export function createEventEmitter() {
    const events = new Map<string, { fn: (payload: any) => any; once: boolean }[]>();

    function on(event: string, listener: (payload: any) => any): number {
        let list = events.get(event);
        if (!list) {
            list = [];
            events.set(event, list);
        }
        list.push({ fn: listener, once: false });
        return list.length;
    }

    function once(event: string, listener: (payload: any) => any): number {
        let list = events.get(event);
        if (!list) {
            list = [];
            events.set(event, list);
        }
        list.push({ fn: listener, once: true });
        return list.length;
    }

    function off(event: string, listener: (payload: any) => any): boolean {
        const list = events.get(event);
        if (!list) return false;
        for (let i = 0; i < list.length; i++) {
            if (list[i].fn === listener) {
                list.splice(i, 1);
                return true;
            }
        }
        return false;
    }

    function emit(event: string, payload: any): any[] {
        const list = events.get(event);
        if (!list) return [];
        const results: any[] = [];
        for (const listenerObj of [...list]) {
            results.push(listenerObj.fn(payload));
            if (listenerObj.once) {
                const idx = list.findIndex(l => l.fn === listenerObj.fn && l.once);
                if (idx !== -1) {
                    list.splice(idx, 1);
                }
            }
        }
        return results;
    }

    function listenerCount(event: string): number {
        const list = events.get(event);
        return list ? list.length : 0;
    }

    return { on, once, off, emit, listenerCount };
}

export function createEventEmitter(): EventEmitter

type Listener = (payload: unknown) => unknown

interface EventEmitter {
  on(event: string, listener: Listener): number
  once(event: string, listener: Listener): number
  off(event: string, listener: Listener): boolean
  emit(event: string, payload: unknown): unknown[]
  listenerCount(event: string): number
}

export function createEventEmitter(): EventEmitter {
  const listeners = new Map<string, { fn: Listener; once: boolean }[]>();

  return {
    on(event: string, listener: Listener): number {
      if (!listeners.has(event)) {
        listeners.set(event, []);
      }
      listeners.get(event)!.push({ fn: listener, once: false });
      return this.listenerCount(event);
    },
    once(event: string, listener: Listener): number {
      if (!listeners.has(event)) {
        listeners.set(event, []);
      }
      listeners.get(event)!.push({ fn: listener, once: true });
      return this.listenerCount(event);
    },
    off(event: string, listener: Listener): boolean {
      const arr = listeners.get(event);
      if (!arr) return false;
      for (let i = 0; i < arr.length; i++) {
        if (arr[i].fn === listener) {
          arr.splice(i, 1);
          return true;
        }
      }
      return false;
    },
    emit(event: string, payload: unknown): unknown[] {
      const arr = listeners.get(event);
      if (!arr) return [];
      const results: unknown[] = [];
      for (let i = 0; i < arr.length; i++) {
        const obj = arr[i];
        results.push(obj.fn(payload));
        if (obj.once) {
          arr.splice(i, 1);
        }
      }
      if ((arr as any).length === 0) {
        listeners.delete(event);
      }
      return results;
    },
    listenerCount(event: string): number {
      const arr = listeners.get(event);
      return arr ? arr.length : 0;
    },
  };
}

export function createRateLimiter() {
  const map = new Map<string, {remaining:number,start:number}>();
  return {
    allow(key:string,nowMs:number):boolean{
      let state=map.get(key);
      if(!state){
        state={remaining:3,start:nowMs};
        map.set(key,state);
      }else if(nowMs-state.start>=1000){
        state.start=nowMs;
        state.remaining=3;
      }
      if(state.remaining>0){
        state.remaining--;
        return true;
      }
      return false;
    },
    remaining(key:string,nowMs:number):number{
      let state=map.get(key);
      if(!state){
        return 3;
      }else if(nowMs-state.start>=1000){
        state.start=nowMs;
        state.remaining=3;
      }
      return Math.max(state.remaining,0);
    },
    reset(key:string):void{
      map.delete(key);
    }
  };
}

export function createRateLimiter(): RateLimiter {
  const limit = 3;
  const windowMs = 1000;
  const store = new Map<string,{start:number, remaining:number}>();

  return {
    allow(key:string, nowMs:number): boolean {
      let entry = store.get(key);
      const now = nowMs;

      if (!entry) {
        entry = { start: now, remaining: limit };
        store.set(key, entry);
      } else {
        if (now - entry.start >= windowMs) {
          entry.start = now;
          entry.remaining = limit;
        }
      }

      if (entry.remaining > 0) {
        entry.remaining--;
        return true;
      }
      return false;
    },
    remaining(key:string, nowMs:number): number {
      let entry = store.get(key);
      const now = nowMs;

      if (!entry) {
        return limit;
      }

      if (now - entry.start >= windowMs) {
        entry.start = now;
        entry.remaining = limit;
      }

      return Math.max(entry.remaining, 0);
    },
    reset(key:string): void {
      store.delete(key);
    },
  };
}

interface RateLimiter {
  allow(key: string, nowMs: number): boolean;
  remaining(key: string, nowMs: number): number;
  reset(key: string): void;
}

