export function createEventEmitter() {
  type Listener = (payload: any) => any;
  interface ListenerEntry {
    fn: Listener;
    once: boolean;
  }
  const registry = new Map<string | symbol, ListenerEntry[]>();

  return {
    on(event: string | symbol, listener: Listener): number {
      let list = registry.get(event);
      if (!list) {
        list = [];
        registry.set(event, list);
      }
      list.push({ fn: listener, once: false });
      return list.length;
    },

    once(event: string | symbol, listener: Listener): number {
      let list = registry.get(event);
      if (!list) {
        list = [];
        registry.set(event, list);
      }
      list.push({ fn: listener, once: true });
      return list.length;
    },

    off(event: string | symbol, listener: Listener): boolean {
      const list = registry.get(event);
      if (!list) return false;
      const index = list.findIndex((item) => item.fn === listener);
      if (index !== -1) {
        list.splice(index, 1);
        return true;
      }
      return false;
    },

    emit(event: string | symbol, payload: any): any[] {
      const list = registry.get(event);
      if (!list) return [];
      const results: any[] = [];
      const snapshot = [...list];
      for (const item of snapshot) {
        if (list.includes(item)) {
          results.push(item.fn(payload));
          if (item.once) {
            const idx = list.indexOf(item);
            if (idx !== -1) {
              list.splice(idx, 1);
            }
          }
        }
      }
      return results;
    },

    listenerCount(event: string | symbol): number {
      return registry.get(event)?.length ?? 0;
    },
  };
}
