type Listener = (payload: unknown) => unknown

interface EventEmitter {
  on(event: string, listener: Listener): number
  once(event: string, listener: Listener): number
  off(event: string, listener: Listener): boolean
  emit(event: string, payload: unknown): unknown[]
  listenerCount(event: string): number
}

export function createEventEmitter(): EventEmitter {
  const events = new Map<string, Array<{ fn: Listener; once: boolean }>>();

  return {
    on(event, listener) {
      if (!events.has(event)) {
        events.set(event, []);
      }
      const list = events.get(event)!;
      list.push({ fn: listener, once: false });
      return list.length;
    },

    once(event, listener) {
      if (!events.has(event)) {
        events.set(event, []);
      }
      const list = events.get(event)!;
      list.push({ fn: listener, once: true });
      return list.length;
    },

    off(event, listener) {
      const list = events.get(event);
      if (!list) return false;
      const index = list.findIndex((item) => item.fn === listener);
      if (index !== -1) {
        list.splice(index, 1);
        return true;
      }
      return false;
    },

    emit(event, payload) {
      const list = events.get(event);
      if (!list) return [];

      const results: unknown[] = [];
      // Snapshot of listeners at the time of emission to preserve order and stability
      const itemsToProcess = [...list];

      for (const item of itemsToProcess) {
        // Check if the listener is still registered (not removed by a previous listener in this loop)
        const indexInOriginal = list.indexOf(item);
        if (indexInOriginal !== -1) {
          results.push(item.fn(payload));
          if (item.once) {
            list.splice(indexInOriginal, 1);
          }
        }
      }

      return results;
    },

    listenerCount(event) {
      return events.get(event)?.length || 0;
    },
  };
}

