export function createRateLimiter() {
  interface RateLimiter {
    allow(key: string, nowMs: number): boolean;
    remaining(key: string, nowMs: number): number;
    reset(key: string): void;
  }

  interface WindowState {
    windowStart: number;
    count: number;
  }

  const windows = new Map<string, WindowState>();
  const LIMIT = 3;
  const DURATION = 1000;

  return {
    allow(key: string, nowMs: number): boolean {
      const state = windows.get(key);

      if (!state || nowMs >= state.windowStart + DURATION) {
        windows.set(key, { windowStart: nowMs, count: 1 });
        return true;
      }

      if (state.count < LIMIT) {
        state.count++;
        return true;
      }

      return false;
    },

    remaining(key: string, nowMs: number): number {
      const state = windows.get(key);

      if (!state || nowMs >= state.windowStart + DURATION) {
        return LIMIT;
      }

      return Math.max(0, LIMIT - state.count);
    },

    reset(key: string): void {
      windows.delete(key);
    },
  } as RateLimiter;
}
