type Listener = (payload: unknown) => unknown

interface EventEmitter {
  on(event: string, listener: Listener): number
  once(event: string, listener: Listener): number
  off(event: string, listener: Listener): boolean
  emit(event: string, payload: unknown): unknown[]
  listenerCount(event: string): number
}

export function createEventEmitter(): EventEmitter {
  const eventMap = new Map<string, Array<{
    fn: Listener;
    isOnce: boolean;
  }>>();

  return {
    on(event: string, listener: Listener): number {
      const listeners = eventMap.get(event) || [];
      listeners.push({ fn: listener, isOnce: false });
      eventMap.set(event, listeners);
      return listeners.length;
    },

    once(event: string, listener: Listener): number {
      const listeners = eventMap.get(event) || [];
      listeners.push({ fn: listener, isOnce: true });
      eventMap.set(event, listeners);
      return listeners.length;
    },

    off(event: string, listener: Listener): boolean {
      const listeners = eventMap.get(event);
      if (!listeners) return false;

      const index = listeners.findIndex(l => l.fn === listener);
      if (index === -1) return false;

      listeners.splice(index, 1);
      if (listeners.length === 0) {
        eventMap.delete(event);
      }
      return true;
    },

    emit(event: string, payload: unknown): unknown[] {
      const listeners = eventMap.get(event);
      if (!listeners) return [];

      const results: unknown[] = [];
      const remainingListeners: Array<{ fn: Listener; isOnce: boolean }> = [];

      for (const entry of listeners) {
        results.push(entry.fn(payload));
        if (!entry.isOnce) {
          remainingListeners.push(entry);
        }
      }

      if (remainingListeners.length === 0) {
        eventMap.delete(event);
      } else {
        eventMap.set(event, remainingListeners);
      }

      return results;
    },

    listenerCount(event: string): number {
      return eventMap.get(event)?.length || 0;
    }
  };
}
