interface RateLimiter {
  allow(key: string, nowMs: number): boolean
  remaining(key: string, nowMs: number): number
  reset(key: string): void
}

interface KeyState {
  windowStart: number
  count: number
}

export function createRateLimiter(): RateLimiter {
  const limit = 3
  const windowMs = 1000
  const state = new Map<string, KeyState>()

  const getOrUpdateState = (key: string, nowMs: number): KeyState => {
    let current = state.get(key)

    if (!current || nowMs - current.windowStart >= windowMs) {
      current = {
        windowStart: nowMs,
        count: 0
      }
      state.set(key, current)
    }

    return current
  }

  return {
    allow(key: string, nowMs: number): boolean {
      const current = getOrUpdateState(key, nowMs)
      if (current.count < limit) {
        current.count++
        return true
      }
      return false
    },

    remaining(key: string, nowMs: number): number {
      const current = state.get(key)
      if (!current || nowMs - current.windowStart >= windowMs) {
        return limit
      }
      return Math.max(0, limit - current.count)
    },

    reset(key: string): void {
      state.delete(key)
    }
  }
}
