type Listener = (payload: unknown) => unknown

interface EventEmitter {
  on(event: string, listener: Listener): number
  once(event: string, listener: Listener): number
  off(event: string, listener: Listener): boolean
  emit(event: string, payload: unknown): unknown[]
  listenerCount(event: string): number
}

export function createEventEmitter(): EventEmitter {
  const events = new Map<string, Array<{ fn: Listener; once: boolean }>>();

  return {
    on(event, listener) {
      let listeners = events.get(event);
      if (!listeners) {
        listeners = [];
        events.set(event, listeners);
      }
      listeners.push({ fn: listener, once: false });
      return listeners.length;
    },

    once(event, listener) {
      let listeners = events.get(event);
      if (!listeners) {
        listeners = [];
        events.set(event, listeners);
      }
      listeners.push({ fn: listener, once: true });
      return listeners.length;
    },

    off(event, listener) {
      const listeners = events.get(event);
      if (!listeners) return false;
      const index = listeners.findIndex((l) => l.fn === listener);
      if (index !== -1) {
        listeners.splice(index, 1);
        return true;
      }
      return false;
    },

    emit(event, payload) {
      const listeners = events.get(event);
      if (!listeners) return [];

      const snapshot = [...listeners];
      const results: unknown[] = [];

      for (const listener of snapshot) {
        results.push(listener.fn(payload));
        if (listener.once) {
          const index = listeners.indexOf(listener);
          if (index !== -1) {
            listeners.splice(index, 1);
          }
        }
      }
      return results;
    },

    listenerCount(event) {
      const listeners = events.get(event);
      return listeners ? listeners.length : 0;
    },
  };
}

