export function createRateLimiter() {
  const storage = new Map<string, { windowStart: number; count: number }>();
  const WINDOW_SIZE_MS = 1000;
  const MAX_REQUESTS = 3;

  const updateWindow = (key: string, nowMs: number) => {
    const state = storage.get(key);
    if (!state || nowMs >= state.windowStart + WINDOW_SIZE_MS) {
      storage.set(key, { windowStart: nowMs, count: 0 });
    }
  };

  return {
    allow(key: string, nowMs: number): boolean {
      updateWindow(key, nowMs);
      const state = storage.get(key)!;
      if (state.count < MAX_REQUESTS) {
        state.count++;
        return true;
      }
      return false;
    },

    remaining(key: string, nowMs: number): number {
      updateWindow(key, nowMs);
      const state = storage.get(key)!;
      return Math.max(0, MAX_REQUESTS - state.count);
    },

    reset(key: string): void {
      storage.delete(key);
    },
  };
}
