  count: number
}

export function createRateLimiter(): RateLimiter {
  const limit = 3
  const windowMs = 1000
  const stores = new Map<string, RateLimitState>()

  return {
    allow(key, nowMs) {
      const state = stores.get(key)

      if (!state || nowMs - state.windowStart >= windowMs) {
        stores.set(key, { windowStart: nowMs, count: 1 })
        return true
      }

      if (state.count < limit) {
        state.count++
        return true
      }

      return false
    },

    remaining(key, nowMs) {
      const state = stores.get(key)

      if (!state || nowMs - state.windowStart >= windowMs) {
        return limit
      }

      return Math.max(0, limit - state.count)
    },

    reset(key) {
      stores.delete(key)
    }
  }
}

