class RateLimiterState {
    constructor(private timestamps: number[]) {}

    // Filters timestamps to keep only those within the current 1000ms window
    private getWindowRequests(nowMs: number): number[] {
        const windowStart = nowMs - 1000;
        // Filter out timestamps older than the window start
        return this.timestamps.filter(t => t >= windowStart);
    }

    // Checks if a request is allowed based on the current window count
    public allow(nowMs: number): boolean {
        const recentRequests = this.getWindowRequests(nowMs);
        if (recentRequests.length < 3) {
            // Request is allowed. Record the new request time.
            this.timestamps.push(nowMs);
            return true;
        }
        return false;
    }

    // Calculates the number of requests currently valid in the window
    public getCount(nowMs: number): number {
        const recentRequests = this.getWindowRequests(nowMs);
        return recentRequests.length;
    }

    // Calculates remaining capacity
    public remaining(nowMs: number): number {
        const count = this.getCount(nowMs);
        return 3 - count;
    }

    // Clears all state for this key
    public clear(): void {
        this.timestamps = [];
    }
}

export function createRateLimiter(): {
    allow: (key: string, nowMs: number) => boolean;
    remaining: (key: string, nowMs: number) => number;
    reset: (key: string) => void;
} {
    const store = new Map<string, RateLimiterState>();

    return {
        /**
         * Checks if a request for a key is allowed. If allowed, updates the state.
         */
        allow(key: string, nowMs: number): boolean {
            if (!store.has(key)) {
                const state = new RateLimiterState([]);
                store.set(key, state);
            }

            const state = store.get(key)!;

            if (state.allow(nowMs)) {
                // If allowed, ensure the state object is updated (it is handled internally by allow)
                // No need to explicitly set state back, as state is a reference.
                return true;
            }
            return false;
        },

        /**
         * Checks the remaining capacity for a key.
         */
        remaining(key: string, nowMs: number): number {
            if (!store.has(key)) {
                return 3; // Unlimited if no limits are set
            }
            const state = store.get(key)!;
            return state.remaining(nowMs);
        },

        /**
         * Resets the rate limiting state for a specific key.
         */
        reset(key: string): void {
            store.delete(key);
        }
    };
