export function createRateLimiter(): RateLimiter {
  const LIMIT = 3;
  const WINDOW_MS = 1000;

  const store = new Map<string, { windowStart: number, remaining: number }>();

  const allow = (key: string, nowMs: number): boolean => {
    let entry = store.get(key);

    if (!entry) {
      // First call for this key: start a new window
      store.set(key, { windowStart: nowMs, remaining: LIMIT });
      return true;
    }

    // Check if the current window has expired
    if (nowMs - entry.windowStart >= WINDOW_MS) {
      // Window expired, reset the quota
      entry.windowStart = nowMs;
      entry.remaining = LIMIT;
    }

    // Check remaining allowance
    if (entry.remaining > 0) {
      entry.remaining--;
      return true;
    }

    return false;
  };

  const remaining = (key: string, nowMs: number): number => {
    const entry = store.get(key);

    if (!entry) {
      // If no state exists, assume full allowance (or infinite if no hard limit existed, but here we assume the limit applies to the window)
      return LIMIT;
    }

    // Check if the window is expired
    if (nowMs - entry.windowStart >= WINDOW_MS) {
      return LIMIT;
    }

    return entry.remaining;
  };

  const reset = (key: string): void => {
    store.delete(key);
  };

  return {
    allow,
    remaining,
    reset,
  } as RateLimiter;
}

