        const todoIndex = todos.findIndex(t => t.id === id);
        if (todoIndex !== -1) {
            todos[todoIndex].completed = !todos[todoIndex].completed;
        }
    }

    function deleteTodo(id: number): boolean {
        const todoIndex = todos.findIndex(t => t.id === id);
        if (todoIndex !== -1) {
            // Remove the item by splicing, ensuring IDs are not reused (though we use nextId for insertion)
            todos.splice(todoIndex, 1);
            return true;
        }
        return false;
    }

    function listTodos(): Array<{ id: number, text: string, completed: boolean }> {
        return todos;
    }

    function listCompleted(): Array<{ id: number, text: string, completed: boolean }> {
        return todos.filter(t => t.completed);
    }

    function listPending(): Array<{ id: number, text: string, completed: boolean }> {
        return todos.filter(t => !t.completed);
    }

    function clearCompleted(): void {
        // Filter out completed items
        todos = todos.filter(t => !t.completed);
    }

