  interface Todo {
    id: number
    text: string
    completed: boolean
  }

  interface TodoApp {
    addTodo(text: string): Todo
    getTodo(id: number): Todo | undefined
    toggleTodo(id: number): void
    deleteTodo(id: number): boolean
    listTodos(): Todo[]
    listCompleted(): Todo[]
    listPending(): Todo[]
    clearCompleted(): void
  }

  const todos: Todo[] = []
  let nextId: number = 1

  const addTodo = (text: string): Todo => {
    const newTodo: Todo = {
      id: nextId++,
      text: text,
      completed: false,
    }
    todos.push(newTodo)
    return newTodo
  }

  const getTodo = (id: number): Todo | undefined => {
    const index = todos.findIndex((todo) => todo.id === id)
    if (index !== -1) {
      return todos[index]
    }
    return undefined
  }

  const toggleTodo = (id: number): void => {
    const index = todos.findIndex((todo) => todo.id === id)
    if (index !== -1) {
      todos[index].completed = !todos[index].completed
    }
  }

  const deleteTodo = (id: number): boolean => {
    const initialLength = todos.length
    const index = todos.findIndex((todo) => todo.id === id)
    if (index !== -1) {
      todos.splice(index, 1)
      return true
    }
    return false
  }

  const listTodos = (): Todo[] => {
    return todos
  }

  const listCompleted = (): Todo[] => {
    return todos.filter((todo) => todo.completed)
  }

  const listPending = (): Todo[] => {
    return todos.filter((todo) => !todo.completed)
  }

  const clearCompleted = (): void => {
    const pendingTodos = todos.filter((todo) => !todo.completed)
    // Overwrite the array with only pending items, effectively removing completed ones
    // This fulfills the requirement of clearing completed items efficiently.
    todos.length = 0
    todos.push(...pendingTodos)
  }

  return {
    addTodo,
    getTodo,
    toggleTodo,
    deleteTodo,
    listTodos,
    listCompleted,
