export function createTtlCache(): {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void;
  get(key: string, nowMs: number): unknown;
  has(key: string, nowMs: number): boolean;
  delete(key: string): boolean;
  size(nowMs: number): number;
  clear(): void;
} {
  const cache = new Map<string, { value: unknown, expiresAt: number }>();

  /**
   * Sets a value in the cache with an optional Time To Live (TTL).
   * @param key The cache key.
   * @param value The value to store.
   * @param nowMs The current time in milliseconds (deterministic).
   * @param ttlMs The time to live in milliseconds. Defaults to 1000ms if omitted.
   */
  function set(key: string, value: unknown, nowMs: number, ttlMs?: number): void {
    const ttl = ttlMs ?? 1000;
    const expiresAt = nowMs + ttl;
    cache.set(key, { value, expiresAt });
  }

  /**
   * Retrieves the value associated with a key.
   * @param key The cache key.
   * @param nowMs The current time in milliseconds (deterministic).
   * @returns The stored value, or undefined if the entry does not exist or has expired.
   */
  function get(key: string, nowMs: number): unknown {
    const entry = cache.get(key);

    if (!entry) {
      return undefined;
    }

    if (nowMs >= entry.expiresAt) {
      // Entry is expired. We generally do not remove expired entries
      // unless explicitly called by size/get/delete.
      // For get/has, an expired item is effectively not present.
      return undefined;
    }

    return entry.value;
  }

  /**
   * Checks if a key exists and is currently not expired.
   * @param key The cache key.
   * @param nowMs The current time in milliseconds (deterministic).
   * @returns True if the entry exists and is live, false otherwise.
   */
  function has(key: string, nowMs: number): boolean {
    const entry = cache.get(key);

    if (!entry) {
      return false;
    }

    return nowMs < entry.expiresAt;
  }

  /**
   * Removes an entry from the cache.
   * @param key The cache key to delete.
   * @returns True if the entry existed and was removed, false otherwise.
   */
  function deleteKey(key: string): boolean {
    if (!cache.has(key)) {
      return false;
    }
    cache.delete(key);
    return true;
  }

  /**
   * Counts the number of currently live (non-expired) entries.
   * @param nowMs The current time in milliseconds (deterministic).
   * @returns The count of live entries.
   */
  function size(nowMs: number): number {
    let count = 0;
    for (const entry of cache.values()) {
      if (nowMs < entry.expiresAt) {
        count++;
      }
    }
    return count;
  }

  /**
   * Removes all entries from the cache.
   */
  function clear(): void {
    cache.clear();
  }

  return {
    set,
    get,
    has,
    delete: deleteKey,
    size,
    clear,
  };
}

