export function createRateLimiter(
    nowMs: number
): {
    allow: (key: string, nowMs: number) => void;
    remaining: (key: string, nowMs: number) => number;
    reset: (key: string) => void;
} {
    // Stores the timestamps of the last 'maxRequests' successful requests for each key.
    // We'll store timestamps to accurately check the 1000ms window.
    type KeyState = { timestamps: number[] };
    const keyStates = new Map<string, KeyState>();
    const WINDOW_MS = 1000;
    const MAX_REQUESTS_PER_WINDOW = 3;

    const getOrCreateState = (key: string): KeyState => {
        if (!keyStates.has(key)) {
            keyStates.set(key, { timestamps: [] });
        }
        return keyStates.get(key)!;
    };

    /**
     * Checks if a request for the given key at the current time is allowed.
     * Updates the state by recording the request if allowed.
     * @param key The identifier for the key being rate-limited.
     * @param nowMs The current time in milliseconds.
     * @returns True if the request is allowed, false otherwise.
     */
    const allow = (key: string, nowMs: number): void => {
        const state = getOrCreateState(key);
        const windowStartMs = Math.floor(nowMs / WINDOW_MS) * WINDOW_MS;

        // 1. Clean up old timestamps outside the current (and preceding) window
        const windowCutoffMs = nowMs - WINDOW_MS;
        state.timestamps = state.timestamps.filter(ts => ts > windowCutoffMs);

        // 2. Check quota within the current window
        if (state.timestamps.length < MAX_REQUESTS_PER_WINDOW) {
            // Request allowed: Record the current time
            state.timestamps.push(nowMs);
        }
        // If quota is reached, the request is denied, and we do not record the timestamp.
    };

    /**
     * Gets the number of remaining requests for a key.
     * @param key The identifier for the key.
     * @param nowMs The current time in milliseconds.
     * @returns The number of requests remaining in the current window.
     */
    const remaining = (key: string, nowMs: number): number => {
        const state = keyStates.get(key);
        if (!state) {
            return MAX_REQUESTS_PER_WINDOW; // Assume full capacity if never tracked
        }

        const windowStartMs = Math.floor(nowMs / WINDOW_MS) * WINDOW_MS;

        // Clean up old timestamps for accurate count
        state.timestamps = state.timestamps.filter(ts => ts >= windowStartMs);

        return MAX_REQUESTS_PER_WINDOW - state.timestamps.length;
    };

    /**
     * Resets the quota for a specific key.
     * @param key The identifier for the key to reset.
     */
    const reset = (key: string): void => {
        if (keyStates.has(key)) {
            keyStates.get(key)!.timestamps = [];
        }
    };

    return {
        allow,
        remaining,
        reset
    };
}
