const createEventEmitter = () => {
    /**
     * @private
     * Map storing listeners for each event name.
     * Key: event name (string)
     * Value: Array of Listener objects.
     */
    const listeners = new Map<string, Array<{
        listener: (...args: any[]) => void;
        isOnce: boolean;
    }>>();

    /**
     * Adds a normal listener for an event.
     * @param event The name of the event.
     * @param listener The function to execute.
     * @returns The current number of listeners for the event.
     */
    const on = (event: string, listener: (...args: any[]) => void): number => {
        if (!listeners.has(event)) {
            listeners.set(event, []);
        }
        const eventListeners = listeners.get(event)!;
        eventListeners.push({ listener, isOnce: false });
        return eventListeners.length;
    };

    /**
     * Adds a one-time listener for an event.
     * @param event The name of the event.
     * @param listener The function to execute once.
     * @returns The current number of listeners for the event.
     */
    const once = (event: string, listener: (...args: any[]) => void): number => {
        if (!listeners.has(event)) {
            listeners.set(event, []);
        }
        const eventListeners = listeners.get(event)!;
        eventListeners.push({ listener, isOnce: true });
        return eventListeners.length;
    };

