export type Listener = (payload: unknown) => unknown;

interface EventEmitter {
  on(event: string, listener: Listener): number;
  once(event: string, listener: Listener): number;
  off(event: string, listener: Listener): boolean;
  emit(event: string, payload: unknown): unknown[];
  listenerCount(event: string): number;
}

// Internal structure to hold listeners for a single event
type EventListeners = {
  regular: { listener: Listener; count: number }[];
  once: { listener: Listener; count: number }[];
};

function createEventEmitter(): EventEmitter {
  // Map stores event name -> listeners structure
  const events = new Map<string, EventListeners>();

  /**
   * Gets or initializes the listener storage for a given event.
   */
  const getListeners = (event: string): EventListeners => {
    if (!events.has(event)) {
      events.set(event, { regular: [], once: [] });
    }
    return events.get(event)!;
  };

  /**
   * Calculates the total count of listeners for an event.
   */
  const countListeners = (event: string): number => {
    const listeners = events.get(event);
    return listeners ? listeners.regular.length + listeners.once.length : 0;
  };


  /**
   * Adds a regular listener.
   * @param event The name of the event.
   * @param listener The function to call.
   * @returns The new total listener count for this event.
   */
  const on = (event: string, listener: Listener): number => {
    const listeners = getListeners(event);
    listeners.regular.push({ listener, count: 1 });
    return countListeners(event);
  };

  /**
   * Adds a one-time listener.
   * @param event The name of the event.
   * @param listener The function to call.
   * @returns The new total listener count for this event.
   */
  const once = (event: string, listener: Listener): number => {
    const listeners = getListeners(event);
    listeners.once.push({ listener, count: 1 });
    return countListeners(event);
  };

  /**
   * Removes one instance of a given listener function.
   * @param event The name of the event.
   * @param listener The listener function to remove.
   * @returns True if a listener was removed, false otherwise.
   */
  const off = (event: string, listener: Listener): boolean => {
    const listeners = events.get(event);
    if (!listeners) {
      return false;
    }

    // 1. Try removing from regular listeners
    let foundIndex = listeners.regular.findIndex(l => l.listener === listener);
    if (foundIndex !== -1) {
      listeners.regular.splice(foundIndex, 1);
      return true;
    }

    // 2. Try removing from once listeners
    foundIndex = listeners.once.findIndex(l => l.listener === listener);
    if (foundIndex !== -1) {
      listeners.once.splice(foundIndex, 1);
      return true;
    }

    return false;
  };

  /**
   * Invokes all registered listeners for an event.
   * @param event The name of the event.
   * @param payload The data to pass to the listeners.
   * @returns An array containing the return values of all executed listeners.
   */
  const emit = (event: string, payload: unknown): unknown[] => {
    const listeners = events.get(event);
    if (!listeners || (listeners.regular.length === 0 && listeners.once.length === 0)) {
      return [];
    }

    const results: unknown[] = [];

    // 1. Run regular listeners (must iterate over a copy to ensure safety, though JS arrays handle iteration fine)
    const regularListeners = [...listeners.regular];
    for (const { listener } of regularListeners) {
      results.push(listener(payload));
    }

    // 2. Run one-time listeners and remove them immediately after execution
    // Since the definition implies all once listeners fire and then are removed, 
    // we collect the results first and then clear the storage.
    const onceListenersToRun = [...listeners.once];
    for (const { listener } of onceListenersToRun) {
      results.push(listener(payload));
    }

    // Important: Clear all once listeners after emitting
    listeners.once = [];

    return results;
  };

  /**
   * Returns the current count of listeners for a specific event.
   * @param event The name of the event.
   * @returns The number of registered listeners.
   */
  const listenerCount = (event: string): number => {
    return countListeners(event);
  };

  return {
    on,
    once,
    off,
    emit,
    listenerCount,
  };
}

export function createRateLimiter() {
    // State storage: key -> { count: number, windowStartMs: number }
    const quotas = new Map<string, { count: number; windowStartMs: number }>();

    const MAX_REQUESTS = 3;
    const WINDOW_MS = 1000;

    /**
     * Retrieves the state for a given key, enforcing window rollover if elapsed.
     * @param key The identifier key.
     * @param nowMs The current time in milliseconds.
     * @returns The state object for the key.
     */
    const getOrCreateState = (key: string, nowMs: number) => {
        let state = quotas.get(key);

        if (!state) {
            // First request, initialize state
            state = { count: 0, windowStartMs: nowMs };
            quotas.set(key, state);
        } else {
            const elapsedTime = nowMs - state.windowStartMs;

            if (elapsedTime >= WINDOW_MS) {
                // Window elapsed: Reset state entirely
                state = { count: 0, windowStartMs: nowMs };
                quotas.set(key, state);
            }
            // If elapsed time < WINDOW_MS, state remains valid.
        }
        return state;
    };

    /**
     * Checks if a request is allowed for the given key at the current time.
     * Updates the state if allowed.
     * @param key The identifier key.
     * @param nowMs The current time in milliseconds.
     * @returns True if the request is allowed, false otherwise.
     */
    const allow = (key: string, nowMs: number): boolean => {
        // This function handles window rollover internally upon state retrieval.
        let state = getOrCreateState(key, nowMs);

        // If the window just rolled over, we must count the current request.
        if (state.count === 0 && state.windowStartMs === nowMs) {
             // Initial count or rollover occurred. Count is already 0, we are starting the first request.
             state.count = 1;
             return true;
        }

        // Check limits
        if (state.count < MAX_REQUESTS) {
            state.count += 1;
            return true;
        }
        return false;
    };

    /**
     * Calculates the remaining requests for the given key at the current time.
     * Handles window rollover if elapsed.
     * @param key The identifier key.
     * @param nowMs The current time in milliseconds.
     * @returns The number of remaining requests (never negative).
     */
    const remaining = (key: string, nowMs: number): number => {
        let state = quotas.get(key);

        // If the key doesn't exist, it's a fresh window.
        if (!state) {
            return MAX_REQUESTS;
        }

        const elapsedTime = nowMs - state.windowStartMs;

        if (elapsedTime >= WINDOW_MS) {
            // Window elapsed: Reset and return full allowance.
            // Note: We don't actually reset the quota here, but we report the maximum remaining count.
            // The actual quota reset happens when 'allow' is called subsequently.
            return MAX_REQUESTS;
        }

        // Otherwise, calculate remaining count.
        return Math.max(0, MAX_REQUESTS - state.count);
    };

    /**
     * Clears the quota state for a specific key.
     * @param key The identifier key.
     */
    const reset = (key: string): void => {
        quotas.delete(key);
    };

    return {
        allow,
        remaining,
        reset,
    };
}

export function createRateLimiter(): RateLimiter {
  const LIMIT = 3;
  const WINDOW_MS = 1000;
  // Map stores key -> { count: current uses, windowStart: timestamp of window start }
  const rates = new Map<string, { count: number; windowStart: number }>();

  /**
   * Checks if the window for the given key has expired, or if the key is new.
   * If so, it resets the state to a fresh window.
   * @returns {boolean} True if a reset occurred or was needed due to expiry.
   */
  const needsReset = (key: string, nowMs: number): boolean => {
    const state = rates.get(key);

    if (!state) {
      return true;
    }

    return nowMs - state.windowStart >= WINDOW_MS;
  };

  const rateLimiter: RateLimiter = {
    allow(key: string, nowMs: number): boolean {
      if (needsReset(key, nowMs)) {
        // Reset window and allow the first use
        rates.set(key, { count: 1, windowStart: nowMs });
        return true;
      }

      const state = rates.get(key)!;

      if (state.count < LIMIT) {
        // Allowed: increment count
        rates.set(key, { count: state.count + 1, windowStart: state.windowStart });
        return true;
      }

      // Limit reached
      return false;
    },

    remaining(key: string, nowMs: number): number {
      const state = rates.get(key);

      if (!state || needsReset(key, nowMs)) {
        // If key is new or window expired, capacity is full
        return LIMIT;
      }

      // Window active, calculate remaining quota
      return LIMIT - state.count;
    },

    reset(key: string): void {
      rates.delete(key);
    }
  };

  return rateLimiter;
}

