export function createTodoApp() {
    type Todo = { id: number; text: string; completed: boolean };

    // Internal state management
    let todos: Todo[] = [];
    let nextId: number = 1;

    /**
     * Adds a new todo item.
     * @param text The text content of the todo.
     * @returns The full created todo object.
     */
    const addTodo = (text: string): Todo => {
        const newTodo: Todo = { id: nextId++, text, completed: false };
        todos.push(newTodo);
        // Return a shallow copy to prevent external mutation of the internal state
        return { ...newTodo };
    };

    /**
     * Retrieves a todo item by ID.
     * @param id The ID of the todo.
     * @returns The todo object if found, otherwise undefined.
     */
    const getTodo = (id: number): Todo | undefined => {
        return todos.find(todo => todo.id === id);
    };

    /**
     * Toggles the completed status of a todo item.
     * If the ID is missing, it does nothing.
     * @param id The ID of the todo to toggle.
     */
    const toggleTodo = (id: number): void => {
        const index = todos.findIndex(t => t.id === id);
        if (index !== -1) {
            const todo = todos[index];
            // Create a new state object for the modified item
            todos[index] = { ...todo, completed: !todo.completed };
        }
    };

    /**
     * Deletes a todo item by ID.
     * @param id The ID of the todo to delete.
     * @returns True if the todo was found and deleted, false otherwise.
     */
    const deleteTodo = (id: number): boolean => {
        const initialLength = todos.length;
        // Use filtering to create a new array reference for the state
        todos = todos.filter(todo => todo.id !== id);
        return todos.length < initialLength;
    };

    /**
     * Lists all todo items.
     * @returns A copy of the array containing all todos.
     */
    const listTodos = (): Todo[] => {
        return [...todos];
    };

    /**
     * Lists all completed todo items.
     * @returns A copy of the array containing completed todos.
     */
    const listCompleted = (): Todo[] => {
        return todos.filter(todo => todo.completed);
    };

    /**
     * Lists all pending todo items.
     * @returns A copy of the array containing pending todos.
     */
    const listPending = (): Todo[] => {
        return todos.filter(todo => !todo.completed);
    };

    /**
     * Removes all completed todo items from the list.
     */
    const clearCompleted = (): void => {
        // Reassign the todos array to filter out completed items
        todos = todos.filter(todo => !todo.completed);
    };

    return {
        addTodo,
        getTodo,
        toggleTodo,
        deleteTodo,
        listTodos,
        listCompleted,
        listPending,
        clearCompleted,
    };
}

