export function createTtlCache(): {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void
  get(key: string, nowMs: number): unknown
  has(key: string, nowMs: number): boolean
  delete(key: string): boolean
  size(nowMs: number): number
  clear(): void
} {
  /**
   * Internal cache storage: Maps key to { value: unknown, expiresAt: number }
   * expiresAt is the time (in ms) at which the entry becomes invalid.
   */
  const cache = new Map<string, { value: unknown, expiresAt: number }>();

  /**
   * Checks if an entry is expired at the given timestamp.
   * If expired, it removes it from the map.
   * @param key The cache key.
   * @param nowMs The current deterministic timestamp.
   * @returns true if the entry is expired and removed, false otherwise.
   */
  const checkAndCleanup = (key: string, nowMs: number): boolean => {
    const entry = cache.get(key);
    if (entry && nowMs >= entry.expiresAt) {
      cache.delete(key);
      return true;
    }
    return false;
  };

  return {
    /**
     * Sets a key-value pair with an optional Time To Live (TTL).
     * @param key The unique key.
     * @param value The value to store.
     * @param nowMs The current deterministic timestamp.
     * @param ttlMs Optional time in milliseconds until expiration. Defaults to 1000ms.
     */
    set(key: string, value: unknown, nowMs: number, ttlMs?: number): void {
      const ttl = ttlMs === undefined ? 1000 : ttlMs;
      const expiresAt = nowMs + ttl;
      cache.set(key, { value, expiresAt });
    },

    /**
     * Retrieves the value associated with the key if it has not expired.
     * @param key The key to retrieve.
     * @param nowMs The current deterministic timestamp.
     * @returns The value, or undefined if not found or expired.
     */
    get(key: string, nowMs: number): unknown {
      if (!cache.has(key)) {
        return undefined;
      }

      // Clean up if expired
      if (checkAndCleanup(key, nowMs)) {
          return undefined;
      }

      return cache.get(key)!.value;
    },

    /**
     * Checks if the key exists and is currently live.
     * @param key The key to check.
     * @param nowMs The current deterministic timestamp.
     * @returns True if the entry exists and is live, false otherwise.
     */
    has(key: string, nowMs: number): boolean {
      if (!cache.has(key)) {
        return false;
      }

      // Check status and clean up if expired
      if (checkAndCleanup(key, nowMs)) {
          return false;
      }

      return true;
    },

    /**
     * Deletes the specified key if it exists.
     * @param key The key to delete.
     * @returns True if the entry existed and was deleted, false otherwise.
     */
    delete(key: string): boolean {
      if (cache.has(key)) {
        return cache.delete(key);
      }
      return false;
    },

    /**
     * Counts the number of currently live (non-expired) entries at the given timestamp.
     * Note: This performs necessary cleanup of expired entries during counting.
     * @param nowMs The current deterministic timestamp.
     * @returns The count of live entries.
     */
    size(nowMs: number): number {
      let count = 0;
      for (const [key, entry] of cache.entries()) {
        if (nowMs < entry.expiresAt) {
          count++;
        } else {
          // Clean up expired entry while iterating
          cache.delete(key);
        }
      }
      return count;
    },

    /**
     * Clears all entries from the cache.
     */
    clear(): void {
      cache.clear();
    }
  };
}

export function createTtlCache(): TtlCache {
    const DEFAULT_TTL_MS = 1000;

    interface CacheEntry {
        value: unknown;
        expiresAt: number;
    }

    /**
     * @private
     * @type {Map<string, CacheEntry>}
     */
    const store = new Map<string, CacheEntry>();

    /**
     * @private
     * Checks if an entry is expired at the given time.
     * @param entry The cache entry.
     * @param nowMs Current time in milliseconds.
     * @returns True if expired, false otherwise.
     */
    const isExpired = (entry: CacheEntry, nowMs: number): boolean => {
        return nowMs >= entry.expiresAt;
    };

    /**
     * Sets a key-value pair with optional Time-To-Live (TTL).
     * If ttlMs is undefined, the default TTL (1000ms) is used.
     * @param key The cache key.
     * @param value The value to store.
     * @param nowMs The current time in milliseconds (for consistency).
     * @param ttlMs Optional Time-To-Live in milliseconds.
     */
    const set = (key: string, value: unknown, nowMs: number, ttlMs?: number): void => {
        let effectiveTTLMs: number;

        if (typeof ttlMs === 'undefined') {
            effectiveTTLMs = DEFAULT_TTL_MS;
        } else {
            // ttlMs is number type, but it might be passed as 0 or a specific value.
            effectiveTTLMs = ttlMs;
        }

        let expiresAt: number;

        if (effectiveTTLMs === 0) {
            // Immediate expiration
            expiresAt = nowMs;
        } else if (typeof effectiveTTLMs === 'number' && effectiveTTLMs > 0) {
            expiresAt = nowMs + effectiveTTLMs;
        } else {
            // Fallback, though theoretically covered by the undefined/default logic
            expiresAt = nowMs + DEFAULT_TTL_MS;
        }

        store.set(key, { value, expiresAt });
    };

    /**
     * Retrieves a value if it exists and has not expired.
     * @param key The cache key.
     * @param nowMs Current time in milliseconds.
     * @returns The stored value, or undefined/null if expired or not found.
     */
    const get = (key: string, nowMs: number): unknown => {
        const entry = store.get(key);
        if (!entry) {
            return undefined;
        }
        if (isExpired(entry, nowMs)) {
            store.delete(key);
            return undefined;
        }
        return entry.value;
    };

    /**
     * Checks if a key exists and has not expired.
     * @param key The cache key.
     * @param nowMs Current time in milliseconds.
     * @returns True if the entry is present and active, false otherwise.
     */
    const has = (key: string, nowMs: number): boolean => {
        const entry = store.get(key);
        if (!entry) {
            return false;
        }
        if (isExpired(entry, nowMs)) {
            // Clean up expired entries lazily upon access
            store.delete(key);
            return false;
        }
        return true;
    };

    /**
     * Removes a key from the cache.
     * @param key The cache key.
     * @returns True if the entry was deleted, false if the key did not exist.
     */
    const deleteKey = (key: string): boolean => {
        return store.delete(key);
    };

    /**
     * Calculates the number of active (non-expired) entries in the cache.
     * @param nowMs Current time in milliseconds.
     * @returns The count of non-expired entries.
     */
    const size = (nowMs: number): number => {
        let count = 0;
        // Iterate over stored keys and count active entries
        for (const entry of store.values()) {
            if (!isExpired(entry, nowMs)) {
                count++;
            }
        }
        return count;
    };

    /**
     * Clears all entries from the cache.
     */
    const clear = (): void => {
        store.clear();
    };

    // --- Implementation of TtlCache Interface ---

    return {
        set,
        get,
        has,
        delete: deleteKey,
        size,
        clear,
    };
}

