interface Calculator {
  add(n: number): Calculator
  subtract(n: number): Calculator
  multiply(n: number): Calculator
  divide(n: number): Calculator
  clear(): Calculator
  result(): number
  memoryStore(): Calculator
  memoryRecall(): number
  memoryClear(): Calculator
  memoryAdd(): Calculator
}

class CalculatorImpl implements Calculator {
  private _currentValue: number = 0;
  private _memoryValue: number = 0;

  add(n: number): Calculator {
    this._currentValue += n;
    return this;
  }

  subtract(n: number): Calculator {
    this._currentValue -= n;
    return this;
  }

  multiply(n: number): Calculator {
    this._currentValue *= n;
    return this;
  }

  divide(n: number): Calculator {
    if (n === 0) {
      // Mimic calculator behavior by throwing or allowing NaN,
      // but for strict typing, we return the current state/throw.
      throw new Error("Cannot divide by zero");
    }
    this._currentValue /= n;
    return this;
  }

  clear(): Calculator {
    this._currentValue = 0;
    return this;
  }

  result(): number {
    return this._currentValue;
  }

  memoryStore(): Calculator {
    this._memoryValue = this._currentValue;
    return this;
  }

  memoryRecall(): number {
    return this._memoryValue;
  }

  memoryClear(): Calculator {
    this._memoryValue = 0;
    return this;
  }

  memoryAdd(): Calculator {
    this._memoryValue += this._currentValue;
    return this;
  }
}

export function createCalculator(): Calculator {
  return new CalculatorImpl();
}
