        if (nowMs >= windowEndTime) {
            // Window has fully elapsed, report as expired
            return { state: { count: 0, windowStartMs: 0 }, expired: true };
        } else {
            // Window is active
            return { state: { count: currentState.count, windowStartMs: currentState.windowStartMs }, expired: false };
        }
    };

    const limiter = {
        /**
         * Attempts to allow a request for the given key at the specified time.
         * Updates the internal state upon success.
         * @param key The unique key to check.
         * @param nowMs The current deterministic timestamp in milliseconds.
         * @returns True if the request is allowed, false otherwise.
         */
        allow: (key: string, nowMs: number): boolean => {
            const { state: { count: currentCount, windowStartMs: currentWindowStart }, expired } = getWindowState(key, nowMs);

            let nextCount: number;
            let nextWindowStartMs: number;

            if (expired) {
                // Start new window
                nextCount = 1;
                nextWindowStartMs = nowMs;
            } else {
                // Window active
                if (currentCount < CAPACITY) {
                    nextCount = currentCount + 1;
                    nextWindowStartMs = currentWindowStart; // Keep the original window start
                } else {
                    // Limit reached, do not change state
                    return false;
                }
            }

            // Update state only if allowed
            if (nextCount > 0) {
                quotas.set(key, { count: nextCount, windowStartMs: nextWindowStartMs });
                return true;
            }

            return false;
        },

        /**
         * Calculates the remaining quota for the key at the specified time. Does not change state.
         * @param key The unique key to check.
         * @param nowMs The current deterministic timestamp in milliseconds.
         * @returns The number of remaining allowed requests (never < 0).
         */
        remaining: (key: string, nowMs: number): number => {
            const { state, expired } = getWindowState(key, nowMs);

            let remaining: number;
            if (expired) {
                // Fresh window starts, max capacity remains
                remaining = CAPACITY;
            } else {
                // Active window
                const currentCount = state.count;
                remaining = Math.max(0, CAPACITY - currentCount);
            }

            return remaining;
        },

        /**
         * Clears the rate limit state for a specific key.
         * @param key The key to reset.
         */
        reset: (key: string): void => {
            quotas.delete(key);
        }
    };

    return limiter;
}
