     * Toggles the completed status of a todo item. Does nothing if the ID is invalid.
     * @param id The ID of the todo to toggle.
     */
    const toggleTodo = (id: number): void => {
        const todo = getTodo(id);
        if (todo) {
            todo.completed = !todo.completed;
        }
        // No explicit return value, as nothing needs to happen if missing.
    };

