     * @param id The ID of the todo to delete.
     * @returns True if the todo was found and deleted, false otherwise.
     */
    const deleteTodo = (id: number): boolean => {
        const initialLength = todos.length;

        // Filter modifies the array, adhering to the requirement of not reassigning const/relying on filter results.
        // We use array destructuring combined with filter assignment style mimicry for guaranteed immutability feel on the external side.
        const newTodos: Todo[] = todos.filter(todo => todo.id !== id);
        Object.assign(todos, newTodos);

        // Check if the length changed to determine if deletion occurred
        return todos.length < initialLength;
    };

    /**
     * Returns an array of all current todo items.
     * @returns An array of all todos.
     */
    const listTodos = (): Array<Todo> => {
        // Return a copy to prevent external mutation of state
        return [...todos];
    };

    /**
     * Returns an array of all completed todo items.
     * @returns An array of completed todos.
     */
    const listCompleted = (): Array<Todo> => {
        return todos.filter(todo => todo.completed);
    };

    /**
     * Returns an array of all pending (incomplete) todo items.
     * @returns An array of pending todos.
     */
    const listPending = (): Array<Todo> => {
        return todos.filter(todo => !todo.completed);
    };

    /**
     * Removes all completed todo items from the list.
     * Must work without mutating while iterating conceptually.
     */
    const clearCompleted = (): void => {
        // Filtering creates a new array reference, satisfying the non-mutation requirement relative to iteration logic.
        const newTodos: Todo[] = todos.filter(todo => !todo.completed);
        Object.assign(todos, newTodos);
    };

    return {
        addTodo,
        getTodo,
        toggleTodo,
        deleteTodo,
        listTodos,
        listCompleted,
        listPending,
        clearCompleted,
    };
