export function createTtlCache(): {
    set(key: string, value: unknown, nowMs: number, ttlMs?: number): void;
    get(key: string, nowMs: number): unknown;
    has(key: string, nowMs: number): boolean;
    delete(key: string): boolean;
    size(nowMs: number): number;
    clear(): void;
} {
    // Internal cache structure: Map<key, { value: unknown, expiresAt: number }>
    const cache = new Map<string, { value: unknown, expiresAt: number }>();

    /**
     * Sets a key-value pair with an optional Time-To-Live.
     * @param key The cache key.
     * @param value The value to store.
     * @param nowMs The deterministic timestamp for setting the entry.
     * @param ttlMs Optional time-to-live in milliseconds. Defaults to 1000ms.
     */
    const set = (key: string, value: unknown, nowMs: number, ttlMs: number | undefined): void => {
        const defaultTtl = 1000;
        const ttl = ttlMs === undefined ? defaultTtl : ttlMs;
        const expiresAt = nowMs + ttl;

        cache.set(key, { value, expiresAt });
    };

    /**
     * Retrieves a value from the cache if it has not expired.
     * @param key The cache key.
     * @param nowMs The deterministic timestamp to check against expiration.
     * @returns The stored value if live, otherwise undefined.
     */
    const get = (key: string, nowMs: number): unknown => {
        const entry = cache.get(key);
        if (!entry) {
            return undefined;
        }
        if (nowMs >= entry.expiresAt) {
            // Entry is expired, remove it and return undefined
            cache.delete(key);
            return undefined;
        }
        return entry.value;
    };

    /**
     * Checks if a key exists and is currently live.
     * @param key The cache key.
     * @param nowMs The deterministic timestamp to check against expiration.
     * @returns True if the entry exists and is not expired, false otherwise.
     */
    const has = (key: string, nowMs: number): boolean => {
        const entry = cache.get(key);
        if (!entry) {
            return false;
        }
        return nowMs < entry.expiresAt;
    };

    /**
     * Deletes an entry by key if it exists.
     * @param key The cache key to delete.
     * @returns True if the key was present and deleted, false otherwise.
     */
    const deleteKey = (key: string): boolean => {
        if (cache.has(key)) {
            cache.delete(key);
            return true;
        }
        return false;
    };

    /**
     * Counts the number of entries that are currently live (not expired) at the given timestamp.
     * @param nowMs The deterministic timestamp for size calculation.
     * @returns The count of live entries.
     */
    const size = (nowMs: number): number => {
        let count = 0;
        for (const [key, entry] of cache.entries()) {
            if (nowMs < entry.expiresAt) {
                count++;
            }
        }
        return count;
    };

    /**
     * Removes all entries from the cache.
     */
    const clear = (): void => {
        cache.clear();
    };

    return {
        set: (key, value, nowMs, ttlMs) => set(key, value, nowMs, ttlMs),
        get: (key, nowMs) => get(key, nowMs),
        has: (key, nowMs) => has(key, nowMs),
        delete: (key) => deleteKey(key),
        size: (nowMs) => size(nowMs),
        clear: () => clear(),
    };
}
