interface CacheEntry {
    value: unknown;
    expiresAt: number;
}

/**
 * Creates a simple in-memory Time-To-Live (TTL) Cache.
 * TTL values are stored in milliseconds.
 * @returns {TtlCache} An object implementing the TtlCache interface.
 */
export function createTtlCache(): TtlCache {
    const cache = new Map<string, CacheEntry>();
    const DEFAULT_TTL = 1000; // 1000ms default TTL

    const tlc: TtlCache = {
        /**
         * Sets a key-value pair in the cache, overwriting existing entries.
         * @param key The cache key.
         * @param value The value to store. Can be undefined.
         * @param nowMs The current time in milliseconds (for consistent testing/consistency).
         * @param ttlMs Optional Time-To-Live in milliseconds. If 0, item expires immediately.
         */
        set(key: string, value: unknown, nowMs: number, ttlMs?: number): void {
            let effectiveTtl = DEFAULT_TTL;

            if (ttlMs !== undefined) {
                if (ttlMs === 0) {
                    // Immediate expiration means expiresAt <= nowMs
                    effectiveTtl = 0;
                } else {
                    effectiveTtl = ttlMs;
                }
            }

            // Calculate expiration time. Use current time if nowMs is invalid, though consistency demands it's passed.
            const expiryMs = nowMs + effectiveTtl;

            cache.set(key, {
                value: value,
                expiresAt: expiryMs,
            });
        },

        /**
         * Retrieves a value from the cache if it has not expired.
         * @param key The cache key.
         * @param nowMs The current time in milliseconds.
         * @returns The stored value if active, otherwise undefined.
         */
        get(key: string, nowMs: number): unknown {
            const entry = cache.get(key);

            if (!entry) {
                return undefined;
            }

            if (nowMs >= entry.expiresAt) {
                this.delete(key); // Clean up expired entry on access
                return undefined;
            }

            return entry.value;
        },

        /**
         * Checks if a key exists and has not expired.
         * @param key The cache key.
         * @param nowMs The current time in milliseconds.
         * @returns True if the entry exists and is not expired, false otherwise.
         */
        has(key: string, nowMs: number): boolean {
            const entry = cache.get(key);

            if (!entry) {
                return false;
            }

            return nowMs < entry.expiresAt;
        },

        /**
         * Deletes a key from the cache if it exists.
         * @param key The cache key.
         * @returns True if the entry was found and deleted, false otherwise.
         */
        delete(key: string): boolean {
            if (cache.has(key)) {
                // Deleting immediately prevents checking expiry, fulfilling the "delete" action.
                cache.delete(key);
                return true;
            }
            return false;
        },

        /**
         * Counts the number of entries that have not expired as of the given time.
         * @param nowMs The current time in milliseconds.
         * @returns The count of active entries.
         */
        size(nowMs: number): number {
            let count = 0;
            for (const entry of cache.values()) {
                if (nowMs < entry.expiresAt) {
                    count++;
                }
            }
            return count;
        },

        /**
         * Clears all entries from the cache.
         */
        clear(): void {
            cache.clear();
        }
    };

    return tlc;
}

interface TtlCache {
    set(key: string, value: unknown, nowMs: number, ttlMs?: number): void
    get(key: string, nowMs: number): unknown
    has(key: string, nowMs: number): boolean
    delete(key: string): boolean
    size(nowMs: number): number
    clear(): void
}
