export function createCalculator() {
    let currentValue: number = 0;
    let memoryValue: number = 0;

    const calculator = {
        add: (n: number): typeof calculator => {
            currentValue += n;
            return calculator;
        },
        subtract: (n: number): typeof calculator => {
            currentValue -= n;
            return calculator;
        },
        multiply: (n: number): typeof calculator => {
            currentValue *= n;
            return calculator;
        },
        divide: (n: number): typeof calculator => {
            if (n === 0) {
                throw new Error("Division by zero");
            }
            currentValue /= n;
            return calculator;
        },
        clear: (): typeof calculator => {
            currentValue = 0;
            return calculator;
        },
        result: (): number => {
            return currentValue;
        },
        memoryStore: (): typeof calculator => {
            memoryValue = currentValue;
            return calculator;
        },
        memoryAdd: (): typeof calculator => {
            memoryValue += currentValue;
            return calculator;
        },
        memoryClear: (): typeof calculator => {
            memoryValue = 0;
            return calculator;
        },
        memoryRecall: (): number => {
            return memoryValue;
        }
    };
    return calculator;
