interface Calculator {
  add(n: number): Calculator
  subtract(n: number): Calculator
  multiply(n: number): Calculator
  divide(n: number): Calculator
  clear(): Calculator
  result(): number
  memoryStore(): Calculator
  memoryRecall(): number
  memoryClear(): Calculator
  memoryAdd(): Calculator
}

export function createCalculator(): Calculator {
  class CalculatorImpl implements Calculator {
    private currentValue: number = 0;
    private memory: number = 0;

    add(n: number): CalculatorImpl {
      this.currentValue += n;
      return this;
    }

    subtract(n: number): CalculatorImpl {
      this.currentValue -= n;
      return this;
    }

    multiply(n: number): CalculatorImpl {
      this.currentValue *= n;
      return this;
    }

    divide(n: number): CalculatorImpl {
      if (n === 0) {
        throw new Error("Division by zero");
      }
      this.currentValue /= n;
      return this;
    }

    clear(): CalculatorImpl {
      this.currentValue = 0;
      return this;
    }

    result(): number {
      return this.currentValue;
    }

    memoryStore(): CalculatorImpl {
      this.memory = this.currentValue;
      return this;
    }

    memoryRecall(): number {
      return this.memory;
    }

    memoryClear(): CalculatorImpl {
      this.memory = 0;
      return this;
    }

    memoryAdd(): CalculatorImpl {
      this.memory = this.currentValue;
      return this;
    }
  }

  return new CalculatorImpl();
}

