type RateLimiterObject = {
    allow: (key: string, nowMs: number) => boolean;
    remaining: (key: string, nowMs: number) => number;
    reset: (key: string) => void;
};

/**
 * Creates a rate limiter object supporting per-key rate limiting.
 * Policy: 3 requests per 1000ms.
 * @returns {RateLimiterObject} An object with allow, remaining, and reset methods.
 */
export function createRateLimiter(): RateLimiterObject {
    // Map stores state for each key: key -> { count: number, windowStart: number }
    const keyStates = new Map<string, { count: number; windowStart: number }>();

    const MAX_REQUESTS = 3;
    const WINDOW_MS = 1000;

    /**
     * Clears the rate limit state for a specific key.
     */
    const reset = (key: string): void => {
        keyStates.delete(key);
    };

    /**
     * Checks if a request for a given key is allowed at the specified time.
     * Manages window rollover if necessary.
     */
    const allow = (key: string, nowMs: number): boolean => {
        let state = keyStates.get(key);

        if (!state) {
             // First time seeing this key, initialize state
            state = { count: 1, windowStart: nowMs };
            keyStates.set(key, state);
            return true;
        }

        // Check for window expiration (Boundary rule)
        if (nowMs - state.windowStart >= WINDOW_MS) {
            // Window elapsed, reset state
            state = { count: 1, windowStart: nowMs };
            keyStates.set(key, state);
            return true;
        }

        // Window active, check quota
        if (state.count < MAX_REQUESTS) {
            state.count += 1;
            keyStates.set(key, state);
            return true;
        }

        // Quota exceeded
        return false;
    };

    /**
     * Reports the number of remaining requests for a key without consuming one.
     * Triggers window rollover logic implicitly if the window has elapsed, 
     * ensuring remaining count is calculated against the current valid window.
     */
    const remaining = (key: string, nowMs: number): number => {
        const state = keyStates.get(key);

        if (!state) {
            // Key never seen, assumes a fresh window is starting or is starting now
            return MAX_REQUESTS;
        }

        // Check for window expiration (Boundary rule)
        if (nowMs - state.windowStart >= WINDOW_MS) {
            // Window elapsed, reset state for correct calculation
            state = { count: 1, windowStart: nowMs };
            keyStates.set(key, state);
            return MAX_REQUESTS - 1; // Since this call will count as the first
        }

        // Window active
        const remainingCount = Math.max(0, MAX_REQUESTS - state.count);
        return remainingCount;
    };


    return {
        allow,
        remaining,
        reset,
    };
}
