export function createTodoApp(): TodoApp {
  const todos: Todo[] = [];
  let nextId: number = 1;

  /**
   * Adds a new todo item.
   * Returns the newly created Todo object.
   */
  const addTodo = (text: string): Todo => {
    const newTodo: Todo = {
      id: nextId++,
      text: text,
      completed: false,
    };
    todos.push(newTodo);
    return newTodo;
  };

  /**
   * Retrieves a todo item by its ID.
   * Returns the Todo object or undefined if not found.
   */
  const getTodo = (id: number): Todo | undefined => {
    return todos.find(todo => todo.id === id);
  };

  /**
   * Toggles the completion status of a todo item.
   * Does nothing and does not throw if the ID is missing.
   */
  const toggleTodo = (id: number): void => {
    const todo = getTodo(id);
    if (todo) {
      todo.completed = !todo.completed;
    }
  };

  /**
   * Deletes a todo item by ID.
   * Returns true if the item was deleted, false otherwise.
   */
  const deleteTodo = (id: number): boolean => {
    const initialLength = todos.length;
    // Filter creates a new array, satisfying the constraint regarding not mutating/relying on discarded filter results implicitly,
    // although the requirement is to *remove* the ID from future operations, which filtering achieves by creating a new state array reference.
    const newTodos: Todo[] = todos.filter(todo => todo.id !== id);

    if (newTodos.length < initialLength) {
        // Instead of reassigning 'todos' (which might break other internal references if this were a class), 
        // we simulate the removal by ensuring the object reference pointed to by 'todos' 
        // is updated to reflect the removal, although in strict JS module scoping, direct mutation is often expected.
        // Given the constraints, reassigning the captured variable scope 'todos' is the intended pattern for state update.
        todos.length = 0;
        todos.push(...newTodos);
        return true;
    }
    return false;
  };

  /**
   * Lists all todos.
   */
  const listTodos = (): Todo[] => {
    // Must return an array copy to prevent external mutation of internal state
    return [...todos];
  };

  /**
   * Lists all not-yet-completed todos.
   */
  const listPending = (): Todo[] => {
    return todos.filter(todo => !todo.completed);
  };

  /**
   * Lists all completed todos.
   */
  const listCompleted = (): Todo[] => {
    return todos.filter(todo => todo.completed);
  };

  /**
   * Removes all completed todos from the list.
   * Does not mutate while iterating (achieved by filtering).
   */
  const clearCompleted = (): void => {
    const initialLength = todos.length;
    // Use filter to create a new array containing only non-completed items
    // And then reset the 'todos' scope variable reference to enforce the state change.
    const newTodos: Todo[] = todos.filter(todo => !todo.completed);
    todos.length = 0;
    todos.push(...newTodos);
  };

  const api: TodoApp = {
    addTodo,
    getTodo,
    toggleTodo,
    deleteTodo,
    listTodos,
    listCompleted,
    listPending,
    clearCompleted,
  };

  return api;
}
