    type Listener = {
        fn: (...args: any[]) => any;
        once: boolean;
    };

    const events = new Map<string, Listener[]>();

    function on(event: string, listener: (...args: any[]) => any): number {
        const arr = events.get(event) ?? [];
        arr.push({ fn: listener, once: false });
        events.set(event, arr);
        return arr.length;
    }

    function once(event: string, listener: (...args: any[]) => any): number {
        const arr = events.get(event) ?? [];
        arr.push({ fn: listener, once: true });
        events.set(event, arr);
        return arr.length;
    }

    function off(event: string, listener: (...args: any[]) => any): boolean {
        const arr = events.get(event);
        if (!arr) return false;
        const idx = arr.findIndex(entry => entry.fn === listener);
        if (idx === -1) return false;
        arr.splice(idx, 1);
        if (arr.length === 0) events.delete(event);
        return true;
    }

    function emit(event: string, payload?: any): any[] {
        const arr = events.get(event);
        if (!arr) return [];
        const results: any[] = [];
        for (const entry of arr.slice()) {
            results.push(entry.fn(payload));
            if (entry.once) {
                const idx = arr.indexOf(entry);
                if (idx !== -1) arr.splice(idx, 1);
            }
        }
        if (arr.length === 0) events.delete(event);
        return results;
    }

    function listenerCount(event: string): number {
        const arr = events.get(event);
        return arr ? arr.length : 0;
    }

    return { on, once, off, emit, listenerCount };
}

