      if (!list) return false
      const idx = list.findIndex(w => w.listener === listener)
      if (idx === -1) return false
      list.splice(idx, 1)
      if (list.length === 0) this._events.delete(event)
      return true
    }

    emit(event: string, payload: unknown): unknown[] {
      const list = this._events.get(event)
      if (!list) return []
      const results: unknown[] = []
      for (let i = 0; i < list.length; i++) {
        const wrapper = list[i]
        results.push(wrapper.listener(payload))
        if (wrapper.once) {
          list.splice(i, 1)
          i--
        }
      }
      if (list.length === 0) this._events.delete(event)
      return results
    }

    listenerCount(event: string): number {
      const list = this._events.get(event)
      return list ? list.length : 0
    }
  }

  return new Emitter()
}

export function createRateLimiter() {
  const data = new Map<string, { windowStart: number; count: number }>();
  const LIMIT = 3;
  const WINDOW_MS = 1000;

  return {
    allow(key: string, nowMs: number): boolean {
      const state = data.get(key);
      if (!state || nowMs >= state.windowStart + WINDOW_MS) {
        // start a new window
        data.set(key, { windowStart: nowMs, count: 1 });
        return true;
      }
      if (state.count < LIMIT) {
        state.count++;
        return true;
      }
      return false;
    },

    remaining(key: string, nowMs: number): number {
      const state = data.get(key);
      if (!state || nowMs >= state.windowStart + WINDOW_MS) {
        // fresh window, all slots available
        return LIMIT;
      }
      const remaining = LIMIT - state.count;
      return remaining > 0 ? remaining : 0;
    },

    reset(key: string): void {
      data.delete(key);
    },
  };
}

export interface RateLimiter {
  allow(key: string, nowMs: number): boolean
  remaining(key: string, nowMs: number): number
  reset(key: string): void
}

export function createRateLimiter(): RateLimiter {
  const limit = 3
  const windowMs = 1000
  const state = new Map<string, { windowStart: number; count: number }>()

  function getEntry(key: string, nowMs: number) {
    let entry = state.get(key)
    if (!entry) {
      entry = { windowStart: nowMs, count: 0 }
      state.set(key, entry)
    } else if (nowMs - entry.windowStart >= windowMs) {
      entry.windowStart = nowMs
      entry.count = 0
    }
    return entry
  }

  return {
    allow(key: string, nowMs: number): boolean {
      const entry = getEntry(key, nowMs)
      if (entry.count < limit) {
        entry.count++
        return true
      }
      return false
    },

    remaining(key: string, nowMs: number): number {
      const entry = getEntry(key, nowMs)
      const remaining = limit - entry.count
      return remaining > 0 ? remaining : 0
    },

    reset(key: string): void {
      state.delete(key)
    },
  }
}

