export function createCalculator() {
  let current = 0;
  let memory = 0;

  const calc = {
    add(n: number) {
      current += n;
      return calc;
    },
    subtract(n: number) {
      current -= n;
      return calc;
    },
    multiply(n: number) {
      current *= n;
      return calc;
    },
    divide(n: number) {
      if (n === 0) throw new Error("Division by zero");
      current /= n;
      return calc;
    },
    clear() {
      current = 0;
      return calc;
    },
    result() {
      return current;
    },
    memoryStore() {
      memory = current;
      return calc;
    },
    memoryAdd() {
      memory += current;
      return calc;
    },
    memoryClear() {
      memory = 0;
      return calc;
    },
    memoryRecall() {
      return memory;
    }
  };

  return calc;
}

