    state.set(key, { windowStart: now, count: 0 });
  };

  return {
    allow(key: string, nowMs: number): boolean {
      const entry = state.get(key);
      if (!entry || nowMs >= entry.windowStart + WINDOW_MS) {
        startNewWindow(key, nowMs);
        const newEntry = state.get(key)!; // will exist
        newEntry.count++;
        return true;
      }

      if (entry.count < MAX_REQUESTS) {
        entry.count++;
        return true;
      }

      return false;
