    remaining(key: string, nowMs: number): number {
      const entry = state.get(key);
      if (!entry || nowMs >= entry.windowStart + WINDOW_MS) {
        return MAX_REQUESTS;
      }
      const remaining = MAX_REQUESTS - entry.count;
      return remaining >= 0 ? remaining : 0;
    },

    reset(key: string): void {
      state.delete(key);
    },
  };
