export function createEventEmitter() {
    const events = new Map<string, Array<{ fn: (payload: any) => any; once: boolean }>>();

    const add = (event: string, fn: (payload: any) => any, once: boolean): number => {
        const list = events.get(event) ?? [];
        list.push({ fn, once });
        events.set(event, list);
        return list.length;
    };

    const on = (event: string, fn: (payload: any) => any): number => {
        return add(event, fn, false);
    };

    const once = (event: string, fn: (payload: any) => any): number => {
        return add(event, fn, true);
    };

    const off = (event: string, fn: (payload: any) => any): boolean => {
        const list = events.get(event);
        if (!list) return false;
        const idx = list.findIndex(l => l.fn === fn);
        if (idx === -1) return false;
        list.splice(idx, 1);
        if (list.length) {
            events.set(event, list);
        } else {
            events.delete(event);
        }
        return true;
    };

    const listenerCount = (event: string): number => {
        const list = events.get(event);
        return list ? list.length : 0;
    };

    const emit = (event: string, payload: any): any[] => {
        const list = events.get(event);
        if (!list) return [];
        const results: any[] = [];
        // create a copy to avoid issues if array mutates during iteration
        for (const listener of [...list]) {
            results.push(listener.fn(payload));
        }
        // remove once listeners
        const remaining = list.filter(l => !l.once);
        if (remaining.length) {
            events.set(event, remaining);
        } else {
            events.delete(event);
        }
        return results;
    };

    return {
        on,
        once,
        off,
        emit,
        listenerCount,
    };
}

export type Listener = (payload: unknown) => unknown;

export interface EventEmitter {
  on(event: string, listener: Listener): number;
  once(event: string, listener: Listener): number;
  off(event: string, listener: Listener): boolean;
  emit(event: string, payload: unknown): unknown[];
  listenerCount(event: string): number;
}

export function createEventEmitter(): EventEmitter {
  const listeners = new Map<string, Array<{ fn: Listener; once: boolean }>>();

  const getOrCreate = (event: string) => {
    if (!listeners.has(event)) listeners.set(event, []);
    return listeners.get(event)!;
  };

  return {
    on(event, listener) {
      const arr = getOrCreate(event);
      arr.push({ fn: listener, once: false });
      return arr.length;
    },
    once(event, listener) {
      const arr = getOrCreate(event);
      arr.push({ fn: listener, once: true });
      return arr.length;
    },
    off(event, listener) {
      const arr = listeners.get(event);
      if (!arr) return false;
      const idx = arr.findIndex((entry) => entry.fn === listener);
      if (idx === -1) return false;
      arr.splice(idx, 1);
      if (arr.length === 0) listeners.delete(event);
      return true;
    },
    emit(event, payload) {
      const arr = listeners.get(event);
      if (!arr) return [];
      const results: unknown[] = [];
      for (let i = 0; i < arr.length; i++) {
        const { fn, once } = arr[i];
        results.push(fn(payload));
        if (once) {
          arr.splice(i, 1);
          i--;
        }
      }
      if (arr.length === 0) listeners.delete(event);
      return results;
    },
    listenerCount(event) {
      const arr = listeners.get(event);
      return arr ? arr.length : 0;
    },
  };
}

export function createRateLimiter() {
    const MAX_REQUESTS = 3;
    const WINDOW_MS = 1000;
    const state = new Map<string, { windowStart: number; count: number }>();

    function allow(key: string, nowMs: number): boolean {
        const entry = state.get(key);
        if (!entry) {
            state.set(key, { windowStart: nowMs, count: 1 });
            return true;
        }
        if (nowMs >= entry.windowStart + WINDOW_MS) {
            // new window
            entry.windowStart = nowMs;
            entry.count = 1;
            return true;
        } else {
            if (entry.count < MAX_REQUESTS) {
                entry.count += 1;
                return true;
            }
            return false;
        }
    }

    function remaining(key: string, nowMs: number): number {
        const entry = state.get(key);
        if (!entry) return MAX_REQUESTS;
        if (nowMs >= entry.windowStart + WINDOW_MS) return MAX_REQUESTS;
        const remaining = MAX_REQUESTS - entry.count;
        return remaining >= 0 ? remaining : 0;
    }

    function reset(key: string): void {
        state.delete(key);
    }

    return {
        allow,
        remaining,
        reset,
    };
}

export function createRateLimiter(): RateLimiter {
  const limit = 3;
  const windowMs = 1000;
  const store = new Map<string, { count: number; start: number }>();

  return {
    allow(key, nowMs) {
      let entry = store.get(key);
      if (!entry || nowMs - entry.start >= windowMs) {
        // start new window
        entry = { count: 0, start: nowMs };
        store.set(key, entry);
      }
      if (entry.count < limit) {
        entry.count += 1;
        return true;
      }
      return false;
    },

    remaining(key, nowMs) {
      const entry = store.get(key);
      if (!entry || nowMs - entry.start >= windowMs) {
        return limit;
      }
      const remaining = limit - entry.count;
      return remaining > 0 ? remaining : 0;
    },

    reset(key) {
      store.delete(key);
    },
  };
}

