  function purgeIfExpired(key: string, nowMs: number): boolean {
    const entry = store.get(key)
    if (!entry) return false
    if (nowMs >= entry.expiresAt) {
      store.delete(key)
      return false
    }
    return true
  }

  return {
    set(key, value, nowMs, ttlMs) {
      const ttl = ttlMs ?? DEFAULT_TTL_MS
      const expiresAt = nowMs + ttl
      store.set(key, { value, expiresAt })
    },
    get(key, nowMs) {
      if (!purgeIfExpired(key, nowMs)) return undefined
      return store.get(key)!.value
    },
