      const results = [];
      for (const [listener] of listeners.get(event) || []) {
        try {
          const result = listener(payload);
          results.push(result);
        } catch (e) {
          // Ignore unhandled exceptions
        }
      }
      onceListeners.delete(event);
      listeners.set(event, (oldListeners => [...(oldListeners ?? []), listener]).get(event));
