                return listenerCount;
            }).catch(() => {});
            return id();
        },
        off(event: string, listener: Listener): boolean {
            const index = eventListeners[event].indexOf(listener);
            if (index !== -1) {
                eventListeners[event].splice(index, 1);
                return true;
