function createRateLimiter(nowMs) {
  const limitPerWindow = 3;
  const windowDuration = 1000; // ms
  const MAX_WINDOW_SIZE = 15 * windowDuration;

  const keys = {};
  const timestamps = {};

  return {
    allow: (key, nowMs) => {
      if (!keys[key]) {
        keys[key] = [];
        timestamps[key] = nowMs;
        return Infinity;
      }

      let remainingCount = limitPerWindow;
      for (const index of keys[key]) {
        const windowEnd = timestamps[key][index];
        if (windowEnd < nowMs) continue;

        remainingCount -= 1;
      }

      if (remainingCount <= 0) {
        for (let i = 0; i < limitPerWindow - remainingCount; i++) {
          keys[key].push(nowMs);
        }
        timestamps[key] = nowMs;
      } else {
        const firstIndex = keys[key].indexOf(timestamps[key]);
        if (firstIndex !== -1) {
          keys[key][firstIndex] = nowMs;
        } else {
          keys[key].push(nowMs);
        }
        timestamps[key] = nowMs;
      }

      return remainingCount;
    },
    remaining: (key, nowMs) => {
      let remainingCount = limitPerWindow;

      for (const index of keys[key]) {
        const windowEnd = timestamps[key][index];
        if (windowEnd < nowMs) continue;

        remainingCount -= 1;
      }

      return remainingCount > 0 ? limitPerWindow - remainingCount : 0;
    },
    reset: (key) => {
      delete keys[key];
      delete timestamps[key];
    }
  };
}

export function createRateLimiter(): RateLimiter {
    let limit = 3;
    let windowMs = 1000;

    const rateLimiters: { [key: string]: RateLimiter } = {};

    function allow(key: string, nowMs: number): boolean {
        if (!rateLimiters[key]) {
            return true;
        }

        const windowStart = rateLimiters[key].windowStart || Date.now();
        const windowEnd = windowStart + limit * windowMs;

        if (nowMs < windowStart) {
            rateLimiters[key] = { ...rateLimiters[key], windowStart: nowMs };
            return true;
        } else if (nowMs >= windowEnd) {
            rateLimiters[key] = { ...rateLimiters[key], windowStart: Date.now(), remaining: limit };
            return false;
        }

        const remaining = Math.min(rateLimiters[key].remaining, limit);
        rateLimiters[key].remaining -= 1;
        if (remaining === 0) {
            rateLimiters[key] = { ...rateLimiters[key], windowStart: Date.now() };
        }
        return true;
    }

    function remaining(key: string, nowMs: number): number {
        const rateLimiter = rateLimiters[key];
        if (!rateLimiter) {
            throw new Error(`Key ${key} not found`);
        }
        return rateLimiter.remaining || 0;
    }

    function reset(key: string): void {
        delete rateLimiters[key];
    }

    let nextKey = 0;

    function getNewKey(): string {
        if (nextKey >= Math.pow(2, 32)) {
            throw new Error('Max key limit exceeded');
        }
        const newKey = String(nextKey++);
        return newKey;
    }

    return { allow, remaining, reset, getNewKey };
}

