    listCompleted(): Array<{ id: number; text: string; completed: boolean }>,
    listPending(): Array<{ id: number; text: string; completed: boolean }>,
    clearCompleted(): void,
  };

  return {
    addTodo: (text: string) => {
      const todo = { text, completed: false };
      todos[nextId] = todo;
      nextId++;
      return { ...todo };
    },
    getTodo: (id: number): { id: number; text: string; completed: boolean } | undefined => {
      if (Object.keys(todos).includes(id.toString())) {
        return { ...todos[id] };
      }
      return undefined;
    },
    toggleTodo: (id: number) => {
      const todo = todos[id];
      if (todo) {
        todos[id].completed = !todos[id].completed;
      }
    },
    deleteTodo: (id: number): boolean => {
      if (Object.keys(todos).includes(id.toString())) {
        delete todos[id];
        return true;
      }
      return false;
    },
    listTodos: (): Array<{ id: number; text: string; completed: boolean }> =>
      Object.values(todos).map((todo) => ({ ...todo, id: nextId++ })),
    listCompleted: (): Array<{ id: number; text: string; completed: boolean }> =>
      Object.values(todos).filter(({ completed }) => completed),
    listPending: (): Array<{ id: number; text: string; completed: boolean }> =>
      Object.values(todos).filter(({ completed }) => !completed),
    clearCompleted: () => {
      Object.keys(todos).forEach((id) => delete todos[id]);
    },
  };
}

