```typescript
class EventEmitter {
  private listeners = {};
  private listenerCount = {};

  on(event, listener) {
    if (!this.listeners[event]) this.listeners[event] = [];
    this.listeners[event].push(listener);
    this.listenerCount[event] = this.listeners[event].length;
    return this.listenerCount[event];
  }

  once(event, listener) {
    const existingListener = (existingLister, payload) => {
      listener(payload);
      this.off(existingLister, event);
    };
    const listenerCopy = (...args) => listener(args[0]);
    this.on(event, listenerCopy);
    return () => this.off(listenerCopy, event);
  }

  off(event, listener) {
    if (!this.listeners[event]) return false;
    const index = this.listeners[event].indexOf(listener);
    if (index === -1) return false;
    this.listeners[event].splice(index, 1);
    this.listenerCount[event] = this.listeners[event].length;
    return true;
  }

  emit(event, payload) {
    if (!this.listeners[event]) throw new Error(`No listeners for event ${event}`);
    const listenerKeys = Object.keys(this.listeners[event]);
    for (let i = 0; i < listenerKeys.length; i++) {
      const listened = this.listeners[event][listenerKeys[i]];
      const result = listened(payload);
      if (typeof result === 'object' && !Array.isArray(result)) {
        for (const errorKey in result) {
          if (!(errorKey in event)) throw new Error(`Invalid listener output for event ${event}${JSON.stringify(
            Object.defineProperty(result, errorKey, { value: undefined, enumerable: true }).toString(),
          )}`);
        }
      } else if (!Array.isArray(result)) {
        return [result];
      }
    }
    return [];
  }

  listenersCount() {}

  get listenerCount(event?) {}
}

export function createEventEmitter() {
  const eventHandler = new EventEmitter();
  return eventHandler;
}
