export default function createRateLimiter(nowMs: number) {
  const ratelimit = new Map();

  function allow(key: string, nowMs: number): boolean {
    if (!ratelimit.has(key)) {
      ratelimit.set(key, { lastAllowance: 0, windowStartsAt: nowMs });
    }
    const entry = ratelimit.get(key);
    entry.lastAllowance += (nowMs - entry.windowStartsAt) / 1000;
    return entry.lastAllowance < 3 * Math.floor((nowMs - entry.windowStartsAt) / 1000);
  }

  function remaining(key: string, nowMs: number): number {
    if (!ratelimit.has(key)) {
      return Infinity;
    }
    const entry = ratelimit.get(key);
    return 3 * Math.floor(entry.lastAllowance / Math.floor((nowMs - entry.windowStartsAt) / 1000));
  }

  function reset(key: string): void {
    if (ratelimit.has(key)) {
      ratelimit.delete(key);
    }
  }

  return { allow, remaining, reset };
}
