type Calculator = {
    add: (n: number) => Calculator;
    subtract: (n: number) => Calculator;
    multiply: (n: number) => Calculator;
    divide: (n: number) => Calculator;
    clear: () => Calculator;
    result: () => number;
    memoryStore: () => Calculator;
    memoryAdd: () => Calculator;
    memoryClear: () => Calculator;
    memoryRecall: () => number;
};

function createCalculator(): Calculator {
    let currentValue = 0;
    let memoryValue = 0;

    return {
        add(n: number): Calculator {
            currentValue += n;
            return this;
        },
        subtract(n: number): Calculator {
            currentValue -= n;
            return this;
        },
        multiply(n: number): Calculator {
            currentValue *= n;
            return this;
        },
        divide(n: number): Calculator {
            if (n === 0) throw new Error("Division by zero");
            currentValue /= n;
            return this;
        },
        clear(): Calculator {
            currentValue = 0;
            return this;
        },
        result(): number {
            return currentValue;
        },
        memoryStore(): Calculator {
            memoryValue = currentValue;
            return this;
        },
        memoryAdd(): Calculator {
            memoryValue += currentValue;
            return this;
        },
        memoryClear(): Calculator {
            memoryValue = 0;
            return this;
        },
        memoryRecall(): number {
            return memoryValue;
        }
    };
}
