export function createEventEmitter() {
  type Listener = (...args: any[]) => any;
  interface EventListeners {
    [event: string]: {
      permanent: Listener[];
      once: Listener[];
    };
  }

  const listeners: EventListeners = {};
  const oneTimeListeners: Map<any, { listener: Listener; event: string }> = new Map();

  function on<T extends any[]>(event: string, listener: (...args: T) => any): number {
    if (!listeners[event]) listeners[event] = { permanent: [], once: [] };
    listeners[event].permanent.push(listener as Listener);
    return listeners[event].permanent.length;
  }

  function once<T extends any[]>(event: string, listener: (...args: T) => any): number {
    listeners[event] = listeners[event] || { permanent: [], once: [] };
    listeners[event].once.push(listener as Listener);
    return listeners[event].once.length;
  }

  function off<T extends any[]>(event: string, listener: (...args: T) => any): boolean {
    const eventListeners = listeners[event];
    if (!eventListeners) return false;

    // Remove permanent listener
    const permanentIndex = eventListeners.permanent.findIndex(
      l => l === listener as Listener
    );
    if (permanentIndex !== -1) {
      eventListeners.permanent.splice(permanentIndex, 1);
      return true;
    }

    // Remove once listener
    const onceIndex = eventListeners.once.findIndex(l => l === listener as Listener);
    if (onceIndex !== -1) {
      eventListeners.once.splice(onceIndex, 1);
      return true;
    }

    return false;
  }

  function emit<T extends any[], R extends any[]>(
    event: string,
    ...payload: T
  ): R {
    const results: any[] = [];
    const eventListeners = listeners[event];

    if (eventListeners) {
      // Emit permanent listeners
      for (const listener of eventListeners.permanent) {
        results.push(listener(...(payload as any)));
      }

      // Emit once listeners and remove them
      const onceListeners = eventListeners.once;
      for (let i = onceListeners.length - 1; i >= 0; i--) {
        const listener = onceListeners[i];
        results.push(listener(...(payload as any)));
        onceListeners.splice(i, 1);
      }
    }

    return results as unknown as R;
  }

  function listenerCount(event: string): number {
    const eventListeners = listeners[event];
    return (eventListeners ? eventListeners.permanent.length + eventListeners?.once.length : 0);
  }

  return { on, once, off, emit, listenerCount };
}
