interface RateLimiter {
  allow(key: string, nowMs: number): boolean;
  remaining(key: string, nowMs: number): number;
  reset(key: string): void;
}

interface KeyRecord {
  calls: number;
  windowStart: number;
}

export function createRateLimiter(): RateLimiter {
  const records: Map<string, KeyRecord> = new Map();

  return {
    allow(key: string, nowMs: number): boolean {
      const record = records.get(key) || { calls: 0, windowStart: nowMs };
      const remainingWindow = nowMs - record.windowStart;
      const callsInWindow = remainingWindow <= 0 ? 0 : record.calls;

      if (callsInWindow < 3) {
        records.set(key, { calls: callsInWindow + 1, windowStart: nowMs });
        return true;
      }

      records.set(key, { calls: 0, windowStart: nowMs });
      return false;
    },
    remaining(key: string, nowMs: number): number {
      const record = records.get(key);
      if (!record) return 3;

      const remainingWindow = nowMs - record.windowStart;
      if (remainingWindow <= 0) return 3;

      return Math.max(3 - record.calls, 0);
    },
    reset(key: string): void {
      records.delete(key);
    },
  };
}
