export function createEventEmitter() {
    const listeners: Record<string, { listeners: ((...args: any[]) => any)[]; once: boolean }[]> = {};

    const addListener = (event: string, listener: (...args: any[]) => any, isOnce: boolean) => {
        if (!listeners[event]) listeners[event] = [];
        listeners[event].push({ listeners: [listener], once: isOnce });
    };

    const emit = (event: string, payload: any[]) => {
        if (!listeners[event]) return [];
        const results: any[] = [];
        for (const group of listeners[event]) {
            for (const listener of group.listeners) {
                const result = listener(...payload);
                if (result !== undefined) results.push(result);
            }
        }
        return results;
    };

    const listenerCount = (event: string) => {
        return listeners[event]?.reduce((count, group) => count + group.listeners.length, 0) || 0;
    };

    return {
        on(event: string, listener: (...args: any[]) => any): number {
            addListener(event, listener, false);
            return listenerCount(event);
        },
        once(event: string, listener: (...args: any[]) => any): number {
            addListener(event, listener, true);
            return listenerCount(event);
        },
        off(event: string, listener: (...args: any[]) => any): boolean {
            if (!listeners[event]) return false;
            const group = listeners[event].find(group => group.listeners.some(l => l === listener));
            if (!group) return false;
            const index = group.listeners.indexOf(listener);
            if (index === -1) return false;
            group.listeners.splice(index, 1);
            return group.listeners.length > 0;
        },
        emit(event: string, payload: any[]): any[] {
            return emit(event, payload);
        },
        listenerCount(event: string): number {
            return listenerCount(event);
        }
    };
}
