type Listener = (payload: unknown) => unknown;

interface EventEmitter {
  private listeners: Record<string, { listeners: Listener[]; once: boolean }>;
  private eventCount: Record<string, number>;

  constructor();
  on(event: string, listener: Listener): number;
  once(event: string, listener: Listener): number;
  off(event: string, listener: Listener): boolean;
  emit(event: string, payload: unknown): unknown[];
  listenerCount(event: string): number;
}

export function createEventEmitter(): EventEmitter {
  const listeners: Record<string, { listeners: Listener[]; once: boolean }> = {};
  const eventCount: Record<string, number> = {};

  const emit = (event: string, payload: unknown): unknown[] => {
    const eventListeners = listeners[event] || { listeners: [], once: false };
    const result: unknown[] = [];
    for (const listener of eventListeners.listeners) {
      if (listener(payload) !== undefined) {
        result.push(listener(payload));
      }
      if (eventListeners.once) {
        break;
      }
    }
    return result;
  };

  const on = (event: string, listener: Listener): number => {
    if (!listeners[event]) {
      listeners[event] = { listeners: [], once: false };
      eventCount[event] = 0;
    }
    listeners[event].listeners.push(listener);
    eventCount[event]++;
    return eventCount[event];
  };

  const once = (event: string, listener: Listener): number => {
    if (!listeners[event]) {
      listeners[event] = { listeners: [], once: false };
      eventCount[event] = 0;
    }
    listeners[event].once = true;
    listeners[event].listeners.push(listener);
    eventCount[event]++;
    return eventCount[event];
  };

  const off = (event: string, listener: Listener): boolean => {
    if (!listeners[event]) return false;
    const listenersArray = listeners[event].listeners;
    const index = listenersArray.indexOf(listener);
    if (index !== -1) {
      listenersArray.splice(index, 1);
      eventCount[event]--;
      return true;
    }
    return false;
  };

  const listenerCount = (event: string): number => {
    return eventCount[event] || 0;
  };

  return {
    on,
    once,
    off,
    emit,
    listenerCount,
  };
}
