export function createRateLimiter() {
    const rateLimiter: Record<string, { windowStart: number; remaining: number }> = {};

    return {
        allow(key: string, nowMs: number): boolean {
            const windowStart = rateLimiter[key]?.windowStart ?? nowMs;
            const windowEnd = Math.floor(nowMs / 1000) * 1000;
            const windowKey = `${Math.floor(nowMs / 1000)}`;

            if (rateLimiter[key]?.windowStart !== windowKey) {
                rateLimiter[key] = { windowStart: windowKey, remaining: 3 };
            }

            const currentWindow = rateLimiter[key];
            if (currentWindow.remaining <= 0) {
                return false;
            }

            currentWindow.remaining--;
            return true;
        },
        remaining(key: string, nowMs: number): number {
            const windowStart = rateLimiter[key]?.windowStart ?? nowMs;
            const windowKey = `${Math.floor(nowMs / 1000)}`;
            const currentWindow = rateLimiter[key];

            if (currentWindow?.windowStart !== windowKey) {
                return 0;
            }

            return Math.max(0, currentWindow.remaining);
        },
        reset(key: string) {
            rateLimiter[key] = undefined;
        }
    };
}
