type RateLimiterState = {
  windowStart: number;
  count: number;
};

class RateLimiterImpl {
  private state: Map<string, RateLimiterState>;
  private limit: number;
  private windowMs: number;

  constructor(limit: number, windowMs: number) {
    this.state = new Map();
    this.limit = limit;
    this.windowMs = windowMs;
  }

  private getState(key: string): RateLimiterState {
    const state = this.state.get(key);
    if (!state) {
      this.state.set(key, { windowStart: Date.now(), count: 0 });
      return this.state.get(key)!;
    }

    const nowMs = Date.now();
    if (nowMs - state.windowStart >= this.windowMs) {
      this.state.set(key, { windowStart: nowMs, count: 0 });
      return this.state.get(key)!;
    }

    return state;
  }

  allow(key: string, nowMs: number): boolean {
    const state = this.getState(key);
    if (state.count < this.limit) {
      state.count++;
      return true;
    }
    return false;
  }

  remaining(key: string, nowMs: number): number {
    const state = this.getState(key);
    return Math.max(0, this.limit - state.count);
  }

  reset(key: string): void {
    this.state.delete(key);
  }
}

export function createRateLimiter(): RateLimiter {
  return new RateLimiterImpl(3, 1000);
}
