export function createEventEmitter() {
  const listeners: Map<string, { type: 'once' | 'normal'; listeners: NodeJS.ListenerList<Function> }> = new Map();

  const emitListeners = (
    event: string,
    payload: any,
    listenerList: NodeJS.ListenerList<Function>
  ) => {
    listenerList.forEach((listener: Function) => listener(payload));
  };

  return {
    on: (event: string, listener: (...args: any[]) => void) => {
      const entry = listeners.get(event) || {
        listeners: new NodeJS.ListenerList<Function>(),
      };
      entry.listeners.push(listener);
      listeners.set(event, { type: 'normal', listeners: entry.listeners });
      return listeners.get(event)?.listeners.length || 0;
    },

    once: (event: string, listener: (...args: any[]) => void) => {
      const entry = listeners.get(event) || {
        listeners: new NodeJS.ListenerList<Function>(),
      };
      const normalizedEntry = { type: 'once', listeners: entry.listeners };
      listeners.set(event, normalizedEntry);

      const onceListener = (payload: any) => {
        const currentListers = entry.listeners;
        const index = currentListers.lastIndexOf(listener);
        if (index !== -1) currentListers.remove(index);
        listener(payload);
      };

      entry.listeners.push(onceListener);
      return entry.listeners.length;
    },

    off: (event: string, listener: (...args: any[]) => void) => {
      const eventEntry = listeners.get(event);
      if (!eventEntry) return false;

      const targetList = eventEntry.listeners;
      const targetListener = listener as Function;
      const index = targetList.indexOf(targetListener);
      if (index === -1) return false;

      targetList.remove(index);
      listeners.set(event, { type: eventEntry.type, listeners: targetList });
      return true;
    },

    emit: (event: string, payload: any = null) => {
      const entry = listeners.get(event);
      if (!entry) return [];

      const result: any[] = [];
      if (entry.type === 'once') {
        const listeners = entry.listeners;
        listeners.forEach((listener: Function) => {
          listener(payload);
        });
        const currentListeners = listeners.clone(); // Force removing after invoking
        const index = currentListeners.firstIndexOf(listener as Function);
        if (index !== -1) currentListeners.remove(index);
        listeners.set(event, { type: entry.type, listeners: currentListeners });
      } else {
        emitListeners(event, payload as any, entry.listeners);
      }
      return [];
    },

    listenerCount: (event: string) => {
      const entry = listeners.get(event) || { listeners: new NodeJS.ListenerList<Function>() };
      return entry.listeners.length;
    },
  };
}
