type Listener = (payload: unknown) => unknown;

interface EventEmitter {
  on(event: string, listener: Listener): number;
  once(event: string, listener: Listener): number;
  off(event: string, listener: Listener): boolean;
  emit(event: string, payload: unknown): unknown[];
  listenerCount(event: string): number;
}

class SimpleEventEmitter implements EventEmitter {
  private listeners: Record<string, Listener[]> = {};

  on(event: string, listener: Listener): number {
    if (!this.listeners[event]) {
      this.listeners[event] = [];
    }
    this.listeners[event].push(listener);
    return this.listenerCount(event);
  }

  once(event: string, listener: Listener): number {
    const listenerWrapper = (...args: unknown[]) => {
      const result = listener(...args);
      this.off(event, listenerWrapper);
      return result;
    };
    return this.on(event, listenerWrapper as any);
  }

  off(event: string, listener: Listener): boolean {
    const listeners = this.listeners[event];
    if (!listeners) {
      return false;
    }
    const initialCount = listeners.length;
    const idx = listeners.indexOf(listener);
    if (idx !== -1) {
      listeners.splice(idx, 1);
      return true;
    }
    return false;
  }

  emit(event: string, payload: unknown): unknown[] {
    const listeners = this.listeners[event];
    if (!listeners) {
      return [];
    }
    return listeners
      .map(listener => listener(payload))
      .filter(Boolean);
  }

  listenerCount(event: string): number {
    return (this.listeners[event] || []).length;
  }
}

export function createEventEmitter(): EventEmitter {
  return new SimpleEventEmitter();
}
