type Listener = (payload: unknown) => unknown;

interface EventEmitterImpl {
  listeners: Record<string, { func: Listener; once: boolean }[]>;
}

class EventEmitter {
  listeners: Record<string, { func: Listener; once: boolean }[]> = {};

  addListener(
    event: string,
    listener: Listener
  ): void {
    this.listeners[event] = (this.listeners[event] || []).concat([{ func: listener, once: false }]);
  }

  removeOnceListener(
    event: string,
    listener: Listener
  ): boolean {
    const existing = this.listeners[event] || [];
    const filtered = existing.filter((item) => !item.once && item.func === listener);
    if (filtered.length === existing.length) return false;

    this.listeners[event] = existing.map((item) =>
      item.once || filtered.find((item2) => item2.func === listener) ? item : { func: item.func, once: true}
    );
    return true;
  }

  emit(
    event: string,
    payload: unknown
  ): unknown[] {
    const listeners = this.listeners[event] || [];
    const collectedValues: unknown[] = [];

    listeners
      .filter((listenerDef) => !listenerDef.once)
      .forEach((listenerDef) => {
        try {
          captured: collectedValues.push(listenerDef.func(payload));
        } catch (error) {}
      });

    return collectedValues;
  }

  on(event: string, listener: Listener): number {
    this.emit = (newEvent: string, payload: unknown) => {
      this.emit(newEvent, payload);
    };
    this.addListener(event, listener);
    return this.listenerCount(event);
  }

  once(event: string, listener: Listener): number {
    this.addListener(event, listener);
    this.removeOnceListener = this.removeOnceListener.bind(this);
    return this.listenerCount(event);
  }

  listenerCount(event: string): number {
    return (this.listeners[event] || []).length;
  }

  off(event: string, listener: Listener): boolean {
    return this.listeners[event] ?
      (this.removeOnceListener(event, listener) && listenerCount(event) === 0 ? false : true) :
      false;
  }
}

export function createEventEmitter(): EventEmitter {
  const emitter = new EventEmitter();
  return emitter;
}
