export const createRateLimiter = () => {
    const state: Record<string, { windowStartMs: number; count: number }> = {};

    return {
        allow: (key: string, nowMs: number) => {
            const keyState = state[key];
            if (!keyState || nowMs - keyState.windowStartMs >= 1000) {
                state[key] = { windowStartMs: nowMs, count: 0 };
            }
            const currentWindow = state[key];
            if (currentWindow.count < 3) {
                currentWindow.count++;
                return true;
            }
            return false;
        },
        remaining: (key: string, nowMs: number) => {
            const keyState = state[key];
            if (!keyState || nowMs - keyState.windowStartMs >= 1000) {
                return 3;
            }
            return Math.max(0, 3 - keyState.count);
        },
        reset: (key: string) => {
            delete state[key];
        }
    };
};
