export interface TtlCacheEntry {
  value: unknown;
  expiresAt: number;
}

export class TtlCache implements Partial<Record<string, TtlCacheEntry>> {
  private cache: Map<string, TtlCacheEntry> = new Map();

  set(key: string, value: unknown, nowMs: number, ttlMs = 1000): void {
    const expirationTime = nowMs + ttlMs;
    this.cache.set(key, { value, expiresAt: expirationTime });
  }

  get(key: string, nowMs: number): unknown {
    const entry = this.cache.get(key);
    if (entry?.expiresAt <= nowMs) return undefined;
    return entry?.value;
  }

  has(key: string, nowMs: number): boolean {
    const entry = this.cache.get(key);
    return entry?.expiresAt >= nowMs;
  }

  delete(key: string): boolean {
    return this.cache.delete(key) !== undefined;
  }

  clear(): void {
    this.cache.clear();
  }

  private sizeInternal(nowMs: number): number {
    return Array.from(this.cache.values())
      .filter((entry) => entry.expiresAt >= nowMs)
      .length;
  }

  size(nowMs: number): number {
    return this.sizeInternal(nowMs);
  }
}

export function createTtlCache(): TtlCache {
  return new TtlCache();
}
