export function createTtlCache() {
  const cache = new Map<string, { value: unknown; expiresAt: number }>();

  return {
    set(key: string, value: unknown, nowMs: number, ttlMs?: number): void {
      const ttl = ttlMs ?? 1000;
      const expiresAt = nowMs + ttl;
      cache.set(key, { value, expiresAt });
    },

    get(key: string, nowMs: number): unknown {
      const entry = cache.get(key);
      if (!entry) return undefined;
      if (nowMs >= entry.expiresAt) return undefined;
      return entry.value;
    },

    has(key: string, nowMs: number): boolean {
      const entry = cache.get(key);
      return !!entry && nowMs < entry.expiresAt;
    },

    delete(key: string): boolean {
      return cache.delete(key);
    },

    size(nowMs: number): number {
      let count = 0;
      for (const e of cache.values()) {
        if (nowMs < e.expiresAt) count++;
      }
      return count;
    },

    clear(): void {
      cache.clear();
    },
  };
}

interface TtlCache {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void
  get(key: string, nowMs: number): unknown
  has(key: string, nowMs: number): boolean
  delete(key: string): boolean
  size(nowMs: number): number
  clear(): void
}

export function createTtlCache(): TtlCache {
  const defaultTTL = 1000
  const store = new Map<string, { value: unknown; expiresAt: number }>()

  const isExpired = (now: number, expiresAt: number): boolean => now >= expiresAt

  return {
    set(key, value, nowMs, ttlMs) {
      const expiresAt = ttlMs !== undefined ? nowMs + ttlMs : nowMs + defaultTTL
      store.set(key, { value, expiresAt })
    },
    get(key, nowMs) {
      const entry = store.get(key)
      return entry && !isExpired(nowMs, entry.expiresAt) ? entry.value : undefined
    },
    has(key, nowMs) {
      const entry = store.get(key)
      return entry && !isExpired(nowMs, entry.expiresAt)
    },
    delete(key) {
      return store.delete(key)
    },
    size(nowMs) {
      let count = 0
      for (const { expiresAt } of store.values()) {
        if (!isExpired(nowMs, expiresAt)) count++
      }
      return count
    },
    clear() {
      store.clear()
    },
  }
}

