export function createEventEmitter() {
  const listeners = new Map<string, Listener[]>();

  function getOrCreate(event: string): Listener[] {
    let arr = listeners.get(event);
    if (!arr) {
      arr = [];
      listeners.set(event, arr);
    }
    return arr;
  }

  const on = (event: string, listener: (payload: any) => any) => {
    const arr = getOrCreate(event);
    arr.push({ fn: listener, once: false });
    return arr.length;
  };

  const once = (event: string, listener: (payload: any) => any) => {
    const arr = getOrCreate(event);
    arr.push({ fn: listener, once: true });
    return arr.length;
  };

  const off = (event: string, listener: (payload: any) => any) => {
    const arr = listeners.get(event);
    if (!arr) return false;
    for (let i = 0; i < arr.length; i++) {
      if (arr[i].fn === listener) {
        arr.splice(i, 1);
        if (arr.length === 0) {
          listeners.delete(event);
        }
        return true;
      }
    }
    return false;
  };

  const emit = (event: string, payload: any): any[] => {
    const arr = listeners.get(event);
    if (!arr) {
      return [];
    }
    const copy = arr.slice();
    const results: any[] = [];
    for (const { fn, once } of copy) {
      let ret: any;
      try {
        ret = fn(payload);
      } catch {
        // ignore errors
      }
      results.push(ret);
    }
    const filtered = arr.filter(l => !l.once);
    if (filtered.length === 0) {
      listeners.delete(event);
    } else {
      listeners.set(event, filtered);
    }
    return results;
  };

  const listenerCount = (event: string): number => {
    const arr = listeners.get(event);
    return arr ? arr.length : 0;
  };

  return { on, once, off, emit, listenerCount };
}

