export function createRateLimiter(): RateLimiter {
  const LIMIT = 3;
  const WINDOW_MS = 1000;

  const state = new Map<string, { windowStart: number; count: number }>();

  return {
    allow(key: string, nowMs: number): boolean {
      const entry = state.get(key);
      if (!entry) {
        // Fresh key
        state.set(key, { windowStart: nowMs, count: 0 });
        const fresh = state.get(key)!;
        if (fresh.count < LIMIT) {
          fresh.count += 1;
          return true;
        }
        return false;
      }

      if (nowMs - entry.windowStart >= WINDOW_MS) {
        entry.windowStart = nowMs;
        entry.count = 0;
      }

      if (entry.count < LIMIT) {
        entry.count += 1;
        return true;
      }
      return false;
    },

    remaining(key: string, nowMs: number): number {
      let entry = state.get(key);
      if (!entry) {
        return LIMIT;
      }

      if (nowMs - entry.windowStart >= WINDOW_MS) {
        entry.windowStart = nowMs;
        entry.count = 0;
      }

      const remaining = LIMIT - entry.count;
      return remaining > 0 ? remaining : 0;
    },

    reset(key: string): void {
      state.delete(key);
    }
  };
}

