export function createTodoApp(): TodoApp {
  let nextId = 1;
  const todos = new Map<number, Todo>();

  function addTodo(text: string): Todo {
    const todo: Todo = { id: nextId, text, completed: false };
    todos.set(nextId, todo);
    nextId++;
    return todo;
  }

  function getTodo(id: number): Todo | undefined {
    return todos.get(id);
  }

  function toggleTodo(id: number): void {
    const todo = todos.get(id);
    if (todo) {
      todo.completed = !todo.completed;
    }
  }

  function deleteTodo(id: number): boolean {
    return todos.delete(id);
  }

  function listTodos(): Todo[] {
    return Array.from(todos.values());
  }

  function listCompleted(): Todo[] {
    return Array.from(todos.values()).filter(t => t.completed);
  }

  function listPending(): Todo[] {
    return Array.from(todos.values()).filter(t => !t.completed);
  }

  function clearCompleted(): void {
    const ids: number[] = [];
    for (const [id, t] of todos.entries()) {
      if (t.completed) {
        ids.push(id);
      }
    }
    for (const id of ids) {
      todos.delete(id);
    }
  }

  return {
    addTodo,
    getTodo,
    toggleTodo,
    deleteTodo,
    listTodos,
    listCompleted,
    listPending,
    clearCompleted
  };
}

