class TtlCacheImpl implements TtlCache {
  private entries: Map<string, { value: unknown; expiresAt: number }> = new Map()

  private static readonly DEFAULT_TTL_MS = 1000

  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void {
    const ttl = ttlMs !== undefined ? ttlMs : TtlCacheImpl.DEFAULT_TTL_MS
    const expiresAt = ttl === 0 ? nowMs : nowMs + ttl
    this.entries.set(key, { value, expiresAt })
  }

  get(key: string, nowMs: number): unknown {
    const entry = this.entries.get(key)
    if (entry && entry.expiresAt > nowMs) {
      return entry.value
    }
    return undefined
  }

  has(key: string, nowMs: number): boolean {
    const entry = this.entries.get(key)
    return !!entry && entry.expiresAt > nowMs
  }

  delete(key: string): boolean {
    return this.entries.delete(key)
  }

  size(nowMs: number): number {
    let count = 0
    for (const entry of this.entries.values()) {
      if (entry.expiresAt > nowMs) {
        count++
      }
    }
    return count
  }

  clear(): void {
    this.entries.clear()
  }
}

