    on(event, listener) {
      let list = listeners.get(event);
      if (!list) {
        list = [];
        listeners.set(event, list);
      }
      list.push({ fn, once: false });
      return list.length;
    },

    once(event, listener) {
      let list = listeners.get(event);
      if (!list) {
        list = [];
        listeners.set(event, list);
