  const WINDOW = 1000;
  const LIMIT = 3;
  type WindowState = { last: number; count: number };
  const windows = new Map<string, WindowState>();

  const getCurrentWindow = (nowMs: number): number => nowMs - (nowMs % WINDOW);

  return {
    allow(key: string, nowMs: number): boolean {
      const curWindow = getCurrentWindow(nowMs);
      let state = windows.get(key);
      if (!state || state.last !== curWindow) {
        state = { last: curWindow, count: 0 };
        windows.set(key, state);
      }
      if (state.count < LIMIT) {
        state.count += 1;
        windows.set(key, state);
        return true;
      }
      return false;
    },

    remaining(key: string, nowMs: number): number {
      const curWindow = getCurrentWindow(nowMs);
      const state = windows.get(key);
      if (state && state.last === curWindow) {
        const remaining = LIMIT - state.count;
        return remaining > 0 ? remaining : 0;
      }
      return LIMIT;
    },

    reset(key: string): void {
      windows.delete(key);
    },
  };
}

