export function createTodoApp() {
  let nextId = 1;
  const todos: { id: number; text: string; completed: boolean }[] = [];

  const addTodo = (text: string): { id: number; text: string; completed: boolean } => {
    const todo = { id: nextId, text, completed: false };
    todos.push(todo);
    nextId++;
    return todo;
  };

  const getTodo = (id: number): { id: number; text: string; completed: boolean } | undefined => {
    return todos.find(t => t.id === id);
  };

  const toggleTodo = (id: number): void => {
    const todo = todos.find(t => t.id === id);
    if (todo) {
      todo.completed = !todo.completed;
    }
  };

  const deleteTodo = (id: number): boolean => {
    const idx = todos.findIndex(t => t.id === id);
    if (idx === -1) return false;
    todos.splice(idx, 1);
    return true;
  };

  const listTodos = (): { id: number; text: string; completed: boolean }[] => todos;

  const listCompleted = (): { id: number; text: string; completed: boolean }[] => todos.filter(t => t.completed);

  const listPending = (): { id: number; text: string; completed: boolean }[] => todos.filter(t => !t.completed);

  const clearCompleted = (): void => {
    for (let i = todos.length - 1; i >= 0; i--) {
      if (todos[i].completed) {
        todos.splice(i, 1);
      }
    }
  };

  return {
    addTodo,
    getTodo,
    toggleTodo,
    deleteTodo,
    listTodos,
    listCompleted,
    listPending,
    clearCompleted
  };
}

