```
export function createEventEmitter() {
   const listeners = new Map<string, Array<{fn: (payload: any) => any; once: boolean}>>();
   return {
      on(event: string, listener: (payload: any) => any): number {
         if (!listeners.has(event)) {
            listeners.set(event, []);
         }
         const arr = listeners.get(event)!;
         arr.push({ fn: listener, once: false });
         return arr.length;
      },
      once(event: string, listener: (payload: any) => any): number {
         if (!listeners.has(event)) {
            listeners.set(event, []);
         }
         const arr = listeners.get(event)!;
         arr.push({ fn: listener, once: true });
         return arr.length;
      },
      off(event: string, listener: (payload: any) => any): boolean {
         const arr = listeners.get(event);
         if (!arr) return false;
         for (let i = 0; i < arr.length; i++) {
            if (arr[i].fn === listener) {
               arr.splice(i, 1);
               return true;
            }
         }
         return false;
      },
      emit(event: string, payload: any): any[] {
         const arr = listeners.get(event);
         if (!arr) return [];
         const results: any[] = [];
         for (let i = 0; i < arr.length; i++) {
            const entry = arr[i];
            const res = entry.fn(payload);
            results.push(res);
            if (entry.once) {
               arr.splice(i, 1);
               i--;
            }
         }
         return results;
      },
      listenerCount(event: string): number {
         const arr = listeners.get(event);
         return arr ? arr.length : 0;
      }
   };
}
