      // No entry yet, create fresh
      entry = { windowStart: nowMs, remaining: limit };
      state.set(key, entry);
      return entry;
    }
    // If window expired, reset
    if (nowMs - entry.windowStart >= windowMs) {
      entry.windowStart = nowMs;
      entry.remaining = limit;
    }
    return entry;
  }

  const api: RateLimiter = {
    allow(key: string, nowMs: number): boolean {
      const entry = getEntry(key, nowMs);
      if (entry.remaining > 0) {
        entry.remaining -= 1;
        return true;
      }
      return false;
    },
    remaining(key: string, nowMs: number): number {
      const entry = getEntry(key, nowMs);
      return entry.remaining;
    },
    reset(key: string): void {
      state.delete(key);
    },
  };

