export function createEventEmitter() {
  const listeners = new Map<string, { fn: (payload: any) => any; once: boolean }[]>();

  function listenerCount(event: string): number {
    const arr = listeners.get(event);
    return arr ? arr.length : 0;
  }

  const addListener = (event: string, fn: (payload: any) => any, once: boolean): number => {
    let arr = listeners.get(event);
    if (!arr) {
      arr = [];
      listeners.set(event, arr);
    }
    arr.push({ fn, once });
    return arr.length;
  };

  const on = (event: string, fn: (payload: any) => any): number => {
    return addListener(event, fn, false);
  };

  const once = (event: string, fn: (payload: any) => any): number => {
    return addListener(event, fn, true);
  };

  const off = (event: string, fn: (payload: any) => any): boolean => {
    const arr = listeners.get(event);
    if (!arr) return false;
    const index = arr.findIndex(i => i.fn === fn);
    if (index === -1) return false;
    arr.splice(index, 1);
    return true;
  };

  const emit = (event: string, payload: any): any[] => {
    const arr = listeners.get(event);
    if (!arr) return [];
    const results: any[] = [];
    for (const entry of arr) {
      const res = entry.fn(payload);
      results.push(res);
      if (entry.once) {
        const removeIdx = arr.findIndex(i => i.fn === entry.fn);
        if (removeIdx !== -1) {
          arr.splice(removeIdx, 1);
        }
      }
    }
    return results;
  };

  return { on, once, off, emit, listenerCount };
}

