  const windows = new Map<string, Window>();

  return {
    allow(key: string, nowMs: number): boolean {
      let w = windows.get(key);
      if (!w || nowMs >= w.resetAt) {
        w = { count: 0, resetAt: nowMs + 1000 };
        windows.set(key, w);
      }
      if (w.count < 3) {
        w.count += 1;
        return true;
      }
      return false;
