    remaining(key: string, nowMs: number): number {
      const w = windows.get(key);
      if (!w || nowMs >= w.resetAt) return 3;
      const r = 3 - w.count;
      return r > 0 ? r : 0;
    },

    reset(key: string): void {
      windows.delete(key);
    },
  };
