export function createRateLimiter(): RateLimiter {
   const LIMIT = 3;
   const WINDOW_MS = 1000;
   const state = new Map<string, { count: number; windowStart: number }>();

   return {
     allow(key: string, nowMs: number): boolean {
       let entry = state.get(key);
       if (!entry || nowMs - entry.windowStart >= WINDOW_MS) {
         entry = { count: 0, windowStart: nowMs };
         state.set(key, entry);
       }
       if (entry.count < LIMIT) {
         entry.count++;
         return true;
       }
       return false;
     },
     remaining(key: string, nowMs: number): number {
       let entry = state.get(key);
       if (!entry || nowMs - entry.windowStart >= WINDOW_MS) {
         return LIMIT;
       }
       return Math.max(LIMIT - entry.count, 0);
     },
     reset(key: string): void {
       state.delete(key);
     },
   };
}

