export function createEventEmitter() {
    const listeners = {};

    function addListener(event, listener) {
        if (!listeners[event]) {
            listeners[event] = [];
        }
        listeners[event].push(listener);
        return listeners[event].length;
    }

    function removeListener(event, listener) {
        if (listeners[event]) {
            for (let i = 0; i < listeners[event].length; i++) {
                if (listeners[event][i] === listener) {
                    listeners[event].splice(i, 1);
                    return true;
                }
            }
        }
        return false;
    }

    function emit(event, payload) {
        const events = [event];
        let emittedEventCount = 0;

        for (const ev of events) {
            if (!listeners[ev]) continue;

            const responses: any[] = [];

            listeners[ev].forEach(listener => {
                responses.push(listener(payload));
            });

            if (emittedEventCount === 0 && listeners[`${event}.once`]) {
                removeListener(event, listeners[`${event}.once`]);
            }

            emittedEventCount += 1;
        }
        return responses;
    }

    function listenerCount(event) {
        return listeners[event] ? listeners[event].length : 0;
    }

    function on(event: string, listener: Function): number {
        const count = addListener(event, listener);
        return count;
    }

    function once(event: string, listener: Function): number {
        const wrappedOnceListener = (payload) => {
            try {
                emit(`${event}.once`, payload); // Emit a special event to remove this wrapper
                return listener(payload);
            } finally {
                removeListener(`${event}.once`, wrappedOnceListener);
            }
        };
        const count = addListener(event, wrappedOnceListener);
        addListener(`${event}.once`, () => {}); // Ensure the .once event exists before removing it later
        return count;
    }

    function off(event: string, listener?: Function): boolean {
        if (listener === undefined) {
            delete listeners[event];
            return true;
        }
        const removed = removeListener(event, listener);
        if (!removed && event.endsWith('.once')) {
            removeListener(event, () => {});
        }
        return removed;
    }

    return { on, once, off, emit, listenerCount };
}
