function createRateLimiter() {
    const state = new Map<string, [number[], number]>();

    function allow(key: string, nowMs: number) {
        const entry = state.get(key);
        if (!entry || remaining(key, nowMs) === 0) return false;
        entry[1]--;
        if (entry[1] === 0) {
            entry[0].pop();
            while (nowMs - entry[0][0] >= 1000 && entry[0].length > 0) entry[0].shift();
            entry[0].unshift(nowMs);
            entry[1] = Math.min(3, 3 - (entry[0].length - 1));
        }
        return true;
    }

    function remaining(key: string, nowMs: number) {
        const entry = state.get(key);
        if (!entry) return 3;
        let count = Math.max(entry[1], 3 - entry[0].length + 1);
        while (nowMs - entry[0][0] >= 1000 && entry[0].length > 0) {
            entry[0].shift();
            count++;
        }
        return Math.min(count, 3);
    }

    function reset(key: string) {
        state.set(key, [[], 0]);
    }

    return { allow, remaining, reset };
}

