import { createRateLimiter } from './rate-limiter';

const LIMIT = 3;
const WINDOW_MS = 1000;

export function createRateLimiter(): RateLimiter {
  const state: Record<string, number> = {};

  return {
    allow(key, nowMs) {
      if (!state[key]) {
        state[key] = nowMs + WINDOW_MS;
        return true;
      }

      const windowStart = Math.max(state[key], nowMs - WINDOW_MS);
      const remaining = LIMIT - (nowMs >= windowStart ? Math.floor((windowStart + WINDOW_MS - nowMs) / WINDOW_MS) * LIMIT : 0);

      if (remaining > 0) {
        state[key] += WINDOW_MS;
        return true;
      }

      return false;
    },
    remaining(key, nowMs) {
      const windowStart = Math.max(state[key], nowMs - WINDOW_MS);
      const elapsed = Math.floor((nowMs - windowStart) / WINDOW_MS);
      const quotaUsed = Math.min(elapsed, LIMIT);
      const remaining = LIMIT - quotaUsed;

      return Math.max(remaining, 0);
    },
    reset(key) {
      delete state[key];
    }
  };
}

interface RateLimiter {
  allow(key: string, nowMs: number): boolean;
  remaining(key: string, nowMs: number): number;
  reset(key: string): void;
}
