        if (currentValue === 0) {
            throw new Error("Cannot set value to 0");
        } else if (n === 0) {
            throw new Error("Division by zero is undefined and cannot be performed.");
        }
        currentValue /= n;
        return { add, subtract, multiply, divide, clear, result, memoryStore, memoryAdd, memoryRecall, memoryClear };
    };

    const clear = (): Calculator => {
        currentValue = 0;
        return { add, subtract, multiply, divide, clear, result, memoryStore, memoryAdd, memoryRecall, memoryClear };
    };

    const result = (): number => currentValue;

    const memoryStore = (): Calculator => {
        memoryValue = currentValue;
        return { add, subtract, multiply, divide, clear, result, memoryStore, memoryAdd, memoryRecall, memoryClear };
    };

    const memoryAdd = (): Calculator => {
        if (currentValue === 0) { // Add to zero clears the memory.
            memoryValue = 0;
        } else {
            memoryValue += currentValue;
        }
        return { add, subtract, multiply, divide, clear, result, memoryStore, memoryAdd, memoryRecall, memoryClear };
    };

