export function createCalculator(): Calculator {
  let currentValue = 0;
  let memoryValue = 0;

  const calculate = (operation: 'add' | 'subtract' | 'multiply' | 'divide', n: number): Calculator => {
    switch (operation) {
      case 'add':
        currentValue += n;
        break;
      case 'subtract':
        currentValue -= n;
        break;
      case 'multiply':
        currentValue *= n;
        break;
      case 'divide':
        if (n === 0) throw new Error("Division by zero is not allowed");
        currentValue /= n;
        break;
    }
    return calculator;
  };

  const calculator: Calculator = {
    add(n): Calculator { return calculate('add', n); },
    subtract(n): Calculator { return calculate('subtract', n); },
    multiply(n): Calculator { return calculate('multiply', n); },
    divide(n): Calculator { return calculate('divide', n); },
    clear(): Calculator {
      currentValue = 0;
      return calculator;
    },
    result(): number {
      return currentValue;
    },
    memoryStore(): Calculator {
      memoryValue = currentValue;
      return calculator;
    },
    memoryRecall(): number {
      return memoryValue;
    },
    memoryClear(): Calculator {
      memoryValue = 0;
      return calculator;
    },
    memoryAdd(): Calculator {
      memoryValue += currentValue;
      return calculator;
    }
  };

  return calculator;
}

interface Calculator {
  add(n: number): Calculator
  subtract(n: number): Calculator
  multiply(n: number): Calculator
  divide(n: number): Calculator
  clear(): Calculator
  result(): number
  memoryStore(): Calculator
