export function createRateLimiter(): {
    allow: (key: string, nowMs: number) => boolean;
    remaining: (key: string, nowMs: number) => number;
    reset: (key: string) => void;
} {
    const quotas = new Map<string, { lastReset: number; currentQuota: number }>();

    return {
        allow(key: string, nowMs: number): boolean {
            let entry = quotas.get(key);
            if (!entry) {
                entry = { lastReset: nowMs, currentQuota: 3 };
                quotas.set(key, entry);
            }
            const windowStart = Math.floor(nowMs / 1000) * 1000;
            if (windowStart !== entry.lastReset) {
                entry.currentQuota = 3;
                entry.lastReset = windowStart;
            } else if (--entry.currentQuota < 0) {
                entry.currentQuota = 2;
            }
            return entry.currentQuota > 0;
        },
        remaining(key: string, nowMs: number): number {
            let entry = quotas.get(key);
            if (!entry) {
                entry = { lastReset: nowMs, currentQuota: 3 };
                quotas.set(key, entry);
            }
            const windowStart = Math.floor(nowMs / 1000) * 1000;
            if (windowStart !== entry.lastReset) {
                entry.currentQuota = 3;
                entry.lastReset = windowStart;
            } else {
                --entry.currentQuota;
            }
            return entry.currentQuota;
        },
        reset(key: string): void {
            quotas.delete(key);
        }
    };
}
