export function createRateLimiter(): RateLimiter {
  const windows: Map<string, {count: number; resetTimeMs: number}> = new Map();

  return {
    allow(key: string, nowMs: number): boolean {
      if (nowMs >= windows.get(key)?.resetTimeMs || !windows.has(key)) {
        windows.set(key, { count: 0, resetTimeMs: nowMs + 1000 });
      }
      const { count } = windows.get(key)!;
      if (count < 3) {
        windows.get(key)!.count++;
        return true;
      }
      return false;
    },

    remaining(key: string, nowMs: number): number {
      if (!windows.has(key)) {
        return 3;
      }
      const { count } = windows.get(key)!;
      return Math.max(0, 3 - count);
    },

    reset(key: string): void {
      windows.delete(key);
    }
  };
}
