    cache[key] = { value, expiresAt: nowMs + ttlMs };
  }

  function get(key: string, nowMs: number): unknown {
    const entry = cache[key];
    if (entry && nowMs < entry.expiresAt) {
      return entry.value;
    }
    return undefined;
  }

  function has(key: string, nowMs: number): boolean {
    const entry = cache[key];
    return entry !== undefined && nowMs < entry.expiresAt;
  }

  function deleteKey(key: string): boolean {
    if (cache.hasOwnProperty(key)) {
      delete cache[key];
      return true;
    }
    return false;
  }

  function delete_(key: string): boolean {
    return deleteKey(key);
  }

  function size(nowMs: number): number {
    let count = 0;
    for (const key in cache) {
      if (cache.hasOwnProperty(key) && nowMs < cache[key].expiresAt) {
        count++;
      }
    }
    return count;
  }

  function clear(): void {
    cache = {};
  }

  return {
    set,
    get,
    has,
    delete: delete_,
    size,
    clear
  };
}
