export function createTtlCache(): TtlCache {
  const cache: Record<string, [unknown, number]> = {};

  return {
    set(key: string, value: unknown, nowMs: number, ttlMs: number = 1000): void {
      cache[key] = [value, nowMs + ttlMs];
    },
    get(key: string, nowMs: number): unknown {
      if (key in cache) {
        const [value, expiresAt] = cache[key];
        if (nowMs >= expiresAt) {
          delete cache[key];
          return undefined;
        }
        return value;
      }
      return undefined;
    },
    has(key: string, nowMs: number): boolean {
      if (key in cache) {
        const [value, expiresAt] = cache[key];
        return nowMs < expiresAt;
      }
      return false;
    },
    delete(key: string): boolean {
      if (key in cache) {
        delete cache[key];
        return true;
      }
      return false;
    },
    size(nowMs: number): number {
      let count = 0;
      for (const key of Object.keys(cache)) {
        const [value, expiresAt] = cache[key];
        if (nowMs < expiresAt) count++;
      }
      return count;
    },
    clear(): void {
      cache = {};
    }
  };
}
