export function createEventEmitter() {
  const events: Record<string, ((payload: any) => any)[]> = {};

  return {
    on(event: string, listener: (payload: any) => any): number {
      if (!events[event]) {
        events[event] = [];
      }
      events[event].push(listener);
      return events[event].length;
    },

    once(event: string, listener: (payload: any) => any): number {
      const onceListener = (...args: any[]) => {
        listener(...args);
        this.off(event, onceListener);
      };
      return this.on(event, onceListener);
    },

    off(event: string, listener: (payload: any) => any): boolean {
      if (!events[event]) return false;

      const index = events[event].indexOf(listener);
      if (index === -1) return false;

      events[event].splice(index, 1);
      return true;
    },

    emit(event: string, payload: any): any[] {
      if (!events[event]) return [];

      const listeners = events[event] || [];
      const returns: any[] = [];
      for (const listener of listeners) {
        returns.push(listener(payload));
      }
      return returns;
    },

    listenerCount(event: string): number {
      return events[event]?.length || 0;
    }
  };
}
