export function createEventEmitter(): EventEmitter {
  const listeners: { [key: string]: ((payload: unknown) => unknown)[] } = {};

  return {
    on(event: string, listener: Listener): number {
      if (!listeners[event]) {
        listeners[event] = [];
      }
      listeners[event].push(listener);
      return listeners[event].length;
    },
    once(event: string, listener: Listener): number {
      const onceListener = (...args: unknown[]) => {
        listener(...args);
        this.off(event, onceListener);
      };
      return this.on(event, onceListener);
    },
    off(event: string, listener: Listener): boolean {
      if (!listeners[event]) {
        return false;
      }
      const index = listeners[event].indexOf(listener);
      if (index !== -1) {
        listeners[event].splice(index, 1);
        return true;
      }
      return false;
    },
    emit(event: string, payload: unknown): unknown[] {
      if (!listeners[event]) {
        return [];
      }
      const retVals = listeners[event].map((listener) => listener(payload));
      listeners[event] = listeners[event].filter((_, index) => {
        return !retVals[index];
      });
      return retVals;
    },
    listenerCount(event: string): number {
      return (listeners[event] || []).length;
    }
  };
