export function createTodoApp(): {
    addTodo: (text: string) => { id: number; text: string; completed: boolean };
    getTodo: (id: number) => { id: number; text: string; completed: boolean } | undefined;
    toggleTodo: (id: number) => void;
    deleteTodo: (id: number) => boolean;
    listTodos: () => Array<{ id: number; text: string; completed: boolean }>;
    listCompleted: () => Array<{ id: number; text: string; completed: boolean }>;
    listPending: () => Array<{ id: number; text: string; completed: boolean }>;
    clearCompleted: () => void;
} {
    const todos = [];

    function generateId() {
        return todos.length > 0 ? Math.max(...todos.map(todo => todo.id)) + 1 : 1;
    }

    return {
        addTodo: (text: string) => {
            const id = generateId();
            const newTodo = { id, text, completed: false };
            todos.push(newTodo);
            return newTodo;
        },
        getTodo: (id: number) => todos.find(todo => todo.id === id),
        toggleTodo: (id: number) => {
            const todo = todos.find(todo => todo.id === id);
            if (!todo) return;
            todo.completed = !todo.completed;
        },
        deleteTodo: (id: number) => {
            const todoIndex = todos.findIndex(todo => todo.id === id);
            if (todoIndex === -1) return false;
            todos.splice(todoIndex, 1);
            return true;
        },
        listTodos: () => todos,
        listCompleted: () => todos.filter(todo => todo.completed),
        listPending: () => todos.filter(todo => !todo.completed),
        clearCompleted: () => {
            const completedIds = todos
                .filter(todo => todo.completed)
                .map(todo => todo.id);
            for (const id of completedIds) {
                todos.splice(todos.findIndex(todo => todo.id === id), 1);
            }
        },
    };
}
