export function createTodoApp(): TodoApp {
  const todos: Record<number, Todo> = {};
  let nextId = 1;

  return {
    addTodo(text) {
      if (!text.trim()) {
        return undefined;
      }
      const id = nextId++;
      todos[id] = { id, text, completed: false };
      return { id, text, completed: false };
    },

    getTodo(id) {
      return todos[id];
    },

    toggleTodo(id) {
      if (todos[id]) {
        todos[id].completed = !todos[id].completed;
      }
    },

    deleteTodo(id) {
      if (!todos[id]) return false;
      const { text, completed } = todos[id];
      delete todos[id];
      return true;
    },

    listTodos() {
      return Object.values(todos);
    },

    listCompleted() {
      return Object.values(todos).filter(todo => todo.completed);
    },

    listPending() {
      return Object.values(todos).filter(todo => !todo.completed);
    },

    clearCompleted() {
      const completedTodos = Object.values(todos).filter(todo => todo.completed);
      for (const { id } of completedTodos) {
        delete todos[id];
      }
    }
  };
}

