export function createTtlCache(): {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void;
  get(key: string, nowMs: number): unknown;
  has(key: string, nowMs: number): boolean;
  delete(key: string): boolean;
  size(nowMs: number): number;
  clear(): void;
} {
  const cache: { [key: string]: { value: unknown; expiresAt: number } } = {};

  return {
    set(key: string, value: unknown, nowMs: number, ttlMs = 1000) {
      if (value === undefined) {
        delete cache[key];
      } else {
        const expiresAt = nowMs + ttlMs;
        cache[key] = { value, expiresAt };
      }
    },

    get(key: string, nowMs: number): unknown {
      const entry = cache[key];
      if (!entry || nowMs >= entry.expiresAt) {
        return undefined;
      }
      return entry.value;
    },

    has(key: string, nowMs: number): boolean {
      const entry = cache[key];
      return !!entry && nowMs < entry.expiresAt;
    },

    delete(key: string): boolean {
      if (cache.hasOwnProperty(key)) {
        delete cache[key];
        return true;
      }
      return false;
    },

    size(nowMs: number): number {
      let count = 0;
      for (const key in cache) {
        if (nowMs < cache[key].expiresAt) {
          count++;
        }
      }
      return count;
    },

    clear() {
      cache.clear();
    }
  };
}
