export function createRateLimiter() {
  const windowSizeMs = 1000; // 1 second
  const requestsPerWindow = 3;
  const windows: { [key: string]: [number[], Date] } = {};

  return {
    allow(key: string, nowMs: number) {
      let [counters, lastResetTime] = windows[key] || [[], new Date(0)];

      // Ensure counters are reset at the start of each window
      if (nowMs - lastResetTime.getTime() >= windowSizeMs) {
        counters.length = 0;
      }

      const currentCount = counters.filter((_, idx, self) => nowMs - self[idx] < windowSizeMs).length;

      if (currentCount < requestsPerWindow) {
        counters.push(nowMs);
        return true;
      } else {
        return false;
      }
    },

    remaining(key: string, nowMs: number) {
      let [counters, lastResetTime] = windows[key] || [[], new Date(0)];

      if (nowMs - lastResetTime.getTime() >= windowSizeMs) {
        counters.length = 0;
      }

      return requestsPerWindow - counters.filter((_, idx, self) => nowMs - self[idx] < windowSizeMs).length;
    },

    reset(key: string) {
      delete windows[key];
    }
  };
}
