        state[key] = { windowStart: nowMs, count: 0 };
      }

      const { windowStart, count } = state[key];

      if (nowMs - windowStart >= 1000) {
        state[key] = { windowStart: nowMs, count: 0 };
      }

      if (count < 3) {
        state[key].count++;
        return true;
      }

      return false;
    },
    remaining(key: string, nowMs: number): number {
      const { count } = state[key];
      return 3 - count;
    },
    reset(key: string): void {
      delete state[key];
    }
  };
}
