export function createTodoApp(): TodoApp {
  const todos: Todo[] = [];
  const incompleteIds: Set<number> = new Set();

  return {
    addTodo(text: string): Todo {
      const id = todos.length + 1;
      incompleteIds.add(id);
      return { id, text, completed: false };
    },

    getTodo(id: number): Todo | undefined {
      return todos.find(todo => todo.id === id);
    },

    toggleTodo(id: number): void {
      const todoIndex = todos.findIndex(todo => todo.id === id);
      if (todoIndex !== -1) {
        const todo = todos[todoIndex];
        incompleteIds.delete(todo.id);
        if (!todo.completed) {
          incompleteIds.add(todo.id);
        }
        todo.completed = !todo.completed;
      }
    },

    deleteTodo(id: number): boolean {
      const index = todos.findIndex(todo => todo.id === id);
      if (index !== -1) {
        const removed = todos.splice(index, 1)[0];
        incompleteIds.delete(removed.id);
        return true;
      }
      return false;
    },

    listTodos(): Todo[] {
      return [...todos];
    },

    listCompleted(): Todo[] {
      return todos.filter(todo => todo.completed);
    },

    listPending(): Todo[] {
      return Array.from(incompleteIds).map(id => todos.find(todo => todo.id === id));
    },

    clearCompleted(): void {
      const completedTodos = todos.filter(todo => todo.completed);
      completedTodos.forEach(todo => incompleteIds.delete(todo.id));
      todos.splice(0, todos.length, ...completedTodos);
    }
  };
}

