export function createTtlCache() {
  const cache: { [key: string]: { value: unknown; expiresAt: number } } = {};

  const nowMs = (nowMs: number) => nowMs;
  const DEFAULT_TTL_MS = 1000;

  return {
    set(key: string, value: unknown, nowMs: number, ttlMs?: number) {
      if (!key || typeof value !== 'undefined') {
        cache[key] = { value, expiresAt: nowMs() + (ttlMs ?? DEFAULT_TTL_MS) };
      }
    },
    get(key: string, nowMs: number): unknown {
      const entry = cache[key];
      return entry ? nowMs >= entry.expiresAt ? undefined : entry.value : undefined;
    },
    has(key: string, nowMs: number): boolean {
      const entry = cache[key];
      return entry && nowMs < entry.expiresAt;
    },
    delete(key: string): boolean {
      if (cache[key]) {
        delete cache[key];
        return true;
      }
      return false;
    },
    size(nowMs: number): number {
      return Object.values(cache).filter((entry) => nowMs < entry.expiresAt).length;
    },
    clear(): void {
      cache.clear();
    }
  };
}
