export interface Listener {
  callback: (payload: any) => any;
  isOnce: boolean;
}

export interface EventEmitter {
  on(event: string, listener: (payload: any) => any | null): number;
  once(event: string, listener: (payload: any) => any | null): number;
  off(event: string, listener: (payload: any) => any | null): boolean;
  emit(event: string, payload: any): (any)[] | null;
  listenerCount(event: string): number;
}

export const createEventEmitter = (): EventEmitter => {
  const eventListeners: Map<string, Listener[]> = new Map();
  const listenerCountMap: Map<string, number> = new Map();

  return {
    on(event: string, listener: (payload: any) => any | null): number {
      const listeners = eventListeners.get(event);
      if (!listeners) {
        listeners = [];
        eventListeners.set(event, listeners);
        listenerCountMap.set(event, 0);
      }
      const currentCount = listenerCountMap.get(event);
      listeners.push({
        callback: listener,
        isOnce: false,
      });
      listenerCountMap.set(event, currentCount + 1);
      return currentCount;
    },
    once(event: string, listener: (payload: any) => any | null): number {
      const listeners = eventListeners.get(event);
      if (!listeners) {
        listeners = [];
        eventListeners.set(event, listeners);
        listenerCountMap.set(event, 0);
      }
      const currentCount = listenerCountMap.get(event);
      listeners.push({
        callback: listener,
        isOnce: true,
      });
      listenerCountMap.set(event, currentCount + 1);
      return currentCount;
    },
    off(event: string, listener: (payload: any) => any | null): boolean {
      const listeners = eventListeners.get(event);
      if (!listeners) {
        return false;
      }
      for (let i = 0; i < listeners.length; i++) {
        const currentListener = listeners[i];
        if (currentListener.callback === listener && currentListener.isOnce === (listener as any).isOnce) {
          listeners.splice(i, 1);
          listenerCountMap.set(event, listenerCountMap.get(event) - 1);
          return true;
        }
      }
      return false;
    },
    emit(event: string, payload: any): (any)[] | null {
      const listeners = eventListeners.get(event);
      if (!listeners) {
        return [];
      }
      const results: any[] = [];
      for (let i = 0; i < listeners.length; i++) {
        const listener = listeners[i];
        results.push(listener.callback(payload));
        if (listener.isOnce) {
          listeners.splice(i, 1);
        } else {
          listeners.splice(i, 1);
        }
      }
      return results;
    },
    listenerCount(event: string): number {
      return listenerCountMap.get(event) || 0;
    }
  };
};
