export function createRateLimiter(nowMs: number): {
    allow(key: string, nowMs: number): void;
    remaining(key: string, nowMs: number): number;
    reset(key: string): void;
} {
    const state: Record<string, { start: number; count: number; nextWindowStart: number }> = {};
    return {
        allow: (key: string, nowMs: number): void => {
            const start = state[key]?.start || 0;
            const nextWindowStart = state[key]?.nextWindowStart || 0;
            if (nowMs >= start + 1000) {
                state[key] = {
                    start: nowMs,
                    count: 0,
                    nextWindowStart: nowMs,
                };
            } else {
                state[key] = {
                    start,
                    count: state[key]?.count || 0 + 1,
                    nextWindowStart: nowMs,
                };
            }
        },
        remaining: (key: string, nowMs: number): number => {
            const start = state[key]?.start || 0;
            const nextWindowStart = state[key]?.nextWindowStart || 0;
            const windowElapsed = nowMs - start;
            const fullWindows = Math.floor(windowElapsed / 1000);
            if (nowMs < start + 1000) {
                return state[key]?.count || 0;
            } else {
                return Math.max(0, state[key]?.count || 0 - fullWindows);
            }
        },
        reset: (key: string): void => {
            state[key] = {
                start: nowMs,
                count: 0,
                nextWindowStart: nowMs,
            };
        }
    };
}
