export interface EventListener<T> {
  (event: string, payload: T): void;
}

export interface EventListeners {
  [event: string]: EventListener<any>[];
}

export const createEventEmitter = <T>(initialListeners: EventListeners = {}): EventListeners => {
  const listeners: EventListeners = {
    ...initialListeners
  };

  return {
    ...listeners,
    on(event: string, listener: EventListener<T>): number {
      if (!listeners[event]) {
        listeners[event] = [];
      }

      const count = listeners[event].length;
      listeners[event].push({
        type: 'normal',
        callback: listener,
        payload: undefined
      } as EventListener<any>);

      return count;
    },

    once(event: string, listener: EventListener<T>): number {
      if (!listeners[event]) {
        listeners[event] = [];
      }

      const count = listeners[event].length;
      listeners[event].push({
        type: 'once',
        callback: listener,
        payload: undefined
      } as EventListener<any>);

      return count;
    },

    off(event: string, listener: EventListener<T>): boolean {
      if (!listeners[event]) {
        return false;
      }

      const index = listeners[event].findIndex((l) =>
        l.callback === listener.callback && l.payload === listener.payload
      );

      if (index === -1) {
        return false;
      }

      listeners[event].splice(index, 1);
      return true;
    },

    emit(event: string, payload: any): void {
      if (!listeners[event]) {
        return;
      }

      const listenersArray = listeners[event];
      const results: any[] = [];

      for (const listener of listenersArray) {
        results.push(listener.callback(event, payload));
      }

      console.log('Emitting event:', event, 'with payload:', payload, 'Results:', results);
    },

    listenerCount(event: string): number {
      return listeners[event] ? listeners[event].length : 0;
    }
  };
};
