export function createRateLimiter() {
  const rates = new Map<string, { windowMs: number; remaining: number; lastReset: number }>();

  return {
    allow: (key: string, nowMs: number) => {
      if (!rates.has(key)) {
        rates.set(key, { windowMs: 1000, remaining: 3, lastReset: nowMs });
        return true;
      }

      const { windowMs, remaining, lastReset } = rates.get(key);

      if (nowMs - lastReset >= windowMs) {
        rates.set(key, { windowMs, remaining: 3, lastReset: nowMs });
        return true;
      }

      if (remaining > 0) {
        rates.set(key, { windowMs, remaining: remaining - 1, lastReset: nowMs });
        return true;
      }

      return false;
    },

    remaining: (key: string, nowMs: number) => {
      if (!rates.has(key)) return 0;

      const { remaining } = rates.get(key)!;
      return Math.max(0, remaining);
    },

    reset: (key: string) => {
      if (!rates.has(key)) return;

      rates.set(key, { windowMs: 1000, remaining: 3, lastReset: Date.now() });
    }
  };
}
