import { nowMs } from 'date-fns';

export function createTtlCache(): {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void;
  get(key: string, nowMs: number): unknown;
  has(key: string, nowMs: number): boolean;
  delete(key: string): boolean;
  size(nowMs: number): number;
  clear(): void;
} {

  const cache = {} as Record<string, { value: unknown; expiresAt: number }>;

  return {
    set(key: string, value: unknown, nowMs: number, ttlMs?: number): void {
      if (!ttlMs) {
        ttlMs = 1000;
      }
      const expiresAt = nowMs + ttlMs;
      cache[key] = { value, expiresAt };
    },

    get(key: string, nowMs: number): unknown {
      const entry = cache[key];
      if (!entry) {
        return undefined;
      }
      if (nowMs > entry.expiresAt) {
        return undefined;
      }
      return entry.value;
    },

    has(key: string, nowMs: number): boolean {
      const entry = cache[key];
      if (!entry) {
        return false;
      }
      return nowMs < entry.expiresAt;
    },

    delete(key: string): boolean {
      const entry = cache[key];
      if (!entry) {
        return false;
      }
      delete cache[key];
      return true;
    },

    size(nowMs: number): number {
      let count = 0;
      for (const [key, entry] of Object.entries(cache)) {
        if (nowMs < entry.expiresAt) {
          count++;
        }
      }
      return count;
    },

    clear(): void {
      cache = {};
    }
  };
}
