export function createTtlCache(): TtlCache {

  interface TtlCache {
    set(key: string, value: unknown, nowMs: number, ttlMs?: number): void;
    get(key: string, nowMs: number): unknown;
    has(key: string, nowMs: number): boolean;
    delete(key: string): boolean;
    size(nowMs: number): number;
    clear(): void;
  }

  // Default TTL is 1000ms
  const defaultTtl = 1000;

  function expiresAt(nowMs: number, ttlMs: number): number {
    return nowMs + (ttlMs || defaultTtl);
  }

  function isExpired(nowMs: number, expiresAt: number): boolean {
    return nowMs >= expiresAt;
  }

  const cache: Map<string, { value: unknown; expiresAt: number }> = new Map();

  return {
    set: (key: string, value: unknown, nowMs: number, ttlMs?: number) => {
      const expiresAt = expiresAt(nowMs, ttlMs);
      cache.set(key, { value, expiresAt });
    },
    get: (key: string, nowMs: number) => {
      const entry = cache.get(key);
      if (!entry) return undefined;
      if (isExpired(nowMs, entry.expiresAt)) {
        cache.delete(key);
        return undefined;
      }
      return entry.value;
    },
    has: (key: string, nowMs: number) => {
      const entry = cache.get(key);
      if (!entry) return false;
      if (isExpired(nowMs, entry.expiresAt)) {
        cache.delete(key);
        return false;
      }
      return true;
    },
    delete: (key: string) => {
      const entry = cache.get(key);
      if (!entry) return false;
      if (isExpired(nowMs, entry.expiresAt)) {
        cache.delete(key);
        return true;
      }
      return false;
    },
    size: (nowMs: number) => {
      let count = 0;
      for (const [key, entry] of cache.entries()) {
        if (isExpired(nowMs, entry.expiresAt)) {
          count++;
        }
      }
      return count;
    },
    clear: () => {
      cache.clear();
    }
  };
}
