interface Todo {
  id: number
  text: string
  completed: boolean
}

interface TodoApp {
  addTodo(text: string): Todo
  getTodo(id: number): Todo | undefined
  toggleTodo(id: number): void
  deleteTodo(id: number): boolean
  listTodos(): Todo[]
  listCompleted(): Todo[]
  listPending(): Todo[]
  clearCompleted(): void
}

export function createTodoApp(): TodoApp {
  let nextId = 1
  const todos = new Map<number, Todo>()

  return {
    addTodo(text: string): Todo {
      const todo: Todo = {
        id: nextId,
        text,
        completed: false
      }
      todos.set(todo.id, todo)
      nextId++
      return todo
    },
    getTodo(id: number): Todo | undefined {
      return todos.get(id)
    },
    toggleTodo(id: number): void {
      const todo = todos.get(id)
      if (todo) {
        todo.completed = !todo.completed
      }
    },
    deleteTodo(id: number): boolean {
      if (todos.has(id)) {
        todos.delete(id)
        return true
      }
      return false
    },
    listTodos(): Todo[] {
      return Array.from(todos.values())
    },
    listCompleted(): Todo[] {
      return Array.from(todos.values()).filter(todo => todo.completed)
    },
    listPending(): Todo[] {
      return Array.from(todos.values()).filter(todo => !todo.completed)
    },
    clearCompleted(): void {
      const completedIds = Array.from(todos.entries())
        .filter(([_, todo]) => todo.completed)
        .map(([id]) => id)
      for (const id of completedIds) {
        todos.delete(id)
      }
    }
  }
}
