export function createRateLimiter() {
  const state = new Map<string, number[]>();

  return {
    allow(key: string, nowMs: number): boolean {
      const timestamps = state.get(key) || [];
      const windowStart = nowMs - 1000;
      const pruned = timestamps.filter(ts => ts >= windowStart);
      if (pruned.length < 3) {
        pruned.push(nowMs);
        state.set(key, pruned);
        return true;
      }
      return false;
    },
    remaining(key: string, nowMs: number): number {
      const timestamps = state.get(key) || [];
      const windowStart = nowMs - 1000;
      const pruned = timestamps.filter(ts => ts >= windowStart);
      return Math.max(3 - pruned.length, 0);
    },
    reset(key: string): void {
      state.delete(key);
