function createEventEmitter() {
  const _events = new Map<string, { listener: Function; once: boolean }[]>();

  return {
    on(event: string, listener: Function): number {
      if (!_events.has(event)) {
        _events.set(event, []);
      }
      const listeners = _events.get(event)!;
      listeners.push({ listener, once: false });
      return listeners.length;
    },
    once(event: string, listener: Function): number {
      if (!_events.has(event)) {
        _events.set(event, []);
      }
      const listeners = _events.get(event)!;
      listeners.push({ listener, once: true });
      return listeners.length;
    },
    off(event: string, listener: Function): boolean {
      const listeners = _events.get(event);
      if (!listeners) return false;
      for (let i = 0; i < listeners.length; i++) {
        if (listeners[i].listener === listener) {
          listeners.splice(i, 1);
          return true;
        }
      }
      return false;
    },
    emit(event: string, payload: any): any[] {
      const listeners = _events.get(event);
      if (!listeners) return [];
      const results = [];
      for (let i = 0; i < listeners.length; i++) {
        const listener = listeners[i];
        results.push(listener.listener(payload));
        if (listener.once) {
          listeners.splice(i, 1);
          i--;
        }
      }
      return results;
    },
    listenerCount(event: string): number {
      return _events.get(event)?.length || 0;
    },
  };
}

export { createEventEmitter };
