export type Listener = (payload: unknown) => unknown;

export interface EventEmitter {
  on(event: string, listener: Listener): number;
  once(event: string, listener: Listener): number;
  off(event: string, listener: Listener): boolean;
  emit(event: string, payload: unknown): unknown[];
  listenerCount(event: string): number;
}

export function createEventEmitter(): EventEmitter {
  const _events = new Map<string, { listener: Listener; once: boolean }[]>();

  return {
    on(event: string, listener: Listener): number {
      const listeners = _events.get(event) || [];
      listeners.push({ listener, once: false });
      _events.set(event, listeners);
      return listeners.length;
    },
    once(event: string, listener: Listener): number {
      const listeners = _events.get(event) || [];
      listeners.push({ listener, once: true });
      _events.set(event, listeners);
      return listeners.length;
    },
    off(event: string, listener: Listener): boolean {
      const listeners = _events.get(event);
      if (!listeners) return false;
      const index = listeners.findIndex(
        (entry) => entry.listener === listener
      );
      if (index === -1) return false;
      listeners.splice(index, 1);
      _events.set(event, listeners);
      return true;
    },
    emit(event: string, payload: unknown): unknown[] {
      const listeners = _events.get(event) || [];
      const results: unknown[] = [];
      for (let i = 0; i < listeners.length; i++) {
        const entry = listeners[i];
        const result = entry.listener(payload);
        results.push(result);
        if (entry.once) {
          listeners.splice(i, 1);
          i--; // Adjust index after removal
        }
      }
      return results;
    },
    listenerCount(event: string): number {
      return (_events.get(event) || []).length;
    },
  };
}
