export interface RateLimiter {
  allow(key: string, nowMs: number): boolean;
  remaining(key: string, nowMs: number): number;
  reset(key: string): void;
}

export function createRateLimiter(): RateLimiter {
  const limit = 3;
  const windowMs = 1000;
  const state = new Map<string, { windowStart: number; remaining: number }>();

  return {
    allow(key: string, nowMs: number): boolean {
      let entry = state.get(key);
      if (!entry) {
        entry = { windowStart: nowMs, remaining: limit };
        state.set(key, entry);
      } else {
        const windowEnd = entry.windowStart + windowMs;
        if (nowMs >= windowEnd) {
          entry.windowStart = nowMs;
          entry.remaining = limit;
        }
      }

      if (entry.remaining > 0) {
        entry.remaining--;
        return true;
      }
      return false;
    },
    remaining(key: string, nowMs: number): number {
      const entry = state.get(key);
      if (!entry) {
        return limit;
      }
      const windowEnd = entry.windowStart + windowMs;
      if (nowMs >= windowEnd) {
        return limit;
      }
      return entry.remaining;
    },
    reset(key: string): void {
      state.delete(key);
    },
  };
}
