      return entry && nowMs < entry.expiresAt;
    },
    delete(key) {
      cache.delete(key);
      return true;
    },
    size(nowMs) {
      return Array.from(cache.entries()).filter(
        ([, entry]) => nowMs < entry.expiresAt
      ).length;
    },
    clear() {
