export const createEventEmitter = () => {
  const eventListeners = new Map<string, { fn: Function; isOneTime: boolean }[]>();

  return {
    on(event: string, listener: Function): number {
      eventListeners.set(event, [...eventListeners.get(event) || []]);
      eventListeners.get(event).push({ fn: listener, isOneTime: false });
      return eventListeners.get(event).length;
    },
    once(event: string, listener: Function): number {
      eventListeners.set(event, [...eventListeners.get(event) || []]);
      eventListeners.get(event).push({ fn: listener, isOneTime: true });
      return eventListeners.get(event).length;
    },
    off(event: string, listener: Function): boolean {
      const listeners = eventListeners.get(event) || [];
      const index = listeners.findIndex(l => l.fn === listener);
      if (index !== -1) {
        listeners.splice(index, 1);
        return true;
      }
      return false;
    },
    emit(event: string, payload: any): any[] {
      const listeners = eventListeners.get(event) || [];
      const results = [];
      for (let i = 0; i < listeners.length; i++) {
        const listener = listeners[i];
        results.push(listener.fn(payload));
        if (listener.isOneTime) {
          listeners.splice(i, 1);
        }
      }
      return results;
    },
    listenerCount(event: string): number {
      return eventListeners.get(event) ? eventListeners.get(event).length : 0;
    }
  };
