      counts.set(key, (counts.get(key) || 0) + 1);
      return true;
    },

    remaining: (key: string, nowMs: number): number => {
      return counts.get(key) || 0;
    },

    reset: (key: string): void => {
      counts.delete(key);
    }
  };
