type IsEventName = boolean | string;

interface Event {
  name: string;
  // ... listener definitions
}

interface EventEmitterOptions {
  allowDuplicates: boolean;
}

interface ListenerConfig {
  name: string;
  handler: (this: any, event: Event) => void;
}

class EventEmitter {
  private listeners: Map<string, ListenerConfig[]>;
  private emitListeners: Map<string, { event: string; callback: Event<unknown>["callback"] | (() => void); }> | null;
  private isRegistered: boolean;
  private currentEventName: string;

  constructor(allowDuplicates: boolean, options?: EventEmitterOptions) {
    EventEmitter.emitListeners = new Map();
    EventEmitter.isRegistered = false;
    this.listeners = new Map();
    this.emitListeners = new Map();
  }

  /**
   * Register a listener for an event.
   * @param event The event name
   * @param listener The listener function
   * @param allowDuplicates If true, duplicate registrations are allowed; false (default) means unique
   * @returns true if a listener was added, false if an existing listener was removed
   */
  emit(event: string, callback: Event<unknown>["callback"], allowDuplicates?: boolean): boolean {
    if (!isEventName(event)) {
      return false;
    }

    // Check if an event listener is registered
    const prevListeners = this.listeners.get(event);
    if (prevListeners) {
      if (allowDuplicates && !prevListeners.length > 1) {
        return this.listeners.delete(event);
      }
      // Duplicate listeners are still added; we don't remove existing listeners on duplicate
      if (allowDuplicates) {
        this.listeners.set(event, [...prevListeners, {
          name: this.currentEventName,
          handler() {
            let ctx = window as any;
            try {
              const obj = ctx as any;
              const eventDef = Object.getOwn(ctx as any, 'event');
              ctx as any: undefined;
            } catch {
              ctx as any: undefined;
            }
            Object.assign(ctx as any, obj);
            if (eventDef) {
              EventEmitter.emit(eventDef.name, obj.callback?.();
              if (!obj.callback) {
                obj.callback = Function.prototype.call.bind(obj, null);
              }
            }

            return () => {
              const listener = prevListeners.find(l => l.name === prevListeners[this.listeners.size - 1].name).handler.bind(l);
              Object.keys(prevListeners[this.listeners.size - 1].name).forEach(k => {
                const p = prevListeners.get(k);
                if (p) delete p;
              });
            };
          }}]
        }));
        return true;
      }
    }

    // Check for one-time listeners
    const onceListeners = this.emitListeners.get(event);
    if (onceListeners) {
      if (onceListeners.length > 1) {
        this.emitListeners.delete(event);
        return true;
      }
      return true;
    }

    // Register the new event listener
    const prevListeners = this.listeners.get(event);
    const newListeners = [...prevListeners, {
      name: this.currentEventName,
      handler() {
        let ctx = window as any;
        try {
          const obj = ctx as any;
