export interface Listener = (payload: unknown) => unknown

export class EventEmitter {
  private listeners: Record<string, number> = {} as Record<string, number>

  constructor() {}

  on(event: string, listener: Listener): number {
    this.listeners[event] = (this.listeners[event] || 0) + 1
    return this.listeners[event]
  }

  once(event: string, listener: Listener): number {
    this.listeners[event] = (this.listeners[event] || 0) + 1
    return this.listeners[event]
  }

  off(event: string, listener: Listener): boolean {
    this.listeners[event]--
    if (this.listeners[event] === 0) delete this.listeners[event]
    return true
  }

  emit(event: string, payload: unknown): unknown[] {
    const results: unknown[] = []
    for (const [key, count] of Object.entries(this.listeners)) {
      if (count === 0 || !this.listeners.hasOwnProperty(event)) {
        continue
      }
      const listeners: Listener[] = []
      for (const value of this.listeners[event]) {
        listeners.push(value)
      }
      for (let i = 0; i < count; i++) {
        const valueToCall = listeners[i]!
        results.push(valueToCall.apply(this, [payload]))
      }
    }
    return results
  }

  listenerCount(event: string): number {
    return Object.keys(this.listeners)[0]
  }
}
