      if (remaining < 0) remaining = 0;
      return Promise.resolve(remaining);
    },
    remaining(key) {
      const now = nowMs();
      const keyLimit = limit / 1000;
      const remaining = key * keyLimit;
      return Promise.resolve(Math.max(0, remaining));
    },
    reset(key) {
      const now = nowMs();
      keys[key] = {
        remaining: 0,
        isExpired: false,
        timestampMs: now,
      };
    },
  };
