export function createTtlCache(): {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void
  get(key: string, nowMs: number): unknown
  has(key: string, nowMs: number): boolean
  delete(key: string): boolean
  size(nowMs: number): number
  clear(): void
} {
  // In-memory cache with expiration
  const cache: Map<string, { value: unknown; expiresAt: number }> = new Map();

  // Set entry with ttlMs based on nowMs
  function setEntry(key: string, value: unknown, nowMs: number, ttlMs?: number) {
    const now = nowMs;
    if (ttlMs) {
      const expiresAt = now + Math.max(0, ttlMs);
      cache.set(key, { value, expiresAt });
    } else {
      cache.set(key, { value, expiresAt });
    }
  }

  // Get entry with current nowMs
  function getEntry(key: string, nowMs: number): unknown | undefined {
    return cache.get(key);
  }

  // Get all entries
  function getAllEntries(nowMs: number): Map<string, unknown> {
    return cache;
  }

  // Check if any entry exists at a specific nowMs
  function has(key: string, nowMs: number): boolean {
    return getAllEntries(nowMs).get(key)?.value !== undefined;
  }

  // Delete an entry
  function deleteEntry(key: string) {
    const entries = getAllEntries(nowMs);
    return entries.delete(key);
  }

  // Size cache - only counts live entries
  function size(nowMs: number): number {
    const entries = getAllEntries(nowMs);
    return entries.size;
  }

  // Clear entire cache
  function clear() {
    cache.clear();
  }
}
