export function createEventEmitter() {
  const listeners = new Map<string, ListenerEntry[]>();

  return {
    on(event, listener) {
      if (!listeners.has(event)) {
        listeners.set(event, []);
      }
      const list = listeners.get(event)!;
      list.push({ fn: listener, once: false });
      return list.length;
    },
    once(event, listener) {
      if (!listeners.has(event)) {
        listeners.set(event, []);
      }
      const list = listeners.get(event)!;
      list.push({ fn: listener, once: true });
      return list.length;
    },
    off(event, listener) {
      const list = listeners.get(event);
      if (!list) return false;
      const index = list.findIndex(entry => entry.fn === listener);
      if (index === -1) return false;
      list.splice(index, 1);
      if (list.length === 0) {
        listeners.delete(event);
      }
      return true;
    },
    emit(event, payload) {
      const list = listeners.get(event);
      if (!list) return [];
      const results: any[] = [];
      const snapshot = list.slice();

      for (const entry of snapshot) {
        results.push(entry.fn(payload));
      }

      const toRemove = snapshot.filter(entry => entry.once);
      if (toRemove.length > 0) {
        const remaining = list.filter(entry => !toRemove.includes(entry));
        if (remaining.length === 0) {
          listeners.delete(event);
        } else if (remaining.length !== list.length) {
          listeners.set(event, remaining);
        }
      }

      return results;
    },
    listenerCount(event) {
      return listeners.has(event) ? listeners.get(event)!.length : 0;
    }
  };
