export function createTtlCache(): {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void
  get(key: string, nowMs: number): unknown
  has(key: string, nowMs: number): boolean
  delete(key: string): boolean
  size(nowMs: number): number
  clear(): void
} {
  const entries = new Map<string, { value: unknown; expiresAt: number }>();

  return {
    set(key: string, value: unknown, nowMs: number, ttlMs: number = 1000): void {
      entries.set(key, { value, expiresAt: nowMs + ttlMs });
    },
    get(key: string, nowMs: number): unknown {
      const entry = entries.get(key);
      if (!entry || nowMs >= entry.expiresAt) {
        return undefined;
      }
      return entry.value;
    },
    has(key: string, nowMs: number): boolean {
      const entry = entries.get(key);
      return entry !== undefined && nowMs < entry.expiresAt;
    },
    delete(key: string): boolean {
      return entries.delete(key);
    },
    size(nowMs: number): number {
      let count = 0;
      for (const [, entry] of entries.entries()) {
        if (nowMs < entry.expiresAt) {
          count++;
        }
      }
      return count;
    },
    clear(): void {
      entries.clear();
    }
  };
}

export interface TtlCache {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void
  get(key: string, nowMs: number): unknown
  has(key: string, nowMs: number): boolean
  delete(key: string): boolean
  size(nowMs: number): number
  clear(): void
}

export function createTtlCache(): TtlCache {
  const entries = new Map<string, { value: unknown, expiresAt: number }>();
  const DEFAULT_TTL = 1000;

  return {
    set(key: string, value: unknown, nowMs: number, ttlMs?: number) {
      const actualTtl = ttlMs ?? DEFAULT_TTL;
      const expiresAt = nowMs + actualTtl;
      entries.set(key, { value, expiresAt });
    },
    get(key: string, nowMs: number): unknown {
      const entry = entries.get(key);
      if (!entry || nowMs >= entry.expiresAt) {
        return undefined;
      }
      return entry.value;
    },
    has(key: string, nowMs: number): boolean {
      const entry = entries.get(key);
      if (!entry) {
        return false;
      }
      return nowMs < entry.expiresAt;
    },
    delete(key: string): boolean {
      return entries.delete(key);
    },
    size(nowMs: number): number {
      let count = 0;
      for (const [, entry] of entries.entries()) {
        if (nowMs < entry.expiresAt) {
          count++;
        }
      }
      return count;
    },
    clear(): void {
      entries.clear();
    }
  };
}

