export function createRateLimiter() {
  const MAX_REQUESTS = 3;
  const WINDOW_MS = 1000;

  const state = new Map<string, { windowStart: number; count: number }>();

  function allow(key: string, nowMs: number): boolean {
    const windowStart = Math.floor(nowMs / WINDOW_MS) * WINDOW_MS;

    const existing = state.get(key);
    let count: number;

    if (existing && existing.windowStart === windowStart) {
      count = existing.count;
    } else {
      count = 0;
    }

    if (count < MAX_REQUESTS) {
      state.set(key, { windowStart, count: count + 1 });
      return true;
    }

    return false;
  }

  function remaining(key: string, nowMs: number): number {
    const windowStart = Math.floor(nowMs / WINDOW_MS) * WINDOW_MS;

    const existing = state.get(key);
    if (existing && existing.windowStart === windowStart) {
      return Math.max(0, MAX_REQUESTS - existing.count);
    }
    return MAX_REQUESTS;
  }

  function reset(key: string): void {
    state.delete(key);
  }

  return {
    allow,
    remaining,
    reset
  };
}
