export function createRateLimiter(): RateLimiter {
  const limit = 3;
  const windowMs = 1000;
  const state = new Map<
    string,
    { windowStart: number; count: number }
  >();

  return {
    allow(key: string, nowMs: number): boolean {
      let stateEntry = state.get(key);

      if (!stateEntry || nowMs - stateEntry.windowStart >= windowMs) {
        stateEntry = { windowStart: nowMs, count: 0 };
      }

      if (stateEntry.count < limit) {
        state.set(key, {
          windowStart: stateEntry.windowStart,
          count: stateEntry.count + 1,
        });
        return true;
      }
      return false;
    },

    remaining(key: string, nowMs: number): number {
      const stateEntry = state.get(key);

      if (!stateEntry || nowMs - stateEntry.windowStart >= windowMs) {
        return limit;
      }

      const rem = limit - stateEntry.count;
      return rem < 0 ? 0 : rem;
    },

    reset(key: string): void {
      state.delete(key);
    },
  };
}
