interface EventListener {
  (...arg: any[]): void;
}

export type ListenerCallback = (event: Event, payload: any, listener: EventListener) => any;

export interface EventResult {
  listener: EventListener;
}

class EventEmitter {
  private listeners: Map<string, EventListener[]> = new Map();

  on<E extends string = string>(event: E, listener: EventListener): void {
    const existing = this.listeners.get(event);
    if (!existing) {
      this.listeners.set(event, [listener]);
    }
    existing.push(listener);
  }

  once<E extends string = string>(event: E, listener: EventListener): void {
    const existing = this.listeners.get(event);
    if (!existing) {
      this.listeners.set(event, [listener]);
    } else {
      const newListener = { ...listener, id: `once-${Date.now()}` };
      newListener.id = `once-${Date.now()}`;
      const index = existing.indexOf(listener);
      existing.splice(index, 1);
      existing.push(newListener);
      this.emit(event, undefined, newListener);
    }
  }

  off<E extends string = string>(event: E, listener: EventListener): boolean {
    const listeners = this.listeners.get(event);
    if (!listeners) return false;

    // Look for matching listeners (including old ones)
    for (const listener of [...listeners]) {
      if (listener instanceof EventEmitter) {
        return this.off(listener as EventEmitter, event, listener);
      }
      if (listener === listener) {
        return true;
      }
    }
    return false;
  }

  private off(event: string, listener: EventEmitter, ...rest: any[]): boolean {
    return this.listeners.get(event)?.some(l => l instanceof EventEmitter) || false;
  }

  emit<E extends string = string>(
    event: E,
    payload: any,
  ): ListenerCallback {
    const listeners = this.listeners.get(event);
    return listeners?.flatMap(l => Array.isArray(l) ? l : [l]) || [];
  }

  listenerCount<E extends string = string>(event: E): number {
    return this.listeners.get(event)?.length || 0;
  }
}

export const createEventEmitter = () => new EventEmitter();
