export function createEventEmitter(): EventEmitter {
  const listeners: { event: string; listener: ((payload: unknown) => unknown)[] }[] = [];

  return {
    on(event: string, listener: Listener): number {
      const existing = listeners.find(l => l.event === event);
      if (existing) {
        existing.listener.push(listener);
        return existing.listener.length;
      }
      listeners.push({ event, listener });
      return 1;
    },
    once(event: string, listener: Listener): number {
      const existing = listeners.find(l => l.event === event);
      if (existing) {
        existing.listener.push(listener);
        return existing.listener.length;
      }
      listeners.push({ event, listener });
      return 1;
    },
    off(event: string, listener: Listener): boolean {
      for (let i = listeners.length - 1; i >= 0; i--) {
        const l = listeners[i];
        if (l.event === event) {
          const index = listeners.indexOf(l);
          if (index >= 0) {
            listeners.splice(index, 1);
            return true;
          }
        }
      }
      return false;
    },
    emit(event: string, payload: unknown): unknown[] {
      const result: [Listener, ...unknown[]][] = [];
      const matchingListeners = listeners.filter(l => l.event === event);
      for (let i = matchingListeners.length - 1; i >= 0; i--) {
        result[i] = [matchingListeners[i].listener, ...matchingListeners[i].listener.map(l => l(payload))];
      }
      return result.map(([listener]) => listener);
    },
    listenerCount(event: string): number {
      return listeners.filter(l => l.event === event).length;
    }
  };
}
