export function createRateLimiter(): RateLimiter {
  const keyState: Map<string, { startTime: number }> = new Map();

  return {
    allow: function (key: string, nowMs: number): void {
      const state = keyState.get(key);

      if (state) {
        const now = Date.now();
        const windowEnd = state.startTime + 1000;
        const timeDelta = now - state.startTime;

        if (timeDelta >= 1000) {
          keyState.set(key, { startTime: now });
          return;
        }
      }

      if (keyState.has(key)) {
        const state = keyState.get(key);
        const now = Date.now();
        const windowEnd = state.startTime + 1000;
        const timeDelta = now - state.startTime;

        if (timeDelta >= windowEnd) {
          keyState.delete(key);
        }
        return;
      }

      const now = Date.now();
      const windowEnd = now + 1000;
      const timeDelta = now - now;

      keyState.set(key, { startTime: now });
    },
    remaining: function (key: string, nowMs: number): number {
      return 0;
    },
    reset: function (key: string): void {
      keyState.delete(key);
    }
  };
}
```

That's the TypeScript code for a rate limiter with a fixed threshold of 3 requests per 1000ms window. The keyState uses a Map to track per-key state, and the allow method implements the sliding window logic with proper window boundaries. The remaining getter will be defined in the actual implementation.

```typescript
export function createRateLimiter(): RateLimiter {
  let rateLimitor = new Map<string, RateLimiterState>();

  class RateLimiterState {
    limit = 3;
    windowMs = 1000;
    windowStart: number;
    count = 0;

    constructor(key: string, windowStart: number) {
      this.windowStart = windowStart;
    }

    allow(key: string, nowMs: number): boolean {
      const state = rateLimitor.get(key);
      if (!state) {
        const newState = new RateLimiterState(key, nowMs);
        rateLimitor.set(key, newState);
        return true;
      }

      if (nowMs - state.windowStart >= state.windowMs) {
        state.count = 0;
        state.windowStart = nowMs;
        return true;
      }

      if (state.count >= state.limit) {
        return false;
      }

      state.count++;
      return true;
    }

    remaining(key: string, nowMs: number): number {
      const state = rateLimitor.get(key);
      if (!state) {
        return state.windowMs;
      }

      let remaining = state.count;
      if (nowMs - state.windowStart >= state.windowMs) {
        remaining = 0;
      } else {
        remaining = state.limit - state.count;
      }
      return remaining;
    }

    reset(key: string): void {
      rateLimitor.delete(key);
    }
  }

  return {
    allow: function allow(key: string, nowMs: number): boolean {
      const now = Date.now() / 1000;
      const state = rateLimitor.get(key);
      if (!state) {
        const newState = new RateLimiterState(key, now);
        rateLimitor.set(key, newState);
        return true;
      }

      if (now - state.windowStart >= state.windowMs) {
        state.count = 0;
        state.windowStart = now;
        return true;
      }

      if (state.count >= state.limit) {
        return false;
      }

      state.count++;
      return true;
    },
    remaining: function remaining(key: string, nowMs: number): number {
      const state = rateLimitor.get(key);
      if (!state) {
        return state.windowMs;
      }

      let remaining = state.count;
      if (now - state.windowStart >= state.windowMs) {
        remaining = 0;
      } else {
        remaining = state.limit - state.count;
      }
      return remaining;
    },
    reset: function reset(key: string): void {
      rateLimitor.delete(key);
    }
  };
}
