export const createTodoApp = (): {
  addTodo: (text: string) => { id: number; text: string; completed: boolean }
  getTodo: (id: number) => { id: number; text: string; completed: boolean } | undefined
  toggleTodo: (id: number) => void
  deleteTodo: (id: number) => boolean
  listTodos: () => Array<{ id: number; text: string; completed: boolean }>
  listCompleted: () => Array<{ id: number; text: string; completed: boolean }>
  listPending: () => Array<{ id: number; text: string; completed: boolean }>
  clearCompleted: () => void
} => {
  let todos: Array<{ id: number; text: string; completed: boolean }> = []

  const addTodo = (text: string): { id: number; text: string; completed: boolean } => {
    const id = todos.length ? Math.max(...todos.map(t => t.id)) + 1 : 1
    todos.push({ id, text, completed: false })
    return { id, text, completed: false }
  }

  const getTodo = (id: number): { id: number; text: string; completed: boolean } | undefined => {
    return todos.find(t => t.id === id)
  }

  const toggleTodo = (id: number): void => {
    const todoIndex = todos.findIndex(t => t.id === id)
    if (todoIndex !== -1) {
      todos[todoIndex].completed = !todos[todoIndex].completed
    }
  }

  const deleteTodo = (id: number): boolean => {
    const todoIndex = todos.findIndex(t => t.id === id)
    if (todoIndex >= 0) {
      todos.splice(todoIndex, 1)
      return true
    }
    return false
  }

  const listTodos = (): Array<{ id: number; text: string; completed: boolean }> => [...todos]

  const listCompleted = (): Array<{ id: number; text: string; completed: boolean }> =>
    todos.filter(t => t.completed)

  const listPending = (): Array<{ id: number; text: string; completed: boolean }> =>
    todos.filter(t => !t.completed)

  const clearCompleted = (): void => {
    const completedIdx = todos.findIndex(t => t.completed)
    if (completedIdx >= 0) {
      todos.splice(completedIdx, 1)
    }
  }

  return { addTodo, getTodo, toggleTodo, deleteTodo, listTodos, listCompleted, listPending, clearCompleted }
}
