```typescript
export type Listener = (payload: unknown) => unknown;

export type ListenerCallback = (payload: unknown) => unknown;

interface Listeners {
  [key: string]: ListenerCallback[];
}

export class EventEmitter {
  private listeners: Listeners = {};

  constructor() {}

  on(event: string, listener: ListenerCallback): number {
    if (!this.listeners[event]) {
      this.listeners[event] = [];
    }
    this.listeners[event].push(listener);
    return this.listeners[event].length;
  }

  once(event: string, listener: ListenerCallback): number {
    if (!this.listeners[event]) {
      this.listeners[event] = [];
    }
    this.listeners[event].push(listener);
    return this.listeners[event].length;
  }

  off(
    event: string,
    listener: ListenerCallback | (ListenerCallback & { isOnce: boolean })
  ): boolean {
    if (!this.listeners[event]) {
      return false;
    }
    const index = this.listeners[event].indexOf(listener);
    if (index !== -1) {
      this.listeners[event].splice(index, 1);
      return true;
    }
    return false;
  }

  emit(event: string, payload: unknown): unknown[] {
    if (!this.listeners[event]) {
      return [];
    }
    const results: unknown[] = [];
    const listeners = [...this.listeners[event]];
    listeners.forEach(l => {
      try {
        const result = l(payload);
        results.push(result);
      } catch {
        results.push(undefined);
      }
    });
    return results;
  }

  listenerCount(event: string): number {
    return this.listeners[event]?.length ?? 0;
  }
}
