export function createRateLimiter(): RateLimiter {
  const limit = 3;
  const windowMs = 1000;

  const state: Record<string, { count: number; windowStart: number }> = {};

  return {
    allow(key: string, nowMs: number): boolean {
      const { count, windowStart } = state[key] || { count: 0, windowStart: nowMs };
      const windowStartMs = windowStart;

      if (nowMs - windowStartMs >= windowMs) {
        return true;
      }

      if (count < limit) {
        state[key] = { count: count + 1, windowStart: nowMs };
        return true;
      }

      return false;
    },
    remaining(key: string, nowMs: number): number {
      const { count, windowStart } = state[key] || { count: 0, windowStart: nowMs };
      const windowStartMs = windowStart;
      const remainingMs = nowMs - windowStartMs;

      if (remainingMs >= windowMs) {
        return limit;
      }

      return limit - count;
    },
    reset(key: string): void {
      state[key] = { count: 0, windowStart: nowMs };
    }
  };
}
