function createTtlCache(): {
  set: (key: string, value: unknown, nowMs: number, ttlMs?: number) => void
  get: (key: string, nowMs: number) => unknown
  has: (key: string, nowMs: number) => boolean
  delete: (key: string) => boolean
  size: (nowMs: number) => number
  clear: () => void
} {
  const cache = new Map<string, { value: unknown; expiresAt: number }>()
  const ttlMs = ttlMs ?? 1000

  function set(key: string, value: unknown, nowMs: number, ttlMs?: number) {
    ttlMs = ttlMs ?? 1000
    const expiresAt = nowMs + ttlMs
    cache.set(key, { value, expiresAt })
  }

  function get(key: string, nowMs: number) {
    const entry = cache.get(key)
    if (!entry) {
      return undefined
    }
    if (nowMs >= entry.expiresAt) {
      cache.delete(key)
      return undefined
    }
    return entry.value
  }

  function has(key: string, nowMs: number) {
    const entry = cache.get(key)
    return entry && nowMs >= entry.expiresAt
  }

  function delete(key: string) {
    if (cache.delete(key)) {
      return true
    }
    return false
  }

  function size(nowMs: number) {
    return cache.size.filter(e => nowMs >= e.expiresAt).length
  }

  function clear() {
    cache.clear()
  }

  return { set, get, has, delete, size, clear }
}
