type Listener = (payload: unknown) => unknown

interface EventEmitter {
  on(event: string, listener: Listener): number
  once(event: string, listener: Listener): number
  off(event: string, listener: Listener): boolean
  emit(event: string, payload: unknown): unknown[]
  listenerCount(event: string): number
}

export function createEventEmitter(): EventEmitter {
  const listenersMap: Record<string, { listener: Listener; once: boolean }[]> = {}

  return {
    on(event: string, listener: Listener): number {
      if (!listenersMap[event]) {
        listenersMap[event] = []
      }
      listenersMap[event].push({ listener, once: false })
      return listenersMap[event].length
    },
    once(event: string, listener: Listener): number {
      if (!listenersMap[event]) {
        listenersMap[event] = []
      }
      listenersMap[event].push({ listener, once: true })
      return listenersMap[event].length
    },
    off(event: string, listener: Listener): boolean {
      const eventListeners = listenersMap[event]
      if (!eventListeners) {
        return false
      }
      const index = eventListeners.findIndex(item => item.listener === listener)
      if (index !== -1) {
        eventListeners.splice(index, 1)
        return true
      }
      return false
    },
    emit(event: string, payload: unknown): unknown[] {
      const eventListeners = listenersMap[event]
      if (!eventListeners) {
        return []
      }

      const results: unknown[] = []
      const remainingListeners: { listener: Listener; once: boolean }[] = []

      for (const item of eventListeners) {
        const res = item.listener(payload)
        results.push(res)
        if (!item.once) {
          remainingListeners.push(item)
        }
      }

      listenersMap[event] = remainingListeners
      return results
    },
    listenerCount(event: string): number {
      const eventListeners = listenersMap[event]
      return eventListeners ? eventListeners.length : 0
    }
  }
}

interface RateLimiterState {
  windowStart: number;
  count: number;
}

interface RateLimiter {
  allow(key: string, nowMs: number): boolean;
  remaining(key: string, nowMs: number): number;
  reset(key: string): void;
}

export function createRateLimiter(): RateLimiter {
  const MAX_REQUESTS = 3;
  const WINDOW_MS = 1000;
  const storage = new Map<string, RateLimiterState>();

  return {
    allow(key: string, nowMs: number): boolean {
      let state = storage.get(key);

      if (!state || nowMs >= state.windowStart + WINDOW_MS) {
        state = { windowStart: nowMs, count: 0 };
        storage.set(key, state);
      }

      if (state.count < MAX_REQUESTS) {
        state.count++;
        return true;
      }

      return false;
    },
    remaining(key: string, nowMs: number): number {
      const state = storage.get(key);

      if (!state) {
        return MAX_REQUESTS;
      }

      if (nowMs >= state.windowStart + WINDOW_MS) {
        return MAX_REQUESTS;
      }

      return Math.max(0, MAX_REQUESTS - state.count);
    },
    reset(key: string): void {
      storage.delete(key);
    },
  };
}

