export function createEventEmitter() {
  interface EventStorage {
    listeners: Array<(payload: unknown) => void>;
    onceListeners: Array<(payload: unknown) => void>;
  }

  const events: Map<string, EventStorage> = new Map();

  function getEvent(event: string): EventStorage {
    if (!events.has(event)) {
      events.set(event, { listeners: [], onceListeners: [] });
    }
    return events.get(event)!;
  }

  return {
    on(event: string, listener: (payload: unknown) => void): number {
      const eventStorage = getEvent(event);
      eventStorage.listeners.push(listener);
      return eventStorage.listeners.length + eventStorage.onceListeners.length;
    },

    once(event: string, listener: (payload: unknown) => void): number {
      const eventStorage = getEvent(event);
      eventStorage.onceListeners.push(listener);
      return eventStorage.listeners.length + eventStorage.onceListeners.length;
    },

    off(event: string, listener: (payload: unknown) => void): boolean {
      const eventStorage = events.get(event);
      if (!eventStorage) {
        return false;
      }

      const listenerIndex = eventStorage.listeners.indexOf(listener);
      if (listenerIndex !== -1) {
        eventStorage.listeners.splice(listenerIndex, 1);
        return true;
      }

      const onceListenerIndex = eventStorage.onceListeners.indexOf(listener);
      if (onceListenerIndex !== -1) {
        eventStorage.onceListeners.splice(onceListenerIndex, 1);
        return true;
      }

      return false;
    },

    emit(event: string, payload: unknown): unknown[] {
      const eventStorage = events.get(event);
      if (!eventStorage) {
        return [];
      }

      const results: unknown[] = [];

      const regularListeners = [...eventStorage.listeners];
      for (const listener of regularListeners) {
        results.push(listener(payload));
      }

      eventStorage.onceListeners.forEach(listener => {
        results.push(listener(payload));
      });

      eventStorage.onceListeners = [];

      return results;
    },

    listenerCount(event: string): number {
      const eventStorage = events.get(event);
      if (!eventStorage) {
        return 0;
      }
      return eventStorage.listeners.length + eventStorage.onceListeners.length;
    }
  };
}
