  getTodo(id: number): Todo | undefined
  toggleTodo(id: number): void
  deleteTodo(id: number): boolean
  listTodos(): Todo[]
  listCompleted(): Todo[]
  listPending(): Todo[]
  clearCompleted(): void
}

function createTodoApp(): TodoApp {
  const todos: Todo[] = []
  let nextId = 1

  return {
    addTodo(text: string): Todo {
      const todo: Todo = {
        id: nextId++,
        text,
        completed: false
      }
      todos.push(todo)
      return todo
    },

    getTodo(id: number): Todo | undefined {
      return todos.find(todo => todo.id === id)
    },

    toggleTodo(id: number): void {
      const todo = todos.find(todo => todo.id === id)
      if (todo) {
        todo.completed = !todo.completed
      }
    },

    deleteTodo(id: number): boolean {
      const index = todos.findIndex(todo => todo.id === id)
      if (index !== -1) {
        todos.splice(index, 1)
        return true
      }
      return false
    },

    listTodos(): Todo[] {
      return todos.slice()
    },

    listCompleted(): Todo[] {
      return todos.filter(todo => todo.completed)
    },

    listPending(): Todo[] {
      return todos.filter(todo => !todo.completed)
    },

    clearCompleted(): void {
      const remaining: Todo[] = []
      for (const todo of todos) {
        if (!todo.completed) {
          remaining.push(todo)
        }
      }
      for (let i = 0; i < todos.length; i++) {
        todos[i] = remaining[i]
      }
      todos.length = remaining.length
    }
  }
