interface TtlCache {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void
  get(key: string, nowMs: number): unknown
  has(key: string, nowMs: number): boolean
  delete(key: string): boolean
  size(nowMs: number): number
  clear(): void
}

type CacheEntry = {
  value: unknown
  expiresAt: number
}

function createTtlCache(): TtlCache {
  const cache = new Map<string, CacheEntry>()
  const DEFAULT_TTL = 1000

  return {
    set(key: string, value: unknown, nowMs: number, ttlMs: number = DEFAULT_TTL): void {
      if (ttlMs === 0) {
        cache.set(key, { value, expiresAt: nowMs })
      } else {
        cache.set(key, { value, expiresAt: nowMs + ttlMs })
      }
    },
    get(key: string, nowMs: number): unknown {
      const entry = cache.get(key)
      if (!entry || nowMs >= entry.expiresAt) {
        cache.delete(key)
        return undefined
      }
      return entry.value
    },
    has(key: string, nowMs: number): boolean {
      const entry = cache.get(key)
      if (!entry || nowMs >= entry.expiresAt) {
        cache.delete(key)
        return false
      }
      return true
    },
    delete(key: string): boolean {
      return cache.delete(key)
    },
    size(nowMs: number): number {
      let count = 0
      for (const [key, entry] of cache.entries()) {
        if (nowMs < entry.expiresAt) {
          count++
        } else {
          cache.delete(key)
        }
      }
      return count
    },
    clear(): void {
      cache.clear()
    }
  }
}

export { createTtlCache, TtlCache }
