type ListenerEntry = {
  listener: Listener
  once: boolean
}

function createEventEmitter(): EventEmitter {
  const listenersMap = new Map<string, ListenerEntry[]>()

  function getListeners(event: string): ListenerEntry[] {
    if (!listenersMap.has(event)) {
      listenersMap.set(event, [])
    }
    return listenersMap.get(event)!
  }

  function on(event: string, listener: Listener): number {
    getListeners(event).push({ listener, once: false })
    return getListeners(event).length
  }

  function once(event: string, listener: Listener): number {
    getListeners(event).push({ listener, once: true })
    return getListeners(event).length
  }

  function off(event: string, listener: Listener): boolean {
    const eventListeners = getListeners(event)
    const index = eventListeners.findIndex(entry => entry.listener === listener)
    if (index !== -1) {
      eventListeners.splice(index, 1)
      return true
    }
    return false
  }

  function emit(event: string, payload: unknown): unknown[] {
    const eventListeners = getListeners(event)
    const results: unknown[] = []
    const toRemove: ListenerEntry[] = []

    for (const entry of eventListeners) {
      const result = entry.listener(payload)
      results.push(result)
      if (entry.once) {
        toRemove.push(entry)
      }
    }

    if (toRemove.length > 0) {
      const listenerSet = new Set(toRemove)
      const filtered = eventListeners.filter(entry => !listenerSet.has(entry))
      listenersMap.set(event, filtered)
    }

    return results
  }

  function listenerCount(event: string): number {
    const eventListeners = getListeners(event)
    return eventListeners.length
  }

