export function createRateLimiter(): RateLimiter {
  const limit = 3
  const windowMs = 1000
  const state = new Map<string, { startMs: number; count: number }>()

  return {
    allow(key: string, nowMs: number): boolean {
      const entry = state.get(key)

      // Boundary reset: if nowMs - windowStart >= windowMs, start a fresh window
      if (!entry || (nowMs - entry.startMs >= windowMs)) {
        state.set(key, { startMs: nowMs, count: 0 })
      }

      const updated = state.get(key)!
      if (updated.count < limit) {
        updated.count++
        return true
      }
      return false
    },

    remaining(key: string, nowMs: number): number {
      const entry = state.get(key)

      if (!entry) {
        return limit
      }

      if (nowMs - entry.startMs >= windowMs) {
        return limit
      }

      const remainingQuota = limit - entry.count
      return Math.max(0, remainingQuota)
    },

    reset(key: string): void {
      state.delete(key)
    }
  }
}
