export function createTodoApp(): TodoApp {
  let todos: Todo[] = []
  let nextId = 1

  return {
    addTodo(text: string): Todo {
      const todo: Todo = {
        id: nextId++,
        text,
        completed: false
      }
      todos = [...todos, todo]
      return todo
    },

    getTodo(id: number): Todo | undefined {
      return todos.find(t => t.id === id)
    },

    toggleTodo(id: number): void {
      const idx = todos.findIndex(t => t.id === id)
      if (idx !== -1) {
        todos = [...todos]
        todos[idx] = { ...todos[idx], completed: !todos[idx].completed }
      }
    },

    deleteTodo(id: number): boolean {
      const idx = todos.findIndex(t => t.id === id)
      if (idx === -1) return false
      todos = todos.filter((_, i) => i !== idx)
      return true
    },

    listTodos(): Todo[] {
      return [...todos]
    },

    listCompleted(): Todo[] {
      return todos.filter(t => t.completed)
    },

    listPending(): Todo[] {
      return todos.filter(t => !t.completed)
    },

    clearCompleted(): void {
      const pendingIds = new Set(todos.filter(t => !t.completed).map(t => t.id))
      todos = todos.filter(t => pendingIds.has(t.id))
    }
  }
}
