export function createTtlCache(): TtlCache {
  const entries = new Map<string, { value: unknown; expiresAt: number }>()

  return {
    set(key, value, nowMs, ttlMs?: number): void {
      const ttl = ttlMs ?? 1000
      const expiresAt = ttl === 0 ? nowMs : nowMs + ttl
      entries.set(key, { value, expiresAt })
    },

    get(key, nowMs): unknown {
      const entry = entries.get(key)
      if (!entry) {
        return undefined
      }
      if (nowMs >= entry.expiresAt) {
        entries.delete(key)
        return undefined
      }
      return entry.value
    },

    has(key, nowMs): boolean {
      const entry = entries.get(key)
      if (!entry) {
        return false
      }
      if (nowMs >= entry.expiresAt) {
        entries.delete(key)
        return false
      }
      return true
    },

    delete(key): boolean {
      return entries.delete(key)
    },

    size(nowMs): number {
      let count = 0
      for (const [key, entry] of entries.entries()) {
        if (nowMs < entry.expiresAt) {
          count++
        }
      }
      return count
    },

    clear(): void {
      entries.clear()
    },
  }
}

