export function createEventEmitter() {
  const listeners = new Map<string, { normal: Function[]; once: Function[] }>();

  const addListenersToEvent = (event: string, fn: Function) => {
    if (!listeners.has(event)) {
      listeners.set(event, { normal: [], once: [] });
    }
  };

  const on = (event: string, fn: Function): number => {
    addListenersToEvent(event, fn);
    const eventListeners = listeners.get(event)!;
    eventListeners.normal.push(fn);
    return listeners.size; // Note: Spec asks for "listener count for that event"
  };

