type State = {
  lastResetMs: number;
  requestCount: number;
};

const MAX_REQUESTS_PER_WINDOW = 3;
const WINDOW_MS = 1000;

function createRateLimiter() {
  const state = new Map<string, State>();

  return {
    allow: (key: string, nowMs: number): boolean => {
      if (!state.has(key)) {
        state.set(key, {
          lastResetMs: nowMs,
          requestCount: 0,
        });
      }

      const stateState = state.get(key);

      // Check if window has elapsed and reset if needed
      const timeSinceReset = nowMs - stateState.lastResetMs;
      if (timeSinceReset >= WINDOW_MS) {
        stateState.lastResetMs = nowMs;
        stateState.requestCount = 0;
      }

      if (stateState.requestCount < MAX_REQUESTS_PER_WINDOW) {
        stateState.requestCount++;
        return true;
      }

      return false;
    },

    remaining: (key: string, nowMs: number): number => {
      const stateState = state.get(key);

      if (!stateState) {
        return MAX_REQUESTS_PER_WINDOW;
      }

      const timeSinceReset = nowMs - stateState.lastResetMs;

      if (timeSinceReset >= WINDOW_MS) {
        stateState.lastResetMs = nowMs;
        stateState.requestCount = 0;
      }

      return Math.max(0, MAX_REQUESTS_PER_WINDOW - stateState.requestCount);
    },

    reset: (key: string): void => {
      state.set(key, {
        lastResetMs: 0,
        requestCount: 0,
      });
    },
  };
}

export { createRateLimiter };
