interface RateLimiter {
  allow(key: string, nowMs: number): boolean
  remaining(key: string, nowMs: number): number
  reset(key: string): void
}

interface RateLimiterState {
  windowStart: number
  remaining: number
}

const DEFAULT_LIMIT = 3
const DEFAULT_WINDOW_MS = 1000

interface RateLimiterImpl {
  allow(key: string, nowMs: number): boolean
  remaining(key: string, nowMs: number): number
  reset(key: string): void
}

function createRateLimiter(): RateLimiterImpl {
  const state: Record<string, RateLimiterState> = {}

  function updateWindow(key: string, nowMs: number): void {
    const currentState = state[key]
    if (!currentState) {
      state[key] = {
        windowStart: nowMs,
        remaining: DEFAULT_LIMIT
      }
      return
    }

    const windowElapsed = nowMs - currentState.windowStart

    // Boundary reset: if window has elapsed, start fresh
    if (windowElapsed >= DEFAULT_WINDOW_MS) {
      state[key] = {
        windowStart: nowMs,
        remaining: DEFAULT_LIMIT
      }
    }
  }

  return {
    allow(key: string, nowMs: number): boolean {
      updateWindow(key, nowMs)

      const currentState = state[key]!
      if (currentState.remaining > 0) {
        currentState.remaining -= 1
        return true
      }
      return false
    },

    remaining(key: string, nowMs: number): number {
      updateWindow(key, nowMs)

      return state[key]?.remaining ?? DEFAULT_LIMIT
    },

    reset(key: string): void {
      delete state[key]
    }
  }
}

// Exports:
// - createRateLimiter: returns a RateLimiter instance
// - RateLimiter interface with allow, remaining, reset methods
// - Fixed policy: limit = 3, windowMs = 1000
// - Fixed-window policy per key
// - A key can succeed exactly limit times per window
// - Rejected calls return false and remaining doesn't go below 0
// - Boundary reset rule: if nowMs - windowStart >= windowMs, start fresh window for that key
// - Keys are independent
// - reset(key) removes only that key's state
