export function createTtlCache(): Cache {
  const internalStore = new Map<string, { value: unknown; expiresAt: number }>();

  return {
    set(key: string, value: unknown, nowMs: number, ttlMs: number = 1000) {
      internalStore.set(key, { value, expiresAt: nowMs + ttlMs });
    },
    get(key: string, nowMs: number) {
      const entry = internalStore.get(key);
      if (entry == null) return undefined;
      return nowMs >= entry.expiresAt ? undefined : entry.value;
    },
    has(key: string, nowMs: number) {
      const entry = internalStore.get(key);
      if (entry == null) return false;
      return nowMs < entry.expiresAt;
    },
    delete(key: string) {
      const existed = internalStore.has(key);
      internalStore.delete(key);
      return existed;
    },
    size(nowMs: number) {
      let count = 0;
      for (const entry of internalStore.values()) {
        if (nowMs < entry.expiresAt) {
          count++;
        }
      }
      return count;
    },
    clear() {
      internalStore.clear();
    },
  };
}
