export function createTtlCache(): {
  set: (key: string, value: unknown, nowMs: number, ttlMs?: number) => void;
  get: (key: string, nowMs: number) => unknown;
  has: (key: string, nowMs: number) => boolean;
  delete: (key: string) => boolean;
  size: (nowMs: number) => number;
  clear: () => void;
} {
  const store = new Map<string, { value: unknown; expiresAt: number }>();

  const set: (key: string, value: unknown, nowMs: number, ttlMs?: number) => void = (
    key,
    value,
    nowMs,
    ttlMs
  ) => {
    const expiresAt = nowMs + (ttlMs ?? 1000);
    store.set(key, { value, expiresAt });
  };

  const get: (key: string, nowMs: number) => unknown = (key, nowMs) => {
    const entry = store.get(key);
    if (!entry) {
      return undefined;
    }
    if (nowMs >= entry.expiresAt) {
      store.delete(key);
      return undefined;
    }
    return entry.value;
  };

  const has: (key: string, nowMs: number) => boolean = (key, nowMs) => {
    const entry = store.get(key);
    if (!entry) {
      return false;
    }
    if (nowMs >= entry.expiresAt) {
      store.delete(key);
      return false;
    }
    return true;
  };

  const delete: (key: string) => boolean = (key) => {
    return store.delete(key);
  };

  const size: (nowMs: number) => number = (nowMs) => {
    let count = 0;
    for (const [_, entry] of store) {
      if (nowMs < entry.expiresAt) {
        count++;
      }
    }
    return count;
  };

  const clear: () => void = () => {
    store.clear();
  };

  return { set, get, has, delete, size, clear };
}

