export interface Calculator {
  add(n: number): this;
  subtract(n: number): this;
  multiply(n: number): this;
  divide(n: number): this;
  clear(): this;
  result(): number;
  memoryStore(): this;
  memoryAdd(): this;
  memoryClear(): this;
  memoryRecall(): number;
}

export function createCalculator(): Calculator {
  let currentValue = 0;
  let memoryValue = 0;

  const calculator = {
    add: function (n: number): this {
      currentValue += n;
      return calculator;
    },
    subtract: function (n: number): this {
      currentValue -= n;
      return calculator;
    },
    multiply: function (n: number): this {
      currentValue *= n;
      return calculator;
    },
    divide: function (n: number): this {
      if (n !== 0) {
        currentValue /= n;
        return calculator;
      }
      throw new Error("Division by zero");
    },
    clear: function (): this {
      currentValue = 0;
      return calculator;
    },
    result: function (): number {
      return currentValue;
    },
    memoryStore: function (): this {
      memoryValue = currentValue;
      return calculator;
    },
    memoryAdd: function (): this {
      memoryValue += currentValue;
      // currentValue is NOT changed
      return calculator;
    },
    memoryClear: function (): this {
      memoryValue = 0;
      return calculator;
    },
    memoryRecall: function (): number {
      return memoryValue;
    },
  } as Calculator;

  return calculator;
}
