export function createEventEmitter(): EventEmitter {
  let listeners: Map<string, Array<Listener>> = new Map();
  let onceListeners: Map<string, Array<Listener>> = new Map();

  function on(event: string, listener: Listener): number {
    if (!listeners.has(event)) {
      listeners.set(event, []);
    }
    const eventListeners = listeners.get(event)!;
    eventListeners.push(listener);
    return eventListeners.length;
  }

  function once(event: string, listener: Listener): number {
    if (!onceListeners.has(event)) {
      onceListeners.set(event, []);
    }
    const onceListenersList = onceListeners.get(event)!;
    onceListenersList.push(listener);
    return onceListenersList.length;
  }

  function off(event: string, listener: Listener): boolean {
    const eventListeners = listeners.get(event);
    if (eventListeners) {
      const index = eventListeners.indexOf(listener);
      if (index !== -1) {
        eventListeners.splice(index, 1);
        return true;
      }
    }

    const onceListenersList = onceListeners.get(event);
    if (onceListenersList) {
      const index = onceListenersList.indexOf(listener);
      if (index !== -1) {
        onceListenersList.splice(index, 1);
        return true;
      }
    }

    return false;
  }

  function emit(event: string, payload: unknown): unknown[] {
    const results: unknown[] = [];

    const eventListeners = listeners.get(event);
    if (eventListeners) {
      for (const listener of eventListeners) {
        results.push(listener(payload));
      }
    }

    const onceListenersList = onceListeners.get(event);
    if (onceListenersList) {
      for (let i = 0; i < onceListenersList.length; i++) {
        results.push(onceListenersList[i](payload));
        onceListenersList.splice(i, 1);
      }
    }

    return results;
  }

  function listenerCount(event: string): number {
    const eventListeners = listeners.get(event) || [];
    const onceListenersList = onceListeners.get(event) || [];
    return eventListeners.length + onceListenersList.length;
  }

  return {
    on,
    once,
    off,
    emit,
    listenerCount
  };
}

