export function createRateLimiter(windowMs = 1000, maxRequests = 3) {
  const state: Record<string, { lastRequestAt: number; count: number }> = {};

  function allow(key: string, nowMs: number): boolean {
    if (!(key in state)) {
      state[key] = { lastRequestAt: nowMs, count: 0 };
    }

    const entry = state[key];
    const age = nowMs - entry.lastRequestAt;

    if (age >= windowMs) {
      entry.lastRequestAt = nowMs;
      entry.count = 0;
    }

    entry.count++;
    return entry.count <= maxRequests;
  }

  function remaining(key: string, nowMs: number): number {
    if (!(key in state)) {
      return maxRequests;
    }

    const entry = state[key];
    const age = nowMs - entry.lastRequestAt;

    if (age >= windowMs) {
      return maxRequests;
    }

    return Math.max(0, maxRequests - entry.count);
  }

  function reset(key: string): void {
    delete state[key];
  }

  return { allow, remaining, reset };
}
