      const index = todos.findIndex(todo => todo.id === id)
      if (index === -1) {
        return false
      }
      todos.splice(index, 1)
      return true
    },

    listTodos(): Todo[] {
      return todos
    },

    listCompleted(): Todo[] {
      return todos.filter(todo => todo.completed)
    },

    listPending(): Todo[] {
      return todos.filter(todo => !todo.completed)
    },

    clearCompleted(): void {
      const completedIndex = todos.findIndex(todo => todo.completed)
      if (completedIndex === -1) {
        return
      }
      const completedCount = todos.filter(todo => todo.completed).length
      todos.splice(completedIndex, completedCount)
    }
  }
