      if (n === 0) return calculator;
      current /= n;
      return calculator;
    },
    clear: (): Calculator => {
      current = 0;
      return calculator;
    },
    result: (): number => {
      return current;
    },
    memoryStore: (): Calculator => {
      memory = current;
