export function createRateLimiter(): {
  allow: (key: string, nowMs: number) => boolean
  remaining: (key: string, nowMs: number) => number
  reset: (key: string) => void
} {
  const stores = new Map<string, { count: number; windowStart: number }>()

  const MAX_REQUESTS = 3
  const WINDOW_MS = 1000

  function getStore(key: string, nowMs: number) {
    const store = stores.get(key)

    if (!store) {
      return { count: 0, windowStart: nowMs }
    }

    if (nowMs - store.windowStart >= WINDOW_MS) {
      return { count: 0, windowStart: nowMs }
    }

    return store
  }

  function recordRequest(key: string, nowMs: number) {
    const store = getStore(key, nowMs)
    store.count += 1
    stores.set(key, store)
  }

  return {
    allow: (key: string, nowMs: number) => {
      const store = getStore(key, nowMs)
      return store.count < MAX_REQUESTS
    },
    remaining: (key: string, nowMs: number) => {
      const store = getStore(key, nowMs)
      return Math.max(0, MAX_REQUESTS - store.count)
    },
    reset: (key: string) => {
      stores.delete(key)
    }
  }
}
```

export function createRateLimiter(): RateLimiter {
  const limit = 3
  const windowMs = 1000

  const store = new Map<string, { count: number; windowStart: number }>()

  return {
    allow(key: string, nowMs: number): boolean {
      const windowStart = nowMs - windowMs
      let entry = store.get(key)

      if (!entry || nowMs - entry.windowStart >= windowMs) {
        entry = { count: 0, windowStart }
        store.set(key, entry)
      }

      entry.count++
      if (entry.count <= limit) {
        return true
      }

      store.delete(key)
      return false
    },

    remaining(key: string, nowMs: number): number {
      const windowStart = nowMs - windowMs

      const entry = store.get(key)

      if (!entry || nowMs - entry.windowStart >= windowMs) {
        return limit
      }

      return Math.max(0, limit - entry.count)
    },

    reset(key: string): void {
      store.delete(key)
    }
  }
}

