export function createRateLimiter(): RateLimiter {
  const storage = new Map<string, { count: number; windowStart: number }>();
  const limit = 3;
  const windowMs = 1000;

  return {
    allow(key: string, nowMs: number): boolean {
      let entry = storage.get(key);
      if (!entry) {
        entry = { count: 0, windowStart: nowMs - windowMs };
        storage.set(key, entry);
      }

      const { count, windowStart } = entry;
      const timeSinceStart = nowMs - windowStart;

      if (timeSinceStart >= windowMs) {
        entry.windowStart = nowMs;
        entry.count = 1;
      } else {
        if (count < limit) {
          entry.count++;
          return true;
        }
      }

      return false;
    },
    remaining(key: string, nowMs: number): number {
      let entry = storage.get(key);
      if (!entry) {
        entry = { count: 0, windowStart: nowMs - windowMs };
        storage.set(key, entry);
      }

      const { count, windowStart } = entry;
      const timeSinceStart = nowMs - windowStart;

      if (timeSinceStart >= windowMs) {
        entry.windowStart = nowMs;
        entry.count = 1;
        return limit - entry.count;
      }

      return limit - count;
    },
    reset(key: string): void {
      storage.delete(key);
    }
  };
}

interface RateLimiter {
  allow(key: string, nowMs: number): boolean;
  remaining(key: string, nowMs: number): number;
  reset(key: string): void;
}
