export function createTtlCache(): TtlCache {
  const store = new Map<string, { value: unknown; expiresAt: number }>();

  return {
    set(key, value, nowMs, ttlMs = 1000) {
      const expiresAt = nowMs + ttlMs;
      store.set(key, { value, expiresAt });
    },
    get(key, nowMs) {
      const entry = store.get(key);
      if (!entry) return undefined;
      if (nowMs >= entry.expiresAt) {
        store.delete(key);
        return undefined;
      }
      return entry.value;
    },
    has(key, nowMs) {
      const entry = store.get(key);
      if (!entry) return false;
      return nowMs < entry.expiresAt;
    },
    delete(key) {
      const existed = store.has(key);
      store.delete(key);
      return existed;
    },
    size(nowMs) {
      return Array.from(store.values()).filter(entry => nowMs < entry.expiresAt).length;
    },
    clear() {
      store.clear();
    }
  };
}

