type Listener<T = unknown> = (payload: T) => unknown;
type ListenerRecord = { listener: Listener; once: boolean };

export function createEventEmitter() {
  const events = new Map<string, ListenerRecord[]>();

  function on(event: string, listener: Listener): number {
    const listeners = events.get(event) || [];
    listeners.push({ listener, once: false });
    events.set(event, listeners);
    return listeners.length;
  }

  function once(event: string, listener: Listener): number {
    const listeners = events.get(event) || [];
    listeners.push({ listener, once: true });
    events.set(event, listeners);
    return listeners.length;
  }

  function off(event: string, listener: Listener): boolean {
    const listeners = events.get(event);
    if (!listeners) return false;
    const index = listeners.findIndex((lr) => lr.listener === listener);
    if (index === -1) return false;
    listeners.splice(index, 1);
    events.set(event, listeners);
    return true;
  }

  function emit<T = unknown>(event: string, payload: T): unknown[] {
    const listeners = events.get(event);
    if (!listeners) return [];
    const results: unknown[] = [];
    for (let i = 0; i < listeners.length; i++) {
      const lr = listeners[i];
      const result = lr.listener(payload);
      results.push(result);
      if (lr.once) {
        listeners.splice(i, 1);
        i--;
      }
    }
    if (listeners.length === 0) {
      events.delete(event);
    } else {
      events.set(event, listeners);
    }
    return results;
  }

  function listenerCount(event: string): number {
    const listeners = events.get(event);
    return listeners ? listeners.length : 0;
  }

  return { on, once, off, emit, listenerCount };
}
