```typescript
type Listener = (payload: unknown) => unknown

interface EventEmitter {
  on(event: string, listener: Listener): number
  once(event: string, listener: Listener): number
  off(event: string, listener: Listener): boolean
  emit(event: string, payload: unknown): unknown[]
  listenerCount(event: string): number
}

interface RegisteredListener {
  listener: Listener
  once: boolean
}

export function createEventEmitter(): EventEmitter {
  const events: Map<string, RegisteredListener[]> = new Map()

  return {
    on(event: string, listener: Listener): number {
      if (!events.has(event)) {
        events.set(event, [])
      }
      const listeners = events.get(event)!
      listeners.push({ listener, once: false })
      return listeners.length
    },

    once(event: string, listener: Listener): number {
      if (!events.has(event)) {
        events.set(event, [])
      }
      const listeners = events.get(event)!
      listeners.push({ listener, once: true })
      return listeners.length
    },

    off(event: string, listener: Listener): boolean {
      const listeners = events.get(event)
      if (!listeners) {
        return false
      }
      const index = listeners.findIndex((l) => l.listener === listener)
      if (index === -1) {
        return false
      }
      listeners.splice(index, 1)
      if (listeners.length === 0) {
        events.delete(event)
      }
      return true
    },

    emit(event: string, payload: unknown): unknown[] {
      const listeners = events.get(event)
      if (!listeners) {
        return []
      }
      const results: unknown[] = []
      const onceListeners: Listener[] = []

      for (const { listener, once } of listeners) {
        results.push(listener(payload))
        if (once) {
          onceListeners.push(listener)
        }
      }

      if (onceListeners.length > 0) {
        const remainingListeners = listeners.filter(
          (l) => !onceListeners.includes(l.listener)
        )
        if (remainingListeners.length === 0) {
          events.delete(event)
        } else {
          events.set(event, remainingListeners)
        }
      }

      return results
    },

    listenerCount(event: string): number {
      const listeners = events.get(event)
      return listeners ? listeners.length : 0
    },
  }
}
