export function createEventEmitter() {
  const listeners = new Map<string, Array<{ once: boolean; fn: Function }>>();

  return {
    on(event: string, listener: Function): number {
      if (!listeners.has(event)) {
        listeners.set(event, []);
      }
      listeners.get(event)!.push({ once: false, fn: listener });
      return this.listenerCount(event);
    },

    once(event: string, listener: Function): number {
      if (!listeners.has(event)) {
        listeners.set(event, []);
      }
      listeners.get(event)!.push({ once: true, fn: listener });
      return this.listenerCount(event);
    },

    off(event: string, listener: Function): boolean {
      if (!listeners.has(event)) return false;
      const idx = listeners.get(event)!.findIndex(l => l.fn === listener);
      if (idx === -1) return false;
      listeners.get(event)!.splice(idx, 1);
      return true;
    },

    emit(event: string, ...args: any[]): any[] {
      if (!listeners.has(event)) return [];
      const current = listeners.get(event)!;
      const results: any[] = [];
      for (let i = 0; i < current.length; i++) {
        const { once, fn } = current[i];
        results.push(fn(...args));
        if (once) {
          current.splice(i--, 1);
        }
      }
      return results;
    },

    listenerCount(event: string): number {
      return listeners.get(event)?.length || 0;
    },
  };
