export function createRateLimiter(): RateLimiter {
  const limit = 3;
  const windowMs = 1000;
  const state = new Map<string, { count: number; windowStart: number }>();

  return {
    allow(key: string, nowMs: number): boolean {
      const entry = state.get(key) || { count: 0, windowStart: nowMs };
      const elapsed = nowMs - entry.windowStart;

      if (elapsed >= windowMs) {
        entry.count = 0;
        entry.windowStart = nowMs;
      }

      if (entry.count < limit) {
        entry.count++;
        state.set(key, entry);
        return true;
      }

      return false;
    },

    remaining(key: string, nowMs: number): number {
      const entry = state.get(key) || { count: 0, windowStart: nowMs };
      const elapsed = nowMs - entry.windowStart;

      if (elapsed >= windowMs) {
        return limit;
      }

      return Math.max(0, limit - entry.count);
    },

    reset(key: string): void {
      state.delete(key);
    },
  };
}

interface RateLimiter {
  allow(key: string, nowMs: number): boolean;
  remaining(key: string, nowMs: number): number;
  reset(key: string): void;
