export function createEventEmitter() {
  const listeners = new Map<string, Array<[Function, boolean]>>();

  return {
    /**
     * Register a listener for an event
     */
    on(event: string, listener: Function): number {
      if (!listeners.has(event)) {
        listeners.set(event, []);
      }
      const eventListeners = listeners.get(event)!;
      eventListeners.push([listener, false]);
      return eventListeners.length;
    },

    /**
     * Register a one-time listener for an event
     */
    once(event: string, listener: Function): number {
      if (!listeners.has(event)) {
        listeners.set(event, []);
      }
      const eventListeners = listeners.get(event)!;
      eventListeners.push([listener, true]);
      return eventListeners.length;
    },

    /**
     * Remove a specific listener
     */
    off(event: string, listener: Function): boolean {
      if (!listeners.has(event)) return false;

      const eventListeners = listeners.get(event)!;
      const originalLength = eventListeners.length;

      // Remove the first matching listener
      for (let i = 0; i < eventListeners.length; i++) {
        if (eventListeners[i][0] === listener) {
          eventListeners.splice(i, 1);
          return true;
        }
      }

      return false;
    },

    /**
     * Emit an event and call all listeners
     */
    emit(event: string, payload?: any): any[] {
      if (!listeners.has(event)) return [];

      const eventListeners = listeners.get(event)!;
      const results: any[] = [];
      const remainingIndices: number[] = [];

      // First pass to collect indices of non-consumed listeners
      for (let i = 0; i < eventListeners.length; i++) {
        remainingIndices.push(i);
      }

      // Second pass to execute listeners while removing consumed ones
      for (let i = 0; i < eventListeners.length; i++) {
        const [listener, isOnce] = eventListeners[i];
        const result = listener(payload);
        results.push(result);

        // If it's a once listener, remove it
        if (isOnce) {
          // Find the index in our remaining array and remove it
          for (let j = 0; j < remainingIndices.length; j++) {
            if (remainingIndices[j] === i) {
              remainingIndices.splice(j, 1);
              break;
            }
          }
        }
      }

      // Clean up empty listeners array
      if (remainingIndices.length === 0) {
        listeners.delete(event);
      }

      return results;
    },

    /**
     * Get the number of listeners for an event
     */
    listenerCount(event: string): number {
      return listeners.get(event)?.length || 0;
    }
  };
}
