export function createRateLimiter(): RateLimiter {
  const data = new Map<string, { count: number; windowStart: number }>();
  const limit = 3;
  const windowMs = 1000;

  function now(): number {
    return Date.now();
  }

  function cleanUpExpired(windowStart: number): number {
    const nowMs = now();
    return nowMs - windowStart >= windowMs ? nowMs : windowStart;
  }

  return {
    allow(key: string, nowMs: number): boolean {
      const entry = data.get(key);
      if (!entry) {
        data.set(key, {
          count: 1,
          windowStart: cleanUpExpired(nowMs),
        });
        return true;
      }

      const { count, windowStart } = entry;
      if (nowMs - windowStart >= windowMs) {
        data.set(key, {
          count: 1,
          windowStart: nowMs,
        });
        return true;
      }

      if (count >= limit) return false;

      data.set(key, {
        ...entry,
        count: count + 1,
      });
      return true;
    },

    remaining(key: string, nowMs: number): number {
      const entry = data.get(key);
      if (!entry) return limit;

      const { count, windowStart } = entry;
      if (nowMs - windowStart >= windowMs) return limit;

      return Math.max(0, limit - count);
    },

    reset(key: string): void {
      data.delete(key);
    },
  };
}
