/**
 * Creates an in-memory TTL cache with expiration based on deterministic timestamps.
 */
export function createTtlCache() {
  const store = new Map<string, { value: unknown; expiresAt: number }>();

  /**
   * Sets a key-value pair in the cache with an optional TTL.
   */
  function set(key: string, value: unknown, nowMs: number, ttlMs: number = 1000) {
    const expiresAt = nowMs + (ttlMs ?? 1000);
    store.set(key, { value, expiresAt });
  }

  /**
   * Gets the value for a key if it exists and is not expired.
   */
  function get(key: string, nowMs: number): unknown {
    const entry = store.get(key);
    if (!entry) return undefined;
    if (nowMs >= entry.expiresAt) {
      store.delete(key);
      return undefined;
    }
    return entry.value;
  }

  /**
   * Checks if a key exists and is not expired.
   */
  function has(key: string, nowMs: number): boolean {
    const entry = store.get(key);
    if (!entry) return false;
    if (nowMs >= entry.expiresAt) {
      store.delete(key);
      return false;
    }
    return true;
  }

  /**
   * Deletes a key from the cache.
   */
  function deleteKey(key: string): boolean {
    return store.delete(key);
  }

  /**
   * Returns the number of live entries (non-expired).
   */
  function size(nowMs: number): number {
    let count = 0;
    for (const [key, entry] of store) {
      if (nowMs >= entry.expiresAt) {
        store.delete(key);
      } else {
        count++;
      }
    }
    return count;
  }

  /**
   * Clears all entries.
   */
  function clear() {
    store.clear();
  }

  return {
    set,
    get,
    has,
    delete: deleteKey,
    size,
    clear,
  };
}
