  const store = new Map<string, { value: unknown; expiresAt: number }>();

  return {
    set(key: string, value: unknown, nowMs: number, ttlMs = 1000) {
      const expiresAt = nowMs + (ttlMs === 0 ? 0 : ttlMs);
      store.set(key, { value, expiresAt });
    },

    get(key: string, nowMs: number) {
      const entry = store.get(key);
      if (!entry || nowMs >= entry.expiresAt) {
        store.delete(key);
        return null;
      }
      return entry.value;
    },

    has(key: string, nowMs: number) {
      const entry = store.get(key);
      if (!entry) return false;
      if (nowMs >= entry.expiresAt) {
        store.delete(key);
        return false;
      }
      return true;
    },

    delete(key: string) {
      return store.delete(key);
    },

    size(nowMs: number) {
      let count = 0;
      const expiredKeys: string[] = [];
      for (const [key, entry] of store.entries()) {
        if (nowMs >= entry.expiresAt) {
          expiredKeys.push(key);
        } else {
          count++;
        }
      }
      for (const key of expiredKeys) {
        store.delete(key);
      }
      return count;
    },

    clear() {
      store.clear();
    },
  };
