/**
 * A minimal event system implementation with on, once, off, emit, and listenerCount methods.
 * Supports event registration, one-time listeners, listener removal, and event emission.
 */
export function createEventEmitter<T extends Record<string, unknown>>() {
  // Internal storage for events and listeners
  const events = new WeakMap<string, Set<Function>>();

  /**
   * Subscribe to an event with a listener.
   * @param event - The event name.
   * @param listener - The function to call when the event is triggered.
   * @returns The number of listeners for the event.
   */
  function on(event: string, listener: Function): number {
    if (!events.has(event)) {
      events.set(event, new Set());
    }
    const listeners = events.get(event)!;
    listeners.add(listener);
    return listeners.size;
  }

  /**
   * Subscribe to an event once with a listener.
   * @param event - The event name.
   * @param listener - The function to call when the event is triggered.
   * @returns The number of listeners for the event.
   */
  function once(event: string, listener: Function): number {
    const wrapped = function (...args: unknown[]) {
      off(event, wrapped);
      listener(...args);
    };
    return on(event, wrapped);
  }

  /**
   * Remove a listener from an event.
   * @param event - The event name.
   * @param listener - The function to remove.
   * @returns True if a listener was removed, false if not found.
   */
  function off(event: string, listener: Function): boolean {
    const listeners = events.get(event);
    if (listeners?.delete(listener)) {
      if (listeners.size === 0) {
        events.delete(event);
      }
      return true;
    }
    return false;
  }

  /**
   * Emit an event to all the listeners.
   * @param event - The event name.
   * @param payload - Payload data.
   * @returns The return values from listeners.
   */
  function emit(event: string, ...payload: unknown[]): unknown[] {
    const listeners = events.get(event);
    if (!listeners?.size) {
      return [];
    }
    return Array.from(listeners).map((listener) => listener(...payload));
  }

  /**
   * Number of listeners for an event.
   * @param event - The event name.
   * @returns The number of listeners for the event.
   */
  function listenerCount(event: string): number {
    const listeners = events.get(event);
    return listeners?.size ?? 0;
  }

  /**
   * Create a new event system.
   * @export
   */
  return {
    on,
    once,
    off,
    emit,
    listenerCount,
  };
}

// Default export which is the function
export { createEventEmitter };
